export const enrichJobFromUrl = async (url: string): Promise<Partial<Job>> => {
  const ai = getClient();
  const prompt = `
    I have a job posting link: "${url}".

    You are an expert Talent Scout Agent. Your task is to extract the details of this job posting accurately.

    ### INSTRUCTIONS
    1.  **Analyze URL**: Inspect the URL string for clues (e.g., "linkedin.com/jobs/view/product-designer-google-123"). Often the title and company are in the slug.
    2.  **Search Content**: Use Google Search to find the content of this page. If the direct link is behind a login (like LinkedIn), search for the job title and company found in the URL to find the public listing or a similar listing.
    3.  **Extract Data**:
        - **Job Title**: The specific role (e.g., "Senior Product Designer").
        - **Company**: The organization hiring. **CRITICAL**: Do NOT return "LinkedIn", "Indeed", "Glassdoor", or "Otta" as the company.
        - **Location**: City, Country, or "Remote".
        - **Summary**: A detailed job description. If you can't read the full text, provide a summary based on the snippets available.
        - **Posted Date**: Relative (e.g., "2 days ago") or absolute date.

    ### FALLBACK
    If the page is completely inaccessible and search yields no results, construct the best possible Title and Company from the URL itself, and set the summary to "Could not auto-extract details. Please review link."

    Return JSON matching this schema:
    { "title": "string", "company": "string", "location": "string", "summary": "string", "postedDate": "string" }
  `;

  try {
    const response = await retryWithBackoff<GenerateContentResponse>(() => 
        ai.models.generateContent({ 
            model: "gemini-2.5-flash", 
            contents: prompt, 
            config: { 
                tools: [{ googleSearch: {} }],
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        company: { type: Type.STRING },
                        location: { type: Type.STRING },
                        summary: { type: Type.STRING },
                        postedDate: { type: Type.STRING }
                    }
                }
            } 
        })
    );
    const json = JSON.parse(cleanJsonOutput(response.text || "{}"));

    // Safety check for bad extraction: Ensure company isn't the platform
    if (json.company && ['linkedin', 'indeed', 'glassdoor', 'otta', 'job'].includes(json.company.toLowerCase())) {
        json.company = "Unknown Company";
    }

    return json;
  } catch (e) {
    console.error("Enrichment failed", e);
    return {};
  }
};

