export const enrichJobFromUrl = async (url: string): Promise<Partial<Job>> => {
  const ai = getClient();

  // 1. Attempt local regex parsing first as a fallback/baseline
  let fallbackTitle = "Unknown Role";
  let fallbackCompany = "Unknown Company";
  try {
      const urlObj = new URL(url);
      const pathParts = urlObj.pathname.split(/[-/_]/).filter(p => p.length > 2);
      // Heuristic: If slug looks like "senior-product-designer-google", try to extract
      if (pathParts.length > 0) {
          const meaningful = pathParts.filter(p => !['job', 'view', 'linkedin', 'careers', 'detail', 'uk'].includes(p.toLowerCase()));
          if (meaningful.length > 0) {
              fallbackTitle = meaningful.slice(0, 2).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
              if (meaningful.length > 2) fallbackCompany = meaningful[2].charAt(0).toUpperCase() + meaningful[2].slice(1);
          }
      }
  } catch(e) {}

  const prompt = `
    I have a job posting link: "${url}".

    You are an expert Talent Scout Agent. Your task is to extract the details of this job posting accurately.

    ### INSTRUCTIONS
    1.  **Analyze URL**: Inspect the URL string for clues.
    2.  **Search Content**: Use Google Search to find the content of this page or similar listings if behind a login.
    3.  **Extract Data**:
        - **Job Title**: The specific role.
        - **Company**: The organization hiring. Do NOT use "LinkedIn", "Indeed" etc.
        - **Location**: City, Country, or "Remote".
        - **Summary**: A detailed job description.
        - **Posted Date**: Relative date (e.g. "2 days ago") or today's date if unknown.

    ### OUTPUT FORMAT
    Return valid JSON in a markdown code block matching this schema:
    { "title": "string", "company": "string", "location": "string", "summary": "string", "postedDate": "string" }
  `;

  try {
    const response = await retryWithBackoff<GenerateContentResponse>(() => 
        ai.models.generateContent({ 
            model: "gemini-2.5-flash", 
            contents: prompt, 
            config: { 
                tools: [{ googleSearch: {} }],
                // Removed responseMimeType: "application/json" to allow tools to work correctly
            } 
        })
    );
    const json = JSON.parse(cleanJsonOutput(response.text || "{}"));

    // Fallback if AI fails to get good data
    if (!json.title || json.title === "Unknown" || json.title.includes("Scouting")) json.title = fallbackTitle;
    if (!json.company || json.company === "Detecting..." || ['linkedin', 'indeed', 'glassdoor'].includes(json.company?.toLowerCase())) json.company = fallbackCompany;
    if (!json.postedDate || json.postedDate === "Just now") json.postedDate = new Date().toLocaleDateString();

    return json;
  } catch (e) {
    console.error("Enrichment failed", e);
    // Return regex fallback
    return {
        title: fallbackTitle,
        company: fallbackCompany,
        summary: "Could not auto-extract details. Please edit description manually.",
        postedDate: new Date().toLocaleDateString()
    };
  }
};

