  if (isKanban) {
      return (
        <div 
            className="bg-white p-5 rounded-2xl shadow-sm border border-[#DADCE0] hover:shadow-md transition-all group flex flex-col gap-3 relative cursor-grab active:cursor-grabbing hover:border-[#1a73e8] focus-within:ring-2 focus-within:ring-[#1a73e8] outline-none"
