            <div className="flex items-center gap-2 mt-2 pt-3 border-t border-[#F1F3F4] justify-between">
                {/* Back Button */}
                 <button 
                     onClick={(e) => { e.stopPropagation(); if (status === 'applied') onToggleStatus(job.id, 'saved'); if (status === 'interview') onToggleStatus(job.id, 'applied'); if (status === 'offer') onToggleStatus(job.id, 'interview'); }} 
                     className={`p-2 rounded-full transition-colors flex items-center justify-center ${status === 'saved' ? 'invisible' : 'text-[#70757A] hover:bg-[#F1F3F4]'}`}
                     title="Move Back"
                     disabled={status === 'saved'}
                 >
                    <ArrowLeft size={14} />
