                <button 
                    onClick={(e) => { e.stopPropagation(); onOpenDetail(job); }} 
                    className="px-3 py-1.5 text-xs font-bold text-[#70757A] hover:bg-[#E8F0FE] hover:text-[#1967D2] rounded-md transition-colors bg-[#F1F3F4]"
