                 <button 
                     onClick={(e) => { e.stopPropagation(); if (status === 'saved') onToggleStatus(job.id, 'applied'); if (status === 'applied') onToggleStatus(job.id, 'interview'); if (status === 'interview') onToggleStatus(job.id, 'offer'); }} 
                     className={`p-2 rounded-full transition-colors flex items-center justify-center shadow-sm ${status === 'offer' ? 'invisible' : 'text-white bg-[#202124] hover:bg-[#1a73e8]'}`}
                     title="Move Forward"
                     disabled={status === 'offer'}
