    { "score": number, "verdict": "string", "strategy": "string", "isHighValue": boolean, "isCommuteRisk": boolean, "matchedKeywords": ["string"], "workPattern": "string", "experienceRequired": "string", "salary": "string", "industry": "string" }
  `;

