import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, RotateCcw, RotateCw, Wand2, Search, Type, List, X, Check, Save, FileText, BookOpen } from 'lucide-react';
import { improveCV } from '../services/geminiService';
import { saveCV, getCV } from '../services/firebase';

const CVEditor: React.FC = () => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');

  // AI Panel State
  const [showAiPanel, setShowAiPanel] = useState(false);
  const [showDoc, setShowDoc] = useState(false);
  const [aiMode, setAiMode] = useState<'impact' | 'clarify' | null>(null);
  const [selectedText, setSelectedText] = useState('');
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Initial Load from Firestore
  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded from Cloud');
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            // Default Content if nothing in DB
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: var(--md-sys-color-primary);">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
        }
    };
    loadContent();
  }, []);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        // Save to Firestore
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }
  }, []);

  // Debounced auto-save
  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };

      const el = editorRef.current;
      const rawInputHandler = () => handleInput();

      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const handlePaste = (e: React.ClipboardEvent) => {
      // Allow default paste
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const initAI = (type: 'impact' | 'clarify') => {
    const selection = window.getSelection();
    const text = selection?.toString();

    if (!text || text.trim().length === 0) {
        alert("Please highlight text in your CV first.");
        return;
    }

    setSelectedText(text);
    setAiMode(type);
    setShowAiPanel(true);
    setAiSuggestion('');
    generateSuggestion(text, type);
  };

  const generateSuggestion = async (text: string, type: 'impact' | 'clarify') => {
    setIsAiLoading(true);
    try {
        const promptText = type === 'impact' 
            ? "Identify weak verbs and passive voice. Rewrite this to be action-oriented, using strong power verbs. Return ONLY the rewritten text." 
            : "Clarify this text. Remove fluff, fix grammar, and make it concise and punchy. Return ONLY the rewritten text.";

        const result = await improveCV(text, promptText);
        setAiSuggestion(result);
    } catch (e) {
        setAiSuggestion("Error generating suggestion. Please try again.");
    } finally {
        setIsAiLoading(false);
    }
  };

  const applySuggestion = () => {
      if (editorRef.current && aiSuggestion) {
          editorRef.current.focus();
          document.execCommand('insertText', false, aiSuggestion);
          saveContent();
          closeAiPanel();
      }
  };

  const closeAiPanel = () => {
      setShowAiPanel(false);
      setAiMode(null);
      setSelectedText('');
      setAiSuggestion('');
  };

  return (
    <div className="flex h-[calc(100vh-100px)] relative bg-[#F8F9FA] rounded-[32px] overflow-hidden border border-[#DADCE0] shadow-sm">

        {/* Reference Document Panel */}
        {showDoc && (
             <div className="w-1/2 h-full border-r border-[#DADCE0] bg-white hidden lg:block animate-in slide-in-from-left-4 duration-300">
                 <iframe 
                    src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" 
                    className="w-full h-full" 
                    title="Reference CV"
                 ></iframe>
             </div>
        )}

        {/* Main Editor Area */}
        <div className={`flex-1 flex flex-col h-full transition-all duration-300 ${showAiPanel ? 'mr-0 lg:mr-[320px]' : ''}`}>

            {/* Toolbar - Sticky */}
            <div className="flex-none bg-[#F1F3F4] px-4 sm:px-6 py-4 flex items-center gap-4 border-b border-[#DADCE0] z-10 sticky top-0 overflow-x-auto scrollbar-hide shadow-sm">

                <div className="flex items-center gap-1 bg-white p-1 rounded-full shadow-sm border border-[#DADCE0] shrink-0">
                    <button onClick={() => execCmd('undo')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors" aria-label="Undo"><RotateCcw size={16} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors" aria-label="Redo"><RotateCw size={16} /></button>
                </div>

                <div className="flex items-center gap-1 bg-white p-1 rounded-full shadow-sm border border-[#DADCE0] shrink-0">
                    <button onClick={() => execCmd('formatBlock', 'H2')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] font-bold" title="Heading" aria-label="Heading"><Type size={16} /></button>
                    <button onClick={() => execCmd('bold')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] font-bold" aria-label="Bold"><Bold size={16} /></button>
                    <button onClick={() => execCmd('italic')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] italic" aria-label="Italic"><Italic size={16} /></button>
                    <button onClick={() => execCmd('underline')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] underline" aria-label="Underline"><Underline size={16} /></button>
                </div>

                <div className="flex items-center gap-1 bg-white p-1 rounded-full shadow-sm border border-[#DADCE0] shrink-0">
                    <button onClick={() => execCmd('justifyLeft')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]" aria-label="Align Left"><AlignLeft size={16} /></button>
                    <button onClick={() => execCmd('justifyCenter')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]" aria-label="Align Center"><AlignCenter size={16} /></button>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]" aria-label="List"><List size={16} /></button>
                </div>

                <div className="w-px h-6 bg-[#DADCE0] shrink-0"></div>

                {/* AI Actions */}
                <div className="flex gap-2 shrink-0">
                    <button 
                        onClick={() => initAI('impact')} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#E8F0FE] text-[#1967D2] rounded-full text-sm font-bold hover:shadow-md transition-all hover:bg-[#D2E3FC] whitespace-nowrap"
                    >
                        <Search size={16} /> <span className="hidden sm:inline">Impact Check</span>
                    </button>
                    <button 
                        onClick={() => initAI('clarify')} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#F1F3F4] text-[#202124] rounded-full text-sm font-bold hover:shadow-md transition-all hover:bg-[#DADCE0] whitespace-nowrap"
                    >
                        <Wand2 size={16} /> Clarify
                    </button>
                </div>

