import React, { useState } from 'react';
import { X, Link, FileText, AlignLeft, Building2, Type } from 'lucide-react';

interface AddLinkModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (data: { url?: string; text?: string; title?: string; company?: string }) => void;
}

const AddLinkModal: React.FC<AddLinkModalProps> = ({ isOpen, onClose, onAdd }) => {
  const [mode, setMode] = useState<'link' | 'text'>('link');
  const [url, setUrl] = useState('');

  // Text Mode State
  const [text, setText] = useState('');
  const [manualTitle, setManualTitle] = useState('');
  const [manualCompany, setManualCompany] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'link' && url.trim()) {
      onAdd({ url });
      setUrl('');
      onClose();
    } else if (mode === 'text' && text.trim()) {
      onAdd({ 
          text, 
          title: manualTitle || 'Manual Job Entry', 
          company: manualCompany || 'Unknown Company',
          url: 'Manual Entry' 
      });
      setText('');
      setManualTitle('');
      setManualCompany('');
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 transition-all duration-300">
      <div 
        className="bg-white rounded-[24px] shadow-2xl w-full max-w-lg overflow-hidden border border-[#DADCE0] animate-in fade-in zoom-in-95 duration-200"
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >

        {/* Header with Tabs */}
        <div className="bg-[#F8F9FA] border-b border-[#DADCE0] px-6 py-4 flex items-center justify-between">
            <div className="flex bg-white rounded-full p-1 border border-[#DADCE0] shadow-sm">
                <button 
                    onClick={() => setMode('link')}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-[#1a73e8] ${mode === 'link' ? 'bg-[#1a73e8] text-white shadow-sm' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                    aria-label="Switch to Link mode"
                    aria-pressed={mode === 'link'}
                >
                    <Link size={14} /> Link
                </button>
                <button 
                    onClick={() => setMode('text')}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-[#1a73e8] ${mode === 'text' ? 'bg-[#1a73e8] text-white shadow-sm' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                    aria-label="Switch to Text mode"
                    aria-pressed={mode === 'text'}
                >
                    <FileText size={14} /> Paste Text
                </button>
            </div>
            <button 
                onClick={onClose} 
                className="p-2 hover:bg-[#E8EAED] rounded-full text-[#5F6368] transition-colors focus:outline-none focus:ring-2 focus:ring-[#1a73e8]"
                aria-label="Close modal"
            >
                <X size={20} />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6">
          <h2 id="modal-title" className="sr-only">Add New Job</h2>

          {mode === 'link' ? (
              <div className="mb-6">
                <label htmlFor="job-url" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Job URL</label>
                <div className="relative">
                    <Link className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={18} />
                    <input 
                        id="job-url"
                        type="url" 
                        value={url}
                        onChange={(e) => setUrl(e.target.value)}
                        placeholder="https://linkedin.com/jobs/..." 
                        className="w-full pl-10 pr-4 py-3 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-[#202124] transition-all"
                        autoFocus
                        required
                    />
                </div>
                <p className="text-xs text-[#70757A] mt-2 ml-1">Best for public links (Indeed, Company Sites).</p>
              </div>
          ) : (
              <div className="space-y-4 mb-6">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label htmlFor="manual-title" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Job Title</label>
                        <div className="relative">
                            <Type className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={16} />
                            <input 
                                id="manual-title"
                                type="text" 
                                value={manualTitle}
                                onChange={(e) => setManualTitle(e.target.value)}
                                placeholder="e.g. Senior Designer" 
                                className="w-full pl-9 pr-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-sm font-medium"
                            />
                        </div>
                      </div>
                      <div>
                        <label htmlFor="manual-company" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Company</label>
                        <div className="relative">
                            <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={16} />
                            <input 
                                id="manual-company"
                                type="text" 
                                value={manualCompany}
                                onChange={(e) => setManualCompany(e.target.value)}
                                placeholder="e.g. Google" 
                                className="w-full pl-9 pr-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-sm font-medium"
                            />
                        </div>
                      </div>
                  </div>

                  <div>
                    <label htmlFor="manual-desc" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Job Description</label>
                    <textarea 
                        id="manual-desc"
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder="Paste the full job description here..." 
                        className="w-full p-4 h-48 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-[#202124] transition-all resize-none text-sm leading-relaxed"
                        autoFocus
                        required
                    />
                  </div>
              </div>
          )}

          <div className="flex justify-end gap-3 pt-4 border-t border-[#F1F3F4]">
            <button 
                type="button" 
                onClick={onClose}
                className="px-5 py-2.5 text-sm font-bold text-[#5F6368] hover:bg-[#F1F3F4] rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-[#5F6368]"
            >
                Cancel
            </button>
            <button 
                type="submit"
                className="px-6 py-2.5 text-sm font-bold text-white bg-[#1a73e8] hover:bg-[#1557B0] rounded-full transition-colors shadow-sm flex items-center gap-2 focus:outline-none focus:ring-4 focus:ring-[#D2E3FC]"
            >
                {mode === 'link' ? <Link size={16} /> : <FileText size={16} />}
                {mode === 'link' ? 'Scout URL' : 'Analyze Text'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddLinkModal;

import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy, Plus } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  // Filter jobs by status - Using uniform neutral background
  const columns: { id: Job['status'], title: string, icon: React.ReactNode, bgClass: string, accentColor: string }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#1a73e8]' },
      { id: 'applied', title: 'Applied', icon: <Send size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#1a73e8]' },
      { id: 'interview', title: 'Interview', icon: <Users size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#F4B400]' },
      { id: 'offer', title: 'Offer', icon: <Trophy size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#0F9D58]' },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex flex-col h-full min-h-[750px]">

      {/* HEADER WITH ADD ACTION */}
      <div className="mb-8 mx-2 shrink-0 flex justify-between items-center">
          <h2 className="text-2xl font-bold text-[#202124]">Application Pipeline</h2>
          <button 
              onClick={onOpenAddModal}
              className="flex items-center gap-2 px-6 py-2.5 bg-[#1a73e8] text-white rounded-full font-bold text-sm hover:bg-[#1557B0] transition-all shadow-sm active:scale-95 focus:outline-none focus:ring-4 focus:ring-[#D2E3FC]"
              aria-label="Add new job via Link or Text"
          >
              <Plus size={18} />
              <span className="hidden sm:inline">Add Job</span>
              <span className="sm:hidden">Add</span>
          </button>
      </div>

      {/* BOARD COLUMNS */}
      <div className="flex-1 flex gap-6 overflow-x-auto pb-6 items-stretch px-2 custom-scrollbar snap-x snap-mandatory">
        {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className={`flex flex-col h-full min-w-[85vw] sm:min-w-[340px] rounded-[32px] p-4 transition-colors ${col.bgClass} border border-[#DADCE0] snap-center`}
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className={`flex items-center justify-between mb-6 px-4 pt-2 ${col.accentColor}`}>
                        <h3 className="font-bold text-lg flex items-center gap-2">
                            {col.icon} {col.title}
                        </h3>
                        <span className="text-xs bg-white border border-[#DADCE0] px-2.5 py-1 rounded-full font-bold shadow-sm text-[#5F6368]">{colJobs.length}</span>
                    </div>

                    <div className="flex-1 space-y-4 overflow-y-auto pr-1 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="text-center py-20 border-2 border-dashed border-[#DADCE0] rounded-[24px]">
                                <p className="text-sm font-medium text-[#70757A]">Drag jobs here</p>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className="cursor-grab active:cursor-grabbing"
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
        })}
      </div>
    </div>
  );
};

export default KanbanBoard;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, Check, ChevronDown } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;
  const applyUrl = job.url || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 transition-all duration-300">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose}></div>

      {/* Surface */}
      <div className="relative bg-[#F8F9FA] w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[28px] overflow-hidden border border-white/50 animate-in fade-in zoom-in-95 duration-200">

        {/* Header (Fixed) */}
        <div className="flex items-center justify-between px-6 py-6 sm:px-8 bg-white border-b border-[#DADCE0] shrink-0">
           <div className="flex items-center gap-5 flex-1 mr-4 sm:mr-8">
              <div className="w-14 h-14 bg-[#E8F0FE] text-[#1967D2] rounded-2xl hidden sm:flex items-center justify-center shadow-sm shrink-0">
                  <Briefcase size={28} />
              </div>
              <div className="flex-1 min-w-0">
                  {isEditingTitle ? (
                      <input 
                        type="text" 
                        value={editedTitle}
                        onChange={(e) => setEditedTitle(e.target.value)}
                        onBlur={handleSaveTitle}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                        className="text-xl sm:text-2xl font-bold text-[#202124] w-full border-b-2 border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                      />
                  ) : (
                      <h2 
                        onClick={() => setIsEditingTitle(true)}
                        className="text-xl sm:text-2xl font-bold text-[#202124] leading-tight truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-full"
                        title="Click to edit title"
                      >
                        {job.title} <Edit2 size={16} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" />
                      </h2>
                  )}

                  {isEditingCompany ? (
                      <input 
                        type="text" 
                        value={editedCompany}
                        onChange={(e) => setEditedCompany(e.target.value)}
                        onBlur={handleSaveCompany}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveCompany()}
                        className="text-sm text-[#5F6368] font-medium mt-1 w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                      />
                  ) : (
                      <p 
                        onClick={() => setIsEditingCompany(true)}
                        className="text-sm text-[#5F6368] font-medium mt-1 truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-fit"
                        title="Click to edit company"
                      >
                          {job.company} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" />
                      </p>
                  )}
              </div>
           </div>
           <button onClick={onClose} className="w-10 h-10 flex items-center justify-center hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors shrink-0">
             <X size={24} />
           </button>
        </div>

        {/* Unified Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 sm:p-8 bg-white">
            <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-12">

                {/* Main Content Area (Left) */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs */}
                    <div className="flex items-center gap-2 mb-8 bg-[#F1F3F4] p-1 rounded-full w-fit border border-[#DADCE0]">
                        <button 
                            onClick={() => setActiveTab('brief')} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'brief' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <FileText size={14} /> Job Details
                        </button>
                        <button 
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'strategy' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <Sparkles size={14} /> Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="prose prose-slate max-w-none text-[#202124]">
                            {/* Tags */}
                            <div className="mb-8 flex flex-wrap gap-3">
                                {job.seniorityScore && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{job.seniorityScore}</span>
                                )}
                                {analysis?.salary && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis.salary}</span>
                                )}
                                {analysis?.workPattern && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis.workPattern}</span>
                                )}
                                {analysis?.industry && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis.industry}</span>
