import React, { useState } from 'react';
import { X, Link, FileText, AlignLeft, Building2, Type } from 'lucide-react';

interface AddLinkModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (data: { url?: string; text?: string; title?: string; company?: string }) => void;
}

const AddLinkModal: React.FC<AddLinkModalProps> = ({ isOpen, onClose, onAdd }) => {
  const [mode, setMode] = useState<'link' | 'text'>('link');
  const [url, setUrl] = useState('');

  // Text Mode State
  const [text, setText] = useState('');
  const [manualTitle, setManualTitle] = useState('');
  const [manualCompany, setManualCompany] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'link' && url.trim()) {
      onAdd({ url });
      setUrl('');
      onClose();
    } else if (mode === 'text' && text.trim()) {
      onAdd({ 
          text, 
          title: manualTitle || 'Manual Job Entry', 
          company: manualCompany || 'Unknown Company',
          url: 'Manual Entry' 
      });
      setText('');
      setManualTitle('');
      setManualCompany('');
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 transition-all duration-300">
      <div 
        className="bg-white rounded-[24px] shadow-2xl w-full max-w-lg overflow-hidden border border-[#DADCE0] animate-in fade-in zoom-in-95 duration-200"
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
      >

        {/* Header with Tabs */}
        <div className="bg-[#F8F9FA] border-b border-[#DADCE0] px-6 py-4 flex items-center justify-between">
            <div className="flex bg-white rounded-full p-1 border border-[#DADCE0] shadow-sm">
                <button 
                    onClick={() => setMode('link')}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-[#1a73e8] ${mode === 'link' ? 'bg-[#1a73e8] text-white shadow-sm' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                    aria-label="Switch to Link input mode"
                    aria-pressed={mode === 'link'}
                >
                    <Link size={14} /> Link
                </button>
                <button 
                    onClick={() => setMode('text')}
                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-2 focus:outline-none focus:ring-2 focus:ring-[#1a73e8] ${mode === 'text' ? 'bg-[#1a73e8] text-white shadow-sm' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                    aria-label="Switch to Text input mode"
                    aria-pressed={mode === 'text'}
                >
                    <FileText size={14} /> Paste Text
                </button>
            </div>
            <button 
                onClick={onClose} 
                className="p-2 hover:bg-[#E8EAED] rounded-full text-[#5F6368] transition-colors focus:outline-none focus:ring-2 focus:ring-[#1a73e8]"
                aria-label="Close modal"
            >
                <X size={20} />
            </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6">
          <h2 id="modal-title" className="sr-only">Add New Job</h2>

          {mode === 'link' ? (
              <div className="mb-6">
                <label htmlFor="job-url" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Job URL</label>
                <div className="relative">
                    <Link className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={18} />
                    <input 
                        id="job-url"
                        type="url" 
                        value={url}
                        onChange={(e) => setUrl(e.target.value)}
                        placeholder="https://linkedin.com/jobs/..." 
                        className="w-full pl-10 pr-4 py-3 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-[#202124] transition-all"
                        autoFocus
                        required
                    />
                </div>
                <p className="text-xs text-[#70757A] mt-2 ml-1">Best for public links (Indeed, Company Sites).</p>
              </div>
          ) : (
              <div className="space-y-4 mb-6">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      <div>
                        <label htmlFor="manual-title" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Job Title</label>
                        <div className="relative">
                            <Type className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={16} />
                            <input 
                                id="manual-title"
                                type="text" 
                                value={manualTitle}
                                onChange={(e) => setManualTitle(e.target.value)}
                                placeholder="e.g. Senior Designer" 
                                className="w-full pl-9 pr-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-sm font-medium"
                            />
                        </div>
                      </div>
                      <div>
                        <label htmlFor="manual-company" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Company</label>
                        <div className="relative">
                            <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={16} />
                            <input 
                                id="manual-company"
                                type="text" 
                                value={manualCompany}
                                onChange={(e) => setManualCompany(e.target.value)}
                                placeholder="e.g. Google" 
                                className="w-full pl-9 pr-4 py-2.5 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-sm font-medium"
                            />
                        </div>
                      </div>
                  </div>

                  <div>
                    <label htmlFor="manual-desc" className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Job Description</label>
                    <textarea 
                        id="manual-desc"
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder="Paste the full job description here..." 
                        className="w-full p-4 h-48 bg-[#F8F9FA] border border-[#DADCE0] rounded-xl focus:border-[#1a73e8] focus:ring-1 focus:ring-[#1a73e8] outline-none text-[#202124] transition-all resize-none text-sm leading-relaxed"
                        autoFocus
                        required
                    />
                  </div>
              </div>
          )}

          <div className="flex justify-end gap-3 pt-4 border-t border-[#F1F3F4]">
            <button 
                type="button" 
                onClick={onClose}
                className="px-5 py-2.5 text-sm font-bold text-[#5F6368] hover:bg-[#F1F3F4] rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-[#5F6368]"
            >
                Cancel
            </button>
            <button 
                type="submit"
                className="px-6 py-2.5 text-sm font-bold text-white bg-[#1a73e8] hover:bg-[#1557B0] rounded-full transition-colors shadow-sm flex items-center gap-2 focus:outline-none focus:ring-4 focus:ring-[#D2E3FC]"
            >
                {mode === 'link' ? <Link size={16} /> : <FileText size={16} />}
                {mode === 'link' ? 'Scout URL' : 'Analyze Text'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddLinkModal;

import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy, Plus } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  // Filter jobs by status - Using uniform neutral background
  const columns: { id: Job['status'], title: string, icon: React.ReactNode, bgClass: string, accentColor: string }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#1a73e8]' },
      { id: 'applied', title: 'Applied', icon: <Send size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#1a73e8]' },
      { id: 'interview', title: 'Interview', icon: <Users size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#F4B400]' },
      { id: 'offer', title: 'Offer', icon: <Trophy size={18} />, bgClass: 'bg-[#F8F9FA]', accentColor: 'text-[#0F9D58]' },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex flex-col h-full min-h-[750px]">

      {/* HEADER WITH ADD ACTION */}
      <div className="mb-8 mx-2 shrink-0 flex justify-between items-center">
          <h2 className="text-2xl font-bold text-[#202124]">Application Pipeline</h2>
          <button 
              onClick={onOpenAddModal}
              className="flex items-center gap-2 px-6 py-2.5 bg-[#1a73e8] text-white rounded-full font-bold text-sm hover:bg-[#1557B0] transition-all shadow-sm active:scale-95 focus:outline-none focus:ring-4 focus:ring-[#D2E3FC]"
              aria-label="Add new job via Link or Text"
          >
              <Plus size={18} />
              <span className="hidden sm:inline">Add Job</span>
              <span className="sm:hidden">Add</span>
          </button>
      </div>

      {/* BOARD COLUMNS */}
      <div className="flex-1 flex gap-6 overflow-x-auto pb-6 items-stretch px-2 custom-scrollbar snap-x snap-mandatory">
        {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className={`flex flex-col h-full min-w-[85vw] sm:min-w-[340px] rounded-[32px] p-4 transition-colors ${col.bgClass} border border-[#DADCE0] snap-center`}
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className={`flex items-center justify-between mb-6 px-4 pt-2 ${col.accentColor}`}>
                        <h3 className="font-bold text-lg flex items-center gap-2">
                            {col.icon} {col.title}
                        </h3>
                        <span className="text-xs bg-white border border-[#DADCE0] px-2.5 py-1 rounded-full font-bold shadow-sm text-[#5F6368]">{colJobs.length}</span>
                    </div>

                    <div className="flex-1 space-y-4 overflow-y-auto pr-1 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="text-center py-20 border-2 border-dashed border-[#DADCE0] rounded-[24px]">
                                <p className="text-sm font-medium text-[#70757A]">Drag jobs here</p>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className="cursor-grab active:cursor-grabbing"
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
        })}
      </div>
    </div>
  );
};

export default KanbanBoard;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, FileText, TrendingUp, Trash2, Clock, Zap, Bookmark, Archive } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);
  const applyUrl = job.url || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleKeyDown = (e: React.KeyboardEvent, action: () => void) => {
      if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          action();
      }
  };

  if (isKanban) {
      return (
        <div 
            className="bg-white p-4 rounded-2xl shadow-sm border border-[#DADCE0] hover:shadow-md transition-all group flex flex-col gap-3 relative cursor-grab active:cursor-grabbing hover:border-[#1a73e8] focus-within:ring-2 focus-within:ring-[#1a73e8] outline-none"
            tabIndex={0}
            role="button"
            onKeyDown={(e) => handleKeyDown(e, () => onOpenDetail(job))}
        >
            <div className="flex justify-between items-start gap-2">
                <h4 onClick={() => onOpenDetail(job)} className="font-bold text-sm text-[#202124] leading-snug line-clamp-2 cursor-pointer hover:text-[#1a73e8] transition-colors">{job.title}</h4>
                {analysis && (
                    <div className={`shrink-0 w-2 h-2 rounded-full ${analysis.isHighValue ? 'bg-[#34A853]' : 'bg-[#DADCE0]'}`} title={analysis.isHighValue ? "High Value" : "Standard"}></div>
                )}
            </div>

            <p className="text-xs font-medium text-[#5F6368] line-clamp-1">{job.company}</p>

            <div className="flex items-center gap-2 mt-2 pt-3 border-t border-[#F1F3F4]">
                <button 
                    onClick={(e) => { e.stopPropagation(); onOpenDetail(job); }} 
                    className="w-full py-2 text-xs font-bold text-[#70757A] hover:bg-[#E8F0FE] hover:text-[#1967D2] rounded-md transition-colors bg-[#F1F3F4] flex items-center justify-center gap-2 focus:outline-none focus:ring-2 focus:ring-[#1a73e8]"
                    title="View Details"
                >
                    <FileText size={14} /> View Details
                </button>
            </div>
        </div>
      );
  }

  return (
    <div className={`bg-white rounded-3xl p-8 shadow-sm hover:shadow-lg transition-all duration-300 border border-[#DADCE0] relative group overflow-hidden ${status === 'archived' ? 'opacity-50 grayscale' : ''}`}>

      {/* Top Right Actions */}
      <div className="absolute top-6 right-6 flex items-center gap-2">
         <button 
            onClick={() => onDelete(job.id)} 
            className="p-2.5 text-[#70757A] hover:text-[#DB4437] hover:bg-[#FCE8E6] rounded-full transition-all focus:outline-none focus:ring-2 focus:ring-[#DB4437]" 
            title={status === 'archived' ? "Delete Permanently" : "Archive"}
            aria-label="Delete or Archive Job"
         >
            {status === 'archived' ? <Trash2 size={18} /> : <Archive size={18} />}
         </button>

         {status !== 'archived' && (
             <button 
                onClick={() => onToggleStatus(job.id, status)}
                className={`p-2.5 rounded-full transition-all border focus:outline-none focus:ring-2 focus:ring-[#1a73e8] ${isSavedOrBetter 
                    ? 'bg-[#1a73e8] text-white border-[#1a73e8] shadow-md' 
                    : 'bg-white text-[#70757A] border-[#DADCE0] hover:border-[#5F6368]'}`}
                aria-label={isSavedOrBetter ? "Unsave Job" : "Save Job"}
             >
                 <Bookmark size={18} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}
      </div>

      <div className="flex flex-col md:flex-row gap-8">
          {/* Score Circle */}
          <div className="shrink-0">
             {analysis ? (
                 <div className="w-20 h-20 rounded-full bg-[#E8F0FE] text-[#1967D2] flex flex-col items-center justify-center border-4 border-white shadow-sm ring-1 ring-[#D2E3FC]">
                    <span className="text-2xl font-black tracking-tight">{analysis.score}</span>
                    <span className="text-[10px] font-bold uppercase tracking-wider opacity-70">Score</span>
                 </div>
             ) : (
                 <div className="w-20 h-20 rounded-full bg-[#F1F3F4] border-4 border-white shadow-sm flex items-center justify-center animate-pulse">
                     <span className="text-[10px] font-bold text-[#70757A]">SCAN</span>
                 </div>
             )}
          </div>

          <div className="flex-1 pr-12">
             <div 
                className="cursor-pointer group/title focus:outline-none focus:ring-2 focus:ring-[#1a73e8] rounded-lg p-1 -m-1" 
                onClick={() => onOpenDetail(job)}
                onKeyDown={(e) => handleKeyDown(e, () => onOpenDetail(job))}
                tabIndex={0}
                role="button"
                aria-label={`View details for ${job.title} at ${job.company}`}
             >
                <h3 className="text-2xl font-bold text-[#202124] group-hover/title:text-[#1a73e8] transition-colors leading-tight mb-2 flex items-start gap-2">
                    {job.title}
                    {job.isRelatedDiscovery && <Zap size={18} className="text-[#F4B400] fill-[#F4B400] mt-1" />}
                </h3>
                <div className="flex flex-wrap items-center gap-6 text-sm font-medium text-[#5F6368]">
                    <span className="flex items-center gap-1.5"><Briefcase size={16} className="text-[#70757A]" /> {job.company}</span>
                    <span className="flex items-center gap-1.5"><MapPin size={16} className="text-[#70757A]" /> {job.location}</span>
