                      <div>
                        <label className="block text-xs font-bold text-[#5F6368] uppercase tracking-wider mb-2">Company</label>
                        <div className="relative">
                            <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={16} />
