const CVEditor: React.FC = () => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');

  // AI Panel State
  const [showAiPanel, setShowAiPanel] = useState(false);
  const [showDoc, setShowDoc] = useState(false);
  const [aiMode, setAiMode] = useState<'impact' | 'clarify' | null>(null);
  const [selectedText, setSelectedText] = useState('');
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Initial Load from Firestore
  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded from Cloud');
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            // Default Content if nothing in DB
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: var(--md-sys-color-primary);">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
        }
    };
    loadContent();
  }, []);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        // Save to Firestore
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }
  }, []);

  // Debounced auto-save
  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };

      const el = editorRef.current;
      const rawInputHandler = () => handleInput();

      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const handlePaste = (e: React.ClipboardEvent) => {
      // Allow default paste
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const initAI = (type: 'impact' | 'clarify') => {
    const selection = window.getSelection();
    const text = selection?.toString();

    if (!text || text.trim().length === 0) {
        alert("Please highlight text in your CV first.");
        return;
    }

    setSelectedText(text);
    setAiMode(type);
    setShowAiPanel(true);
    setAiSuggestion('');
    generateSuggestion(text, type);
  };

  const generateSuggestion = async (text: string, type: 'impact' | 'clarify') => {
    setIsAiLoading(true);
    try {
        const promptText = type === 'impact' 
            ? "Identify weak verbs and passive voice. Rewrite this to be action-oriented, using strong power verbs. Return ONLY the rewritten text." 
            : "Clarify this text. Remove fluff, fix grammar, and make it concise and punchy. Return ONLY the rewritten text.";

        const result = await improveCV(text, promptText);
        setAiSuggestion(result);
    } catch (e) {
        setAiSuggestion("Error generating suggestion. Please try again.");
    } finally {
        setIsAiLoading(false);
    }
  };

  const applySuggestion = () => {
      if (editorRef.current && aiSuggestion) {
          editorRef.current.focus();
          document.execCommand('insertText', false, aiSuggestion);
          saveContent();
          closeAiPanel();
      }
  };

  const closeAiPanel = () => {
      setShowAiPanel(false);
      setAiMode(null);
      setSelectedText('');
      setAiSuggestion('');
  };

  return (
    <div className="flex h-[calc(100vh-100px)] relative bg-[#F8F9FA] rounded-[32px] overflow-hidden border border-[#DADCE0] shadow-sm">

        {/* Reference Document Panel */}
        {showDoc && (
             <div className="w-1/2 h-full border-r border-[#DADCE0] bg-white hidden lg:block animate-in slide-in-from-left-4 duration-300">
                 <iframe 
                    src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" 
                    className="w-full h-full" 
                    title="Reference CV"
                 ></iframe>
             </div>
        )}

        {/* Main Editor Area */}
        <div className="flex-1 flex flex-col h-full transition-all duration-300">

            {/* Toolbar - Sticky */}
            <div className="flex-none bg-[#F1F3F4] px-4 sm:px-6 py-4 flex items-center gap-4 border-b border-[#DADCE0] z-10 sticky top-0 overflow-x-auto scrollbar-hide shadow-sm">

                <div className="flex items-center gap-1 bg-white p-1 rounded-full shadow-sm border border-[#DADCE0] shrink-0">
                    <button onClick={() => execCmd('undo')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors" aria-label="Undo"><RotateCcw size={16} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors" aria-label="Redo"><RotateCw size={16} /></button>
                </div>

                <div className="flex items-center gap-1 bg-white p-1 rounded-full shadow-sm border border-[#DADCE0] shrink-0">
                    <button onClick={() => execCmd('formatBlock', 'H2')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] font-bold" title="Heading" aria-label="Heading"><Type size={16} /></button>
                    <button onClick={() => execCmd('bold')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] font-bold" aria-label="Bold"><Bold size={16} /></button>
                    <button onClick={() => execCmd('italic')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] italic" aria-label="Italic"><Italic size={16} /></button>
                    <button onClick={() => execCmd('underline')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368] underline" aria-label="Underline"><Underline size={16} /></button>
                </div>

                <div className="flex items-center gap-1 bg-white p-1 rounded-full shadow-sm border border-[#DADCE0] shrink-0">
                    <button onClick={() => execCmd('justifyLeft')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]" aria-label="Align Left"><AlignLeft size={16} /></button>
                    <button onClick={() => execCmd('justifyCenter')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]" aria-label="Align Center"><AlignCenter size={16} /></button>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]" aria-label="List"><List size={16} /></button>
                </div>

                <div className="w-px h-6 bg-[#DADCE0] shrink-0"></div>

                {/* AI Actions */}
                <div className="flex gap-2 shrink-0">
                    <button 
                        onClick={() => initAI('impact')} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#E8F0FE] text-[#1967D2] rounded-full text-sm font-bold hover:shadow-md transition-all hover:bg-[#D2E3FC] whitespace-nowrap"
                    >
                        <Search size={16} /> <span className="hidden sm:inline">Impact Check</span>
                    </button>
                    <button 
                        onClick={() => initAI('clarify')} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#F1F3F4] text-[#202124] rounded-full text-sm font-bold hover:shadow-md transition-all hover:bg-[#DADCE0] whitespace-nowrap"
                    >
                        <Wand2 size={16} /> Clarify
                    </button>
                </div>

                {/* Reference Toggle */}
                <button
                    onClick={() => setShowDoc(!showDoc)}
                    className={`flex items-center gap-2 px-3 py-2 rounded-full text-sm font-bold transition-all border shrink-0 ${showDoc ? 'bg-[#202124] text-white border-transparent' : 'bg-white text-[#5F6368] border-[#DADCE0] hover:bg-[#F1F3F4]'}`}
                    title="Toggle Reference Document"
                >
                    <BookOpen size={16} /> <span className="hidden xl:inline">Reference</span>
                </button>

                 <div className="ml-auto flex items-center gap-2 text-xs font-medium text-[#5F6368] bg-white px-3 py-1.5 rounded-full border border-[#DADCE0] shrink-0">
                    <Save size={12} className={lastSaved ? 'text-green-600' : 'text-gray-400'} />
                    {lastSaved ? `Saved ${lastSaved}` : 'Unsaved'}
                </div>
            </div>

            {/* Paper Container - Scrollable */}
            <div className="flex-1 w-full overflow-y-auto custom-scrollbar p-4 md:p-8 flex justify-center bg-[#F8F9FA]">
                <div 
                    ref={editorRef}
                    contentEditable
                    onPaste={handlePaste}
                    className="w-full max-w-[850px] min-h-[1100px] h-max bg-white shadow-sm hover:shadow-md border border-[#DADCE0] p-6 md:p-[72px] outline-none text-[#202124] font-sans text-base md:text-lg leading-[1.6] transition-all rounded-sm mb-16"
                />
            </div>
        </div>

        {/* Right Sidebar for AI Results */}
        {showAiPanel && (
            <div className="w-[320px] bg-white border-l border-[#DADCE0] shadow-xl flex flex-col z-20">
                <div className="p-5 border-b border-[#DADCE0] flex items-center justify-between bg-[#F8F9FA]">
                    <h3 className="font-bold text-[#202124] flex items-center gap-2">
                        {aiMode === 'impact' ? <Search size={18} className="text-[#1a73e8]" /> : <Wand2 size={18} className="text-[#1a73e8]" />}
                        {aiMode === 'impact' ? 'Impact Review' : 'Clarify Text'}
                    </h3>
                    <button onClick={closeAiPanel} className="p-2 hover:bg-[#F1F3F4] rounded-full text-[#5F6368]">
                        <X size={20} />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-5 custom-scrollbar">
                    <div className="mb-6">
                        <label className="text-xs font-bold text-[#70757A] uppercase tracking-wider mb-2 block">Original</label>
                        <div className="p-3 bg-[#F8F9FA] rounded-xl text-sm text-[#5F6368] border border-[#E8F0FE] italic">
                            "{selectedText}"
                        </div>
                    </div>

                    <div>
                        <label className="text-xs font-bold text-[#70757A] uppercase tracking-wider mb-2 block">Suggestion</label>
                        {isAiLoading ? (
                            <div className="flex flex-col items-center py-8 gap-3">
                                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#1a73e8]"></div>
                                <span className="text-xs text-[#5F6368] animate-pulse">Polishing your words...</span>
                            </div>
                        ) : (
                            <div className="p-4 bg-white rounded-xl text-sm text-[#202124] border-2 border-[#1a73e8] shadow-sm">
                                {aiSuggestion}
                            </div>
                        )}
                    </div>
                </div>

                <div className="p-5 border-t border-[#DADCE0] bg-[#F8F9FA]">
                    <button 
                        onClick={applySuggestion}
                        disabled={isAiLoading || !aiSuggestion}
                        className="w-full py-3 bg-[#1a73e8] text-white rounded-xl font-bold hover:bg-[#1557B0] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-sm"
                    >
                        <Check size={18} /> Apply Change
                    </button>
                </div>
            </div>
        )}
    </div>
  );
};

export default CVEditor;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, Check, ChevronDown } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;
  const applyUrl = job.url || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 transition-all duration-300">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose}></div>

      {/* Surface */}
      <div className="relative bg-[#F8F9FA] w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[28px] overflow-hidden border border-white/50 animate-in fade-in zoom-in-95 duration-200">

        {/* Header (Fixed) */}
        <div className="flex items-center justify-between px-6 py-6 sm:px-8 bg-white border-b border-[#DADCE0] shrink-0">
           <div className="flex items-center gap-5 flex-1 mr-4 sm:mr-8">
              <div className="w-14 h-14 bg-[#E8F0FE] text-[#1967D2] rounded-2xl hidden sm:flex items-center justify-center shadow-sm shrink-0">
                  <Briefcase size={28} />
              </div>
              <div className="flex-1 min-w-0">
                  {isEditingTitle ? (
                      <input 
                        type="text" 
                        value={editedTitle}
                        onChange={(e) => setEditedTitle(e.target.value)}
                        onBlur={handleSaveTitle}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                        className="text-xl sm:text-2xl font-bold text-[#202124] w-full border-b-2 border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                      />
                  ) : (
                      <h2 
                        onClick={() => setIsEditingTitle(true)}
                        className="text-xl sm:text-2xl font-bold text-[#202124] leading-tight truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-full"
                        title="Click to edit title"
                      >
                        {job.title} <Edit2 size={16} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" />
                      </h2>
                  )}

                  {isEditingCompany ? (
                      <input 
                        type="text" 
                        value={editedCompany}
                        onChange={(e) => setEditedCompany(e.target.value)}
                        onBlur={handleSaveCompany}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveCompany()}
                        className="text-sm text-[#5F6368] font-medium mt-1 w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                      />
                  ) : (
                      <p 
                        onClick={() => setIsEditingCompany(true)}
                        className="text-sm text-[#5F6368] font-medium mt-1 truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-fit"
                        title="Click to edit company"
                      >
                          {job.company} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" />
                      </p>
                  )}
              </div>
           </div>
           <button onClick={onClose} className="w-10 h-10 flex items-center justify-center hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors shrink-0">
             <X size={24} />
           </button>
        </div>

        {/* Unified Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 sm:p-8 bg-white">
            <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-12">

                {/* Main Content Area (Left) */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs */}
                    <div className="flex items-center gap-2 mb-8 bg-[#F1F3F4] p-1 rounded-full w-fit border border-[#DADCE0]">
                        <button 
                            onClick={() => setActiveTab('brief')} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'brief' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <FileText size={14} /> Job Details
                        </button>
                        <button 
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'strategy' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <Sparkles size={14} /> Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="prose prose-slate max-w-none text-[#202124]">
                            {/* Tags */}
                            <div className="mb-8 flex flex-wrap gap-3">
                                {job.seniorityScore && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{job.seniorityScore}</span>
                                )}
                                {analysis?.salary && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis.salary}</span>
                                )}
                                {analysis?.workPattern && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis.workPattern}</span>
                                )}
                                {analysis?.industry && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis.industry}</span>
                                )}
                            </div>

                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold text-[#202124] uppercase tracking-wide">Original Description</h3>
                                    {!isEditingSummary ? (
                                        <button 
                                            onClick={() => setIsEditingSummary(true)}
                                            className="text-xs font-bold text-[#1a73e8] hover:bg-[#E8F0FE] px-3 py-1.5 rounded-full flex items-center gap-1 transition-colors"
                                        >
                                            <Edit2 size={12} /> Edit
                                        </button>
                                    ) : (
                                        <button 
                                            onClick={handleSaveDescription}
                                            className="text-xs font-bold text-white bg-[#1a73e8] hover:bg-[#1557B0] px-3 py-1.5 rounded-full flex items-center gap-1 transition-colors shadow-sm"
                                        >
                                            <Save size={12} /> Save
                                        </button>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <textarea 
                                        value={editedSummary}
                                        onChange={(e) => setEditedSummary(e.target.value)}
                                        className="w-full h-[400px] p-4 border border-[#1a73e8] rounded-xl text-base leading-relaxed focus:outline-none focus:ring-2 focus:ring-[#D2E3FC] bg-white text-[#3C4043] font-sans resize-y"
                                        placeholder="Paste full job description here..."
                                    />
                                ) : (
                                    <div className="text-[#3C4043] leading-relaxed whitespace-pre-wrap text-base border border-transparent rounded-xl p-0.5">
                                        {job.summary}
                                    </div>
                                )}
                            </div>

                            {analysis && (
                                <div className="mt-8">
                                    <h4 className="text-sm font-black text-[#1967D2] mb-2 flex items-center gap-2 uppercase tracking-wide">
                                        <Zap size={16} className="fill-[#1967D2]" /> AI Summary
                                    </h4>
                                    <p className="text-[#202124] font-medium mb-6 leading-relaxed text-lg">{analysis.verdict}</p>

                                    <div className="flex flex-wrap gap-2">
                                        {analysis.matchedKeywords.map((kw, i) => (
                                            <span key={i} className="px-4 py-1.5 bg-white border border-[#E8F0FE] text-xs font-bold rounded-full text-[#1967D2]">
                                                {kw}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="animate-in fade-in duration-300">
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="text-xl font-bold text-[#202124]">Execution Strategy</h3>
                                <button onClick={() => onGenerateKit(job)} className="text-sm font-bold text-[#1a73e8] hover:bg-[#E8F0FE] px-4 py-2 rounded-full transition-colors flex items-center gap-2">
                                    <Sparkles size={16} /> Regenerate
                                </button>
                            </div>

                            {analysis?.strategy ? (
                                <div className="prose prose-slate max-w-none font-sans bg-[#F8F9FA] p-8 rounded-[24px] border border-[#DADCE0]">
                                    <div className="whitespace-pre-wrap leading-relaxed text-[#202124]">{analysis.strategy}</div>
                                </div>
                            ) : (
                                <div className="py-24 text-center text-[#70757A]">
                                    <Zap size={48} className="mx-auto mb-4 text-[#DADCE0] animate-pulse" />
                                    <p className="text-lg font-medium">Generating your tailored strategy...</p>
                                    <p className="text-sm mt-2">Connecting your case studies to requirements.</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Sidebar (Right) - Unified Scroll, No Boxes */}
                <div className="w-full md:w-64 shrink-0 space-y-8 order-1 md:order-2">
                    <div className="relative">
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block">Status</span>
                        <div className="relative">
                            <select 
                                value={job.status || 'new'}
                                onChange={handleStatusChange}
                                className={`w-full appearance-none pl-4 pr-10 py-3 rounded-xl font-bold capitalize text-sm border focus:outline-none focus:ring-2 focus:ring-[#1a73e8] cursor-pointer transition-all ${
                                    job.status === 'applied' ? 'bg-[#E8F0FE] text-[#1967D2] border-[#D2E3FC]' :
                                    job.status === 'interview' ? 'bg-[#FEF7E0] text-[#B06000] border-[#FEEFC3]' :
                                    job.status === 'offer' ? 'bg-[#E6F4EA] text-[#137333] border-[#CEEAD6]' :
                                    'bg-white text-[#202124] border-[#DADCE0]'
                                }`}
                            >
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-50" />
                        </div>
                    </div>

                    <div className="cursor-pointer group" onClick={() => setIsEditingLocation(true)}>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block group-hover:text-[#1a73e8] transition-colors">Location</span>
                        {isEditingLocation ? (
                             <input 
                                type="text"
                                value={editedLocation}
                                onChange={(e) => setEditedLocation(e.target.value)}
                                onBlur={handleSaveLocation}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveLocation()}
                                className="text-sm font-semibold text-[#202124] block w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                             />
                        ) : (
                             <span className="text-sm font-semibold text-[#202124] block group-hover:text-[#1a73e8] transition-colors flex items-center justify-between">
                                {job.location} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8]" />
                             </span>
                        )}
                    </div>

                    <div className="cursor-pointer group" onClick={() => setIsEditingPostedDate(true)}>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block group-hover:text-[#1a73e8] transition-colors">Posted</span>
