                    className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all flex items-center gap-2 ${mode === 'text' ? 'bg-[#1a73e8] text-white shadow-sm' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
