                        <Link className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9AA0A6]" size={16} aria-hidden="true" />
                        <input 
                            id="manual-url"
                            type="url" 
                            value={manualUrl}
                            onChange={(e) => setManualUrl(e.target.value)}
