                        {['new', 'saved', 'archived'].map((tab) => {
                            const count = allJobs.filter(j => {
                                    if (tab === 'new') return (j.status || 'new') === 'new';
                                    if (tab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(j.status || '');
                                    return j.status === 'archived';
                                }).length;
                            const isActive = activeTab === tab;
                            return (
                                <button 
                                    key={tab}
                                    onClick={() => setActiveTab(tab as any)} 
                                    className={`px-5 py-2 rounded-full text-sm font-bold capitalize transition-all whitespace-nowrap border ${isActive ? 'bg-[#E8F0FE] text-[#1967D2] border-transparent shadow-sm' : 'bg-white text-[#5F6368] border-[#DADCE0] hover:bg-[#F1F3F4]'}`}
                                >
                                    {tab} <span className="opacity-60 text-xs ml-1">({count})</span>
                                </button>
                            );
                        })}
                    </div>

                    <div className="flex items-center gap-2 bg-white p-1 rounded-full border border-[#DADCE0]">
                         <button 
                            onClick={() => setSortBy('date')}
                            className={`px-4 py-1.5 rounded-full text-xs font-bold flex items-center gap-1 transition-all ${sortBy === 'date' ? 'bg-[#202124] text-white' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                         >
                            Date
                         </button>
                         <button 
                            onClick={() => setSortBy('score')}
                            className={`px-4 py-1.5 rounded-full text-xs font-bold flex items-center gap-1 transition-all ${sortBy === 'score' ? 'bg-[#202124] text-white' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                         >
                            Score <ArrowDownUp size={12} />
                         </button>
                    </div>
                </div>

                <div className="space-y-4 pb-24">
                    {filteredJobs.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[32px] border border-dashed border-[#DADCE0] text-[#70757A]">
                            <CheckCircle2 size={64} className="mb-4 text-[#DADCE0]" />
                            <h3 className="text-xl font-bold text-[#5F6368]">All caught up</h3>
                            <p className="text-sm font-medium">No jobs match your current filters.</p>
                            {(cityFilter !== 'All' || industryFilter) && (
                                <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="mt-4 text-[#1a73e8] font-bold text-sm">Clear Filters</button>
                            )}
                        </div>
                    ) : (
                        filteredJobs.map(job => (
                            <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                        ))
                    )}
                </div>
            </div>
        </div>
        )}

        {currentView === ViewState.KANBAN && (
            <KanbanBoard 
                jobs={allJobs} 
                onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                onToggleStatus={handleKanbanMove}
                onDelete={handleDelete}
                onOpenDetail={handleOpenDetail}
                onOpenAddModal={() => setIsAddLinkOpen(true)}
            />
        )}

        {currentView === ViewState.CV_EDITOR && (
            <CVEditor />
        )}

      </main>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { Bot, Layout, Columns, FileText, CheckCircle2, Filter, Sparkles, Plus, Search, ArrowDownUp, Globe, Link } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected, setIsDbConnected] = useState(() => {
    return initFirebase(DEFAULT_FIREBASE_CONFIG);
  });

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          // Manually update allJobs to reflect change immediately if needed, though subscription usually handles it
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView === ViewState.DASHBOARD) {
              setActiveTab('saved');
          }
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }

          // 1. Create Placeholder immediately (works for both URL and Text)
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);

          // 2. Enrich with AI (handles both cases)
          const enrichedDetails = await enrichJob(data);

          // Merge details. Priority: AI enrichment > Manual Input > Placeholder defaults
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              // If we have manual text, ensure it isn't overwritten by empty AI result
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };

          await addOrUpdateJob(enrichedJob);

          // 3. Analyze
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);

      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const locationCounts = allJobs.reduce((acc, job) => {
    const locRaw = job.location.toLowerCase();
    let key = 'Other';
    if (locRaw.includes('edinburgh')) key = 'Edinburgh';
    else if (locRaw.includes('glasgow')) key = 'Glasgow';
    else if (locRaw.includes('remote')) key = 'Remote';
    else if (locRaw.includes('london')) key = 'London';
    else if (locRaw.includes('manchester')) key = 'Manchester';
    if ((job.status || 'new') === 'new') {
        acc[key] = (acc[key] || 0) + 1;
        acc['All'] = (acc['All'] || 0) + 1;
    }
    return acc;
  }, { 'All': 0 } as Record<string, number>);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const filteredJobs = allJobs.filter(j => {
    const status = j.status || 'new';
    if (activeTab === 'new') return status === 'new';
    if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
    if (activeTab === 'archived') return status === 'archived';
    return true;
  }).filter(j => {
    const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
    if (!locMatch) return false;

    // Industry Filter
    if (industryFilter) {
        const ind = j.analysis?.industry || 'Tech';
        if (ind !== industryFilter) {
             const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
             let calculatedIndustry = 'Tech';
             if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
             else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
             else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
             else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

             if (calculatedIndustry !== industryFilter) return false;
        }
    }
    return true;
  }).sort((a, b) => {
      if (sortBy === 'score') {
          return (b.analysis?.score || 0) - (a.analysis?.score || 0);
      }
      return (b.scoutedAt || 0) - (a.scoutedAt || 0);
  });

  return (
    <div className="min-h-screen bg-[#F0F2F5] text-[#202124] font-sans pb-20 selection:bg-[#E8F0FE] selection:text-[#1a73e8]">

      {/* FLOATING HEADER */}
      <div className="sticky top-4 z-40 px-4 mb-4 flex justify-center">
          <header className="bg-white/90 backdrop-blur-xl border border-white/40 rounded-full shadow-lg elevation-1 p-2 w-full max-w-2xl flex items-center justify-between transition-all">
             <div className="flex items-center gap-3">
                 <div className="bg-[#1a73e8] p-2 rounded-full text-white shadow-sm">
                     <Bot size={20} fill="none" />
                 </div>
                 <span className="font-bold text-lg text-[#202124]">Vyom's Job Agent</span>
             </div>

             <nav className="flex items-center gap-1 bg-[#F1F3F4] p-1 rounded-full">
                 {[
                   { id: ViewState.DASHBOARD, label: 'Dashboard', icon: Layout },
                   { id: ViewState.KANBAN, label: 'Jobs Applied', icon: Columns },
                   { id: ViewState.CV_EDITOR, label: 'CV', icon: FileText }
                 ].map(item => (
                   <button 
                     key={item.id}
                     onClick={() => setCurrentView(item.id)} 
                     className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-bold transition-all duration-300 ${currentView === item.id ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:text-[#202124] hover:bg-white/50'}`}
                   >
                      <item.icon size={16} />
                      <span className="hidden sm:inline">{item.label}</span>
                   </button>
                 ))}
             </nav>
          </header>
      </div>

      <main className="max-w-[1600px] mx-auto px-6 mt-8">

        {/* WELCOME HEADER - CENTERED WITH SCOUT BUTTON */}
        {currentView === ViewState.DASHBOARD && (
            <div className="mb-20 pt-10 animate-in fade-in slide-in-from-bottom-4 duration-500 text-center max-w-2xl mx-auto flex flex-col items-center">
                <h1 className="text-4xl font-normal text-[#202124] tracking-tight">
                    Welcome back, <span className="font-bold">Vyom.</span>
                </h1>
                <p className="text-[#5F6368] mt-2 text-lg mb-4">
                    You have <span className="font-bold text-[#1a73e8]">{allJobs.filter(j => j.status === 'saved').length} saved jobs</span> and <span className="font-bold text-[#137333]">{allJobs.filter(j => j.status === 'interview').length} active interviews</span>.
                </p>

                <div className="flex items-center gap-4 mb-20">
                    <button
                        onClick={fetchJobs}
                        disabled={isFetching}
                        className="px-6 py-2.5 rounded-full text-sm font-bold bg-white border border-[#DADCE0] text-[#5F6368] hover:border-[#1a73e8] hover:text-[#1a73e8] transition-all flex items-center gap-2 shadow-sm"
                    >
                        {isFetching ? (
                            <span className="flex items-center gap-2">
                                <span className="w-4 h-4 border-2 border-[#5F6368] border-t-transparent rounded-full animate-spin"></span>
                                Scouting Market...
                            </span>
                        ) : (
                            <>
                                <Search size={18} />
                                <span>Scout New Jobs</span>
                            </>
                        )}

                        {analyzingCount > 0 && (
                            <span className="absolute -top-2 -right-2 bg-[#DB4437] text-white text-xs font-bold px-2 py-1 rounded-full shadow-md animate-bounce border border-white">
                                {analyzingCount} analyzing
                            </span>
                        )}
                    </button>

                    <button
                        onClick={() => setIsAddLinkOpen(true)}
                        className="px-6 py-2.5 rounded-full text-sm font-bold bg-white border border-[#DADCE0] text-[#5F6368] hover:border-[#1a73e8] hover:text-[#1a73e8] transition-all flex items-center gap-2 shadow-sm"
                        title="Add Job Link"
                    >
                        <Link size={18} />
                        <span>Add Job</span>
                    </button>
                </div>
            </div>
        )}

        {currentView === ViewState.DASHBOARD && (
        <div className="grid grid-cols-12 gap-8 items-start relative">
            {/* SIDEBAR FILTER PANEL */}
            <div className="col-span-12 lg:col-span-3">
               <div className="sticky top-28 space-y-6">
                    <div className="bg-[#F1F3F4] p-6 rounded-[28px] border border-white shadow-sm ring-1 ring-[#DADCE0]/50">
                        <div className="flex items-center gap-2 mb-6 text-[#5F6368]">
                            <Filter size={20} />
                            <span className="text-sm font-bold uppercase tracking-wider">Smart Filters</span>
                        </div>

                        <div className="space-y-4">
                            <p className="text-xs font-bold text-[#70757A] ml-1 uppercase">Location</p>
                            <div className="flex flex-wrap gap-2">
                                {filterOptions.map(city => {
                                    const count = locationCounts[city] || 0;
                                    if (count === 0 && city !== 'All') return null;
                                    const isActive = cityFilter === city;
                                    return (
                                        <button 
                                            key={city} 
                                            onClick={() => setCityFilter(city)} 
                                            className={`px-3 py-1.5 text-xs font-bold rounded-lg transition-all flex items-center gap-2 border ${isActive ? 'bg-[#202124] text-white border-transparent shadow-sm' : 'bg-white text-[#5F6368] border-[#DADCE0] hover:border-[#202124]'}`}
                                        >
                                            {city} <span className={`text-[10px] px-1.5 py-0.5 rounded-full ${isActive ? 'bg-white/20' : 'bg-[#F1F3F4]'}`}>{count}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        </div>

                        <div className="h-px bg-[#DADCE0] my-6"></div>
                        <StatsPanel 
                            jobs={allJobs} 
                            selectedIndustry={industryFilter}
                            onSelectIndustry={setIndustryFilter}
                        />

                        <div className="h-px bg-[#DADCE0] my-6"></div>

                        <div>
                            <h3 className="text-xs font-bold text-[#70757A] uppercase tracking-wide mb-3 flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-[#34A853]"></span> Active Sources
                            </h3>
                            <div className="flex flex-wrap gap-2">
                                {['LinkedIn', 'Glassdoor', 'Indeed', 'Otta', 'Reed', 'TotalJobs', 'Behance'].map(p => (
                                    <span key={p} className="px-2.5 py-1.5 bg-white border border-[#DADCE0] rounded-lg text-[11px] font-bold text-[#5F6368] shadow-sm cursor-default hover:border-[#202124] transition-colors">
                                        {p}
                                    </span>
                                ))}
                            </div>
                        </div>
                    </div>
               </div>
            </div>

            {/* MAIN CONTENT LIST */}
            <div className="col-span-12 lg:col-span-9 min-h-screen">

                {/* Tabs & Sort */}
                <div className="flex flex-wrap items-center justify-between mb-6 gap-4">
                    <div className="flex items-center gap-3 overflow-x-auto pb-2 scrollbar-hide">
                        {['new', 'saved', 'archived'].map((tab) => {
                            const count = allJobs.filter(j => {
                                    if (tab === 'new') return (j.status || 'new') === 'new';
                                    if (tab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(j.status || '');
                                    return j.status === 'archived';
                                }).length;
                            const isActive = activeTab === tab;
                            return (
                                <button 
                                    key={tab}
                                    onClick={() => setActiveTab(tab as any)} 
                                    className={`px-5 py-2 rounded-full text-sm font-bold capitalize transition-all whitespace-nowrap border ${isActive ? 'bg-[#E8F0FE] text-[#1967D2] border-transparent shadow-sm' : 'bg-white text-[#5F6368] border-[#DADCE0] hover:bg-[#F1F3F4]'}`}
                                >
                                    {tab} <span className="opacity-60 text-xs ml-1">({count})</span>
                                </button>
                            );
                        })}
                    </div>

                    <div className="flex items-center gap-2 bg-white p-1 rounded-full border border-[#DADCE0]">
                         <button 
                            onClick={() => setSortBy('date')}
                            className={`px-4 py-1.5 rounded-full text-xs font-bold flex items-center gap-1 transition-all ${sortBy === 'date' ? 'bg-[#202124] text-white' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                         >
                            Date
                         </button>
                         <button 
                            onClick={() => setSortBy('score')}
                            className={`px-4 py-1.5 rounded-full text-xs font-bold flex items-center gap-1 transition-all ${sortBy === 'score' ? 'bg-[#202124] text-white' : 'text-[#5F6368] hover:bg-[#F1F3F4]'}`}
                         >
                            Score <ArrowDownUp size={12} />
                         </button>
                    </div>
                </div>

                <div className="space-y-4 pb-24">
                    {filteredJobs.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[32px] border border-dashed border-[#DADCE0] text-[#70757A]">
                            <CheckCircle2 size={64} className="mb-4 text-[#DADCE0]" />
                            <h3 className="text-xl font-bold text-[#5F6368]">All caught up</h3>
                            <p className="text-sm font-medium">No jobs match your current filters.</p>
                            {(cityFilter !== 'All' || industryFilter) && (
                                <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="mt-4 text-[#1a73e8] font-bold text-sm">Clear Filters</button>
                            )}
                        </div>
                    ) : (
                        filteredJobs.map(job => (
                            <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                        ))
                    )}
                </div>
            </div>
        </div>
        )}

        {currentView === ViewState.KANBAN && (
            <KanbanBoard 
                jobs={allJobs} 
                onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                onToggleStatus={handleKanbanMove}
                onDelete={handleDelete}
                onOpenDetail={handleOpenDetail}
                onOpenAddModal={() => setIsAddLinkOpen(true)}
            />
        )}

        {currentView === ViewState.CV_EDITOR && (
            <CVEditor />
        )}

      </main>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, Check, ChevronDown, RotateCw, TrendingUp, AlertTriangle } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  // URL Editing
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');

  // Re-Analyze State
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
        setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  // URL Logic
  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleSaveUrl = () => {
      if (onUpdateJob && editedUrl.trim() !== job.url) {
          const finalUrl = editedUrl.trim() || 'Manual Entry';
          onUpdateJob({ ...job, url: finalUrl });
      }
      setIsEditingUrl(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  const handleReAnalyzeClick = async () => {
      if (onReAnalyze) {
          setIsAnalyzing(true);
          await onReAnalyze(job);
          setIsAnalyzing(false);
      }
  };

  const isValidAttribute = (attr?: string) => {
      if (!attr) return false;
      const lower = attr.toLowerCase();
      return lower !== 'unspecified' && lower !== 'unknown' && lower !== 'n/a' && attr.trim() !== '';
  };

  return (
    <div 
        className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 transition-all duration-300"
        role="dialog"
        aria-modal="true"
        aria-labelledby="job-detail-title"
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} aria-hidden="true"></div>

      {/* Surface */}
      <div className="relative bg-[#F8F9FA] w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[28px] overflow-hidden border border-white/50 animate-in fade-in zoom-in-95 duration-200">

        {/* Header (Fixed) */}
        <div className="flex items-center justify-between px-6 py-6 sm:px-8 bg-white border-b border-[#DADCE0] shrink-0">
           <div className="flex items-center gap-5 flex-1 mr-4 sm:mr-8">
              <div className="w-14 h-14 bg-[#E8F0FE] text-[#1967D2] rounded-2xl hidden sm:flex items-center justify-center shadow-sm shrink-0" aria-hidden="true">
                  <Briefcase size={28} />
              </div>
              <div className="flex-1 min-w-0">
                  {isEditingTitle ? (
                      <input 
                        type="text" 
                        value={editedTitle}
                        onChange={(e) => setEditedTitle(e.target.value)}
                        onBlur={handleSaveTitle}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                        className="text-xl sm:text-2xl font-bold text-[#202124] w-full border-b-2 border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                        aria-label="Edit Job Title"
                      />
                  ) : (
                      <h2 
                        id="job-detail-title"
                        onClick={() => setIsEditingTitle(true)}
                        className="text-xl sm:text-2xl font-bold text-[#202124] leading-tight truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-full"
                        title="Click to edit title"
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && setIsEditingTitle(true)}
                      >
                        {job.title} <Edit2 size={16} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" aria-label="Edit Title" />
                      </h2>
                  )}

                  {isEditingCompany ? (
                      <input 
                        type="text" 
                        value={editedCompany}
                        onChange={(e) => setEditedCompany(e.target.value)}
                        onBlur={handleSaveCompany}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveCompany()}
                        className="text-sm text-[#5F6368] font-medium mt-1 w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                        aria-label="Edit Company Name"
                      />
                  ) : (
                      <p 
                        onClick={() => setIsEditingCompany(true)}
                        className="text-sm text-[#5F6368] font-medium mt-1 truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-fit"
                        title="Click to edit company"
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && setIsEditingCompany(true)}
                      >
                          {job.company} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" aria-label="Edit Company" />
                      </p>
                  )}
              </div>
           </div>
           <button 
                onClick={onClose} 
                className="w-10 h-10 flex items-center justify-center hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors shrink-0 focus:outline-none focus:ring-2 focus:ring-[#1a73e8]"
                aria-label="Close Modal"
           >
             <X size={24} aria-hidden="true" />
           </button>
        </div>

        {/* Unified Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 sm:p-8 bg-white">
            <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-12">

                {/* Main Content Area (Left) */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs */}
                    <div className="flex items-center gap-2 mb-8 bg-[#F1F3F4] p-1 rounded-full w-fit border border-[#DADCE0]" role="tablist">
                        <button 
                            role="tab"
                            aria-selected={activeTab === 'brief'}
                            onClick={() => setActiveTab('brief')} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'brief' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <FileText size={14} aria-hidden="true" /> Job Details
                        </button>
                        <button 
                            role="tab"
                            aria-selected={activeTab === 'strategy'}
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'strategy' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <Sparkles size={14} aria-hidden="true" /> Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="prose prose-slate max-w-none text-[#202124]" role="tabpanel">
                            {/* Tags */}
                            <div className="mb-8 flex flex-wrap gap-3" aria-label="Job Attributes">
                                {analysis && analysis.isHighValue && (
                                     <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#E6F4EA] text-[#137333] border border-[#CEEAD6] flex items-center gap-1">
                                        <TrendingUp size={14} aria-hidden="true" /> High Value
                                     </span>
                                )}
                                {analysis && analysis.isCommuteRisk && (
                                     <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#FCE8E6] text-[#C5221F] border border-[#FAD2CF] flex items-center gap-1">
                                        <AlertTriangle size={14} aria-hidden="true" /> Commute Risk
                                     </span>
                                )}
                                {isValidAttribute(analysis?.industry) && (
                                    <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#FFF8E1] text-[#B06000] border border-[#FEEFC3]">
                                        {analysis?.industry}
                                    </span>
                                )}
                                {isValidAttribute(job.seniorityScore) && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{job.seniorityScore}</span>
                                )}
                                {isValidAttribute(analysis?.salary) && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis?.salary}</span>
                                )}
                                {isValidAttribute(analysis?.workPattern) && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis?.workPattern}</span>
                                )}
                            </div>

                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold text-[#202124] uppercase tracking-wide">Original Description</h3>
                                    {!isEditingSummary ? (
                                        <button 
                                            onClick={() => setIsEditingSummary(true)}
                                            className="text-xs font-bold text-[#1a73e8] hover:bg-[#E8F0FE] px-3 py-1.5 rounded-full flex items-center gap-1 transition-colors"
                                            aria-label="Edit Job Description"
                                        >
                                            <Edit2 size={12} aria-hidden="true" /> Edit
                                        </button>
                                    ) : (
                                        <button 
                                            onClick={handleSaveDescription}
                                            className="text-xs font-bold text-white bg-[#1a73e8] hover:bg-[#1557B0] px-3 py-1.5 rounded-full flex items-center gap-1 transition-colors shadow-sm"
                                            aria-label="Save Job Description"
                                        >
                                            <Save size={12} aria-hidden="true" /> Save
                                        </button>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <textarea 
                                        value={editedSummary}
                                        onChange={(e) => setEditedSummary(e.target.value)}
                                        className="w-full h-[400px] p-4 border border-[#1a73e8] rounded-xl text-base leading-relaxed focus:outline-none focus:ring-2 focus:ring-[#D2E3FC] bg-white text-[#3C4043] font-sans resize-y"
                                        placeholder="Paste full job description here..."
                                        aria-label="Job Description"
                                    />
                                ) : (
                                    <div className="text-[#3C4043] leading-relaxed whitespace-pre-wrap text-base border border-transparent rounded-xl p-0.5">
                                        {job.summary}
                                    </div>
                                )}
                            </div>

                            {analysis && (
                                <div className="mt-8">
                                    <h4 className="text-sm font-black text-[#1967D2] mb-2 flex items-center gap-2 uppercase tracking-wide">
                                        <Zap size={16} className="fill-[#1967D2]" aria-hidden="true" /> AI Summary
                                    </h4>
                                    <p className="text-[#202124] font-medium mb-6 leading-relaxed text-lg">{analysis.verdict}</p>

                                    <div className="flex flex-wrap gap-2">
                                        {analysis.matchedKeywords.map((kw, i) => (
                                            <span key={i} className="px-4 py-1.5 bg-white border border-[#E8F0FE] text-xs font-bold rounded-full text-[#1967D2]">
                                                {kw}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="animate-in fade-in duration-300" role="tabpanel">
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="text-xl font-bold text-[#202124]">Execution Strategy</h3>
                                <button onClick={() => onGenerateKit(job)} className="text-sm font-bold text-[#1a73e8] hover:bg-[#E8F0FE] px-4 py-2 rounded-full transition-colors flex items-center gap-2">
                                    <Sparkles size={16} aria-hidden="true" /> Regenerate
                                </button>
                            </div>

                            {analysis?.strategy ? (
                                <div className="prose prose-slate max-w-none font-sans bg-[#F8F9FA] p-8 rounded-[24px] border border-[#DADCE0]">
                                    <div className="whitespace-pre-wrap leading-relaxed text-[#202124]">{analysis.strategy}</div>
                                </div>
                            ) : (
                                <div className="py-24 text-center text-[#70757A]">
                                    <Zap size={48} className="mx-auto mb-4 text-[#DADCE0] animate-pulse" aria-hidden="true" />
                                    <p className="text-lg font-medium">Generating your tailored strategy...</p>
                                    <p className="text-sm mt-2">Connecting your case studies to requirements.</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Sidebar (Right) - Unified Scroll, No Boxes */}
                <div className="w-full md:w-64 shrink-0 space-y-8 order-1 md:order-2">
                    <div className="relative">
                        <label htmlFor="status-select" className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block">Status</label>
                        <div className="relative">
                            <select 
                                id="status-select"
                                value={job.status || 'new'}
                                onChange={handleStatusChange}
                                className={`w-full appearance-none pl-4 pr-10 py-3 rounded-xl font-bold capitalize text-sm border focus:outline-none focus:ring-2 focus:ring-[#1a73e8] cursor-pointer transition-all ${
                                    job.status === 'applied' ? 'bg-[#E8F0FE] text-[#1967D2] border-[#D2E3FC]' :
                                    job.status === 'interview' ? 'bg-[#FEF7E0] text-[#B06000] border-[#FEEFC3]' :
                                    job.status === 'offer' ? 'bg-[#E6F4EA] text-[#137333] border-[#CEEAD6]' :
                                    'bg-white text-[#202124] border-[#DADCE0]'
                                }`}
                            >
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-50" aria-hidden="true" />
                        </div>
                    </div>

                    <div className="cursor-pointer group" onClick={() => setIsEditingLocation(true)}>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block group-hover:text-[#1a73e8] transition-colors">Location</span>
                        {isEditingLocation ? (
                             <input 
                                type="text"
                                value={editedLocation}
                                onChange={(e) => setEditedLocation(e.target.value)}
                                onBlur={handleSaveLocation}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveLocation()}
                                className="text-sm font-semibold text-[#202124] block w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                                aria-label="Edit Location"
                             />
                        ) : (
                             <span className="text-sm font-semibold text-[#202124] block group-hover:text-[#1a73e8] transition-colors flex items-center justify-between">
                                {job.location} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8]" aria-label="Edit Location" />
                             </span>
                        )}
                    </div>

                    <div className="cursor-pointer group" onClick={() => setIsEditingPostedDate(true)}>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block group-hover:text-[#1a73e8] transition-colors">Posted</span>
                         {isEditingPostedDate ? (
                             <input 
                                type="text"
                                value={editedPostedDate}
                                onChange={(e) => setEditedPostedDate(e.target.value)}
                                onBlur={handleSavePostedDate}
                                onKeyDown={(e) => e.key === 'Enter' && handleSavePostedDate()}
                                className="text-sm font-semibold text-[#202124] block w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                                aria-label="Edit Posted Date"
                             />
                        ) : (
                             <span className="text-sm font-semibold text-[#202124] block group-hover:text-[#1a73e8] transition-colors flex items-center justify-between">
                                {job.postedDate || 'Recently'} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8]" aria-label="Edit Posted Date" />
                             </span>
                        )}
                    </div>

                    {analysis && (
                         <div>
                            <div className="flex items-center justify-between mb-1">
                                <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368]">Match Score</span>
                                <button 
                                    onClick={handleReAnalyzeClick}
                                    disabled={isAnalyzing}
                                    className={`text-[#1a73e8] hover:bg-[#E8F0FE] p-1 rounded-full transition-all ${isAnalyzing ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    title="Re-analyze Job Score"
                                    aria-label="Re-analyze Job Score"
                                >
                                    <RotateCw size={14} className={isAnalyzing ? "animate-spin" : ""} />
                                </button>
                            </div>
                            <span className="text-4xl font-black text-[#1a73e8] block">{analysis.score}<span className="text-sm text-[#5F6368] ml-1 font-bold">/100</span></span>
                        </div>
                    )}

                    <div className="pt-4 border-t border-[#F1F3F4]">
                        <div className="flex items-center justify-between mb-2">
                             <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368]">Application Link</span>
                             <button onClick={() => setIsEditingUrl(!isEditingUrl)} className="text-[#1a73e8] hover:bg-[#E8F0FE] p-1 rounded-full" aria-label="Edit Link">
                                 <Edit2 size={12} />
                             </button>
                        </div>

                        {isEditingUrl ? (
                            <div className="mb-2">
                                <input 
                                    type="text"
                                    value={editedUrl}
                                    onChange={(e) => setEditedUrl(e.target.value)}
                                    onBlur={handleSaveUrl}
                                    onKeyDown={(e) => e.key === 'Enter' && handleSaveUrl()}
                                    className="text-sm font-medium text-[#202124] w-full p-2 border border-[#1a73e8] rounded-lg outline-none bg-white"
                                    autoFocus
                                    placeholder="https://..."
                                />
                            </div>
                        ) : null}

                        <a 
                            href={applyUrl} 
                            target="_blank" 
                            rel="noreferrer" 
                            className="flex items-center justify-center gap-2 w-full py-3 bg-[#202124] text-white text-sm font-bold rounded-full hover:shadow-lg hover:bg-[#1a73e8] transition-all"
                        >
                            {getAbsoluteUrl(job.url) ? 'Apply on Site' : 'Search on Google'} <ExternalLink size={16} aria-hidden="true" />
                        </a>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, Check, ChevronDown, RotateCw, TrendingUp, AlertTriangle } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  // URL Editing
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');

  // Re-Analyze State
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
        setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  // URL Logic
  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleSaveUrl = () => {
      if (onUpdateJob && editedUrl.trim() !== job.url) {
          const finalUrl = editedUrl.trim() || 'Manual Entry';
          onUpdateJob({ ...job, url: finalUrl });
      }
      setIsEditingUrl(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  const handleReAnalyzeClick = async () => {
      if (onReAnalyze) {
          setIsAnalyzing(true);
          await onReAnalyze(job);
          setIsAnalyzing(false);
      }
  };

  const isValidAttribute = (attr?: string) => {
      if (!attr) return false;
      const lower = attr.toLowerCase();
      return lower !== 'unspecified' && lower !== 'unknown' && lower !== 'n/a' && attr.trim() !== '';
  };

  return (
    <div 
        className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 transition-all duration-300"
        role="dialog"
        aria-modal="true"
        aria-labelledby="job-detail-title"
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} aria-hidden="true"></div>

      {/* Surface */}
      <div className="relative bg-[#F8F9FA] w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[28px] overflow-hidden border border-white/50 animate-in fade-in zoom-in-95 duration-200">

        {/* Header (Fixed) */}
        <div className="flex items-center justify-between px-6 py-6 sm:px-8 bg-white border-b border-[#DADCE0] shrink-0">
           <div className="flex items-center gap-5 flex-1 mr-4 sm:mr-8">
              <div className="w-14 h-14 bg-[#E8F0FE] text-[#1967D2] rounded-2xl hidden sm:flex items-center justify-center shadow-sm shrink-0" aria-hidden="true">
                  <Briefcase size={28} />
              </div>
              <div className="flex-1 min-w-0">
                  {isEditingTitle ? (
                      <input 
                        type="text" 
                        value={editedTitle}
                        onChange={(e) => setEditedTitle(e.target.value)}
                        onBlur={handleSaveTitle}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                        className="text-xl sm:text-2xl font-bold text-[#202124] w-full border-b-2 border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                        aria-label="Edit Job Title"
                      />
                  ) : (
                      <h2 
                        id="job-detail-title"
                        onClick={() => setIsEditingTitle(true)}
                        className="text-xl sm:text-2xl font-bold text-[#202124] leading-tight truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-full"
                        title="Click to edit title"
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && setIsEditingTitle(true)}
                      >
                        {job.title} <Edit2 size={16} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" aria-label="Edit Title" />
                      </h2>
                  )}

                  {isEditingCompany ? (
                      <input 
                        type="text" 
                        value={editedCompany}
                        onChange={(e) => setEditedCompany(e.target.value)}
                        onBlur={handleSaveCompany}
                        onKeyDown={(e) => e.key === 'Enter' && handleSaveCompany()}
                        className="text-sm text-[#5F6368] font-medium mt-1 w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                        autoFocus
                        aria-label="Edit Company Name"
                      />
                  ) : (
                      <p 
                        onClick={() => setIsEditingCompany(true)}
                        className="text-sm text-[#5F6368] font-medium mt-1 truncate cursor-pointer hover:text-[#1a73e8] transition-colors flex items-center gap-2 group w-fit"
                        title="Click to edit company"
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && setIsEditingCompany(true)}
                      >
                          {job.company} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8] transition-opacity" aria-label="Edit Company" />
                      </p>
                  )}
              </div>
           </div>
           <button 
                onClick={onClose} 
                className="w-10 h-10 flex items-center justify-center hover:bg-[#F1F3F4] rounded-full text-[#5F6368] transition-colors shrink-0 focus:outline-none focus:ring-2 focus:ring-[#1a73e8]"
                aria-label="Close Modal"
           >
             <X size={24} aria-hidden="true" />
           </button>
        </div>

        {/* Unified Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-6 sm:p-8 bg-white">
            <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-12">

                {/* Main Content Area (Left) */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs */}
                    <div className="flex items-center gap-2 mb-8 bg-[#F1F3F4] p-1 rounded-full w-fit border border-[#DADCE0]" role="tablist">
                        <button 
                            role="tab"
                            aria-selected={activeTab === 'brief'}
                            onClick={() => setActiveTab('brief')} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'brief' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <FileText size={14} aria-hidden="true" /> Job Details
                        </button>
                        <button 
                            role="tab"
                            aria-selected={activeTab === 'strategy'}
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`flex items-center gap-2 px-6 py-2 rounded-full text-xs font-bold transition-all ${activeTab === 'strategy' ? 'bg-[#202124] text-white shadow-md' : 'text-[#5F6368] hover:bg-white/50'}`}
                        >
                            <Sparkles size={14} aria-hidden="true" /> Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="prose prose-slate max-w-none text-[#202124]" role="tabpanel">
                            {/* Tags */}
                            <div className="mb-8 flex flex-wrap gap-3" aria-label="Job Attributes">
                                {analysis && analysis.isHighValue && (
                                     <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#E6F4EA] text-[#137333] border border-[#CEEAD6] flex items-center gap-1">
                                        <TrendingUp size={14} aria-hidden="true" /> High Value
                                     </span>
                                )}
                                {analysis && analysis.isCommuteRisk && (
                                     <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#FCE8E6] text-[#C5221F] border border-[#FAD2CF] flex items-center gap-1">
                                        <AlertTriangle size={14} aria-hidden="true" /> Commute Risk
                                     </span>
                                )}
                                {isValidAttribute(analysis?.industry) && (
                                    <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#FFF8E1] text-[#B06000] border border-[#FEEFC3]">
                                        {analysis?.industry}
                                    </span>
                                )}
                                {isValidAttribute(job.seniorityScore) && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{job.seniorityScore}</span>
                                )}
                                {isValidAttribute(analysis?.salary) && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis?.salary}</span>
                                )}
                                {isValidAttribute(analysis?.workPattern) && (
                                    <span className="px-3 py-1 bg-[#F1F3F4] text-[#202124] rounded-full text-xs font-bold border border-[#DADCE0]">{analysis?.workPattern}</span>
                                )}
                            </div>

                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-4">
                                    <h3 className="text-sm font-bold text-[#202124] uppercase tracking-wide">Original Description</h3>
                                    {!isEditingSummary ? (
                                        <button 
                                            onClick={() => setIsEditingSummary(true)}
                                            className="text-xs font-bold text-[#1a73e8] hover:bg-[#E8F0FE] px-3 py-1.5 rounded-full flex items-center gap-1 transition-colors"
                                            aria-label="Edit Job Description"
                                        >
                                            <Edit2 size={12} aria-hidden="true" /> Edit
                                        </button>
                                    ) : (
                                        <button 
                                            onClick={handleSaveDescription}
                                            className="text-xs font-bold text-white bg-[#1a73e8] hover:bg-[#1557B0] px-3 py-1.5 rounded-full flex items-center gap-1 transition-colors shadow-sm"
                                            aria-label="Save Job Description"
                                        >
                                            <Save size={12} aria-hidden="true" /> Save
                                        </button>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <textarea 
                                        value={editedSummary}
                                        onChange={(e) => setEditedSummary(e.target.value)}
                                        className="w-full h-[400px] p-4 border border-[#1a73e8] rounded-xl text-base leading-relaxed focus:outline-none focus:ring-2 focus:ring-[#D2E3FC] bg-white text-[#3C4043] font-sans resize-y"
                                        placeholder="Paste full job description here..."
                                        aria-label="Job Description"
                                    />
                                ) : (
                                    <div className="text-[#3C4043] leading-relaxed whitespace-pre-wrap text-base border border-transparent rounded-xl p-0.5">
                                        {job.summary}
                                    </div>
                                )}
                            </div>

                            {analysis && (
                                <div className="mt-8">
                                    <h4 className="text-sm font-black text-[#1967D2] mb-2 flex items-center gap-2 uppercase tracking-wide">
                                        <Zap size={16} className="fill-[#1967D2]" aria-hidden="true" /> AI Summary
                                    </h4>
                                    <p className="text-[#202124] font-medium mb-6 leading-relaxed text-lg">{analysis.verdict}</p>

                                    <div className="flex flex-wrap gap-2">
                                        {analysis.matchedKeywords.map((kw, i) => (
                                            <span key={i} className="px-4 py-1.5 bg-white border border-[#E8F0FE] text-xs font-bold rounded-full text-[#1967D2]">
                                                {kw}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="animate-in fade-in duration-300" role="tabpanel">
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="text-xl font-bold text-[#202124]">Execution Strategy</h3>
                                <button onClick={() => onGenerateKit(job)} className="text-sm font-bold text-[#1a73e8] hover:bg-[#E8F0FE] px-4 py-2 rounded-full transition-colors flex items-center gap-2">
                                    <Sparkles size={16} aria-hidden="true" /> Regenerate
                                </button>
                            </div>

                            {analysis?.strategy ? (
                                <div className="prose prose-slate max-w-none font-sans bg-[#F8F9FA] p-8 rounded-[24px] border border-[#DADCE0]">
                                    <div className="whitespace-pre-wrap leading-relaxed text-[#202124]">{analysis.strategy}</div>
                                </div>
                            ) : (
                                <div className="py-24 text-center text-[#70757A]">
                                    <Zap size={48} className="mx-auto mb-4 text-[#DADCE0] animate-pulse" aria-hidden="true" />
                                    <p className="text-lg font-medium">Generating your tailored strategy...</p>
                                    <p className="text-sm mt-2">Connecting your case studies to requirements.</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Sidebar (Right) - Unified Scroll, No Boxes */}
                <div className="w-full md:w-64 shrink-0 space-y-8 order-1 md:order-2">
                    <div className="relative">
                        <label htmlFor="status-select" className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block">Status</label>
                        <div className="relative">
                            <select 
                                id="status-select"
                                value={job.status || 'new'}
                                onChange={handleStatusChange}
                                className={`w-full appearance-none pl-4 pr-10 py-3 rounded-xl font-bold capitalize text-sm border focus:outline-none focus:ring-2 focus:ring-[#1a73e8] cursor-pointer transition-all ${
                                    job.status === 'applied' ? 'bg-[#E8F0FE] text-[#1967D2] border-[#D2E3FC]' :
                                    job.status === 'interview' ? 'bg-[#FEF7E0] text-[#B06000] border-[#FEEFC3]' :
                                    job.status === 'offer' ? 'bg-[#E6F4EA] text-[#137333] border-[#CEEAD6]' :
                                    'bg-white text-[#202124] border-[#DADCE0]'
                                }`}
                            >
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-50" aria-hidden="true" />
                        </div>
                    </div>

                    <div className="cursor-pointer group" onClick={() => setIsEditingLocation(true)}>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block group-hover:text-[#1a73e8] transition-colors">Location</span>
                        {isEditingLocation ? (
                             <input 
                                type="text"
                                value={editedLocation}
                                onChange={(e) => setEditedLocation(e.target.value)}
                                onBlur={handleSaveLocation}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveLocation()}
                                className="text-sm font-semibold text-[#202124] block w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                                aria-label="Edit Location"
                             />
                        ) : (
                             <span className="text-sm font-semibold text-[#202124] block group-hover:text-[#1a73e8] transition-colors flex items-center justify-between">
                                {job.location} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8]" aria-label="Edit Location" />
                             </span>
                        )}
                    </div>

                    <div className="cursor-pointer group" onClick={() => setIsEditingPostedDate(true)}>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368] mb-1 block group-hover:text-[#1a73e8] transition-colors">Posted</span>
                         {isEditingPostedDate ? (
                             <input 
                                type="text"
                                value={editedPostedDate}
                                onChange={(e) => setEditedPostedDate(e.target.value)}
                                onBlur={handleSavePostedDate}
                                onKeyDown={(e) => e.key === 'Enter' && handleSavePostedDate()}
                                className="text-sm font-semibold text-[#202124] block w-full border-b border-[#1a73e8] outline-none bg-transparent p-0"
                                autoFocus
                                onClick={(e) => e.stopPropagation()}
                                aria-label="Edit Posted Date"
                             />
                        ) : (
                             <span className="text-sm font-semibold text-[#202124] block group-hover:text-[#1a73e8] transition-colors flex items-center justify-between">
                                {job.postedDate || 'Recently'} <Edit2 size={12} className="opacity-0 group-hover:opacity-100 text-[#1a73e8]" aria-label="Edit Posted Date" />
                             </span>
                        )}
                    </div>

                    {analysis && (
                         <div>
                            <div className="flex items-center justify-between mb-1">
                                <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368]">Match Score</span>
                                <button 
                                    onClick={handleReAnalyzeClick}
                                    disabled={isAnalyzing}
                                    className={`text-[#1a73e8] hover:bg-[#E8F0FE] p-1 rounded-full transition-all ${isAnalyzing ? 'opacity-50 cursor-not-allowed' : ''}`}
                                    title="Re-analyze Job Score"
                                    aria-label="Re-analyze Job Score"
                                >
                                    <RotateCw size={14} className={isAnalyzing ? "animate-spin" : ""} />
                                </button>
                            </div>
                            <span className="text-4xl font-black text-[#1a73e8] block">{analysis.score}<span className="text-sm text-[#5F6368] ml-1 font-bold">/100</span></span>
                        </div>
                    )}

                    <div className="pt-4 border-t border-[#F1F3F4]">
                        <div className="flex items-center justify-between mb-2">
                             <span className="text-[10px] font-bold uppercase tracking-widest text-[#5F6368]">Application Link</span>
                             <button onClick={() => setIsEditingUrl(!isEditingUrl)} className="text-[#1a73e8] hover:bg-[#E8F0FE] p-1 rounded-full" aria-label="Edit Link">
                                 <Edit2 size={12} />
                             </button>
                        </div>

                        {isEditingUrl ? (
                            <div className="mb-2">
                                <input 
                                    type="text"
                                    value={editedUrl}
                                    onChange={(e) => setEditedUrl(e.target.value)}
                                    onBlur={handleSaveUrl}
                                    onKeyDown={(e) => e.key === 'Enter' && handleSaveUrl()}
                                    className="text-sm font-medium text-[#202124] w-full p-2 border border-[#1a73e8] rounded-lg outline-none bg-white"
                                    autoFocus
                                    placeholder="https://..."
                                />
                            </div>
                        ) : null}

                        <a 
                            href={applyUrl} 
                            target="_blank" 
                            rel="noreferrer" 
                            className="flex items-center justify-center gap-2 w-full py-3 bg-[#202124] text-white text-sm font-bold rounded-full hover:shadow-lg hover:bg-[#1a73e8] transition-all"
                        >
                            {getAbsoluteUrl(job.url) ? 'Apply on Site' : 'Search on Google'} <ExternalLink size={16} aria-hidden="true" />
                        </a>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

import React, { useState, useEffect } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { Bot, Layout, Columns, FileText, CheckCircle2, Filter, Sparkles, Plus, Search, ArrowDownUp, Globe, Link, Briefcase, Settings, Sidebar } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected, setIsDbConnected] = useState(() => {
    return initFirebase(DEFAULT_FIREBASE_CONFIG);
  });

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          // Manually update allJobs to reflect change immediately if needed, though subscription usually handles it
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView === ViewState.DASHBOARD) {
              setActiveTab('saved');
          }
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }

          // 1. Create Placeholder immediately (works for both URL and Text)
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);

          // 2. Enrich with AI (handles both cases)
          const enrichedDetails = await enrichJob(data);

          // Merge details. Priority: AI enrichment > Manual Input > Placeholder defaults
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              // If we have manual text, ensure it isn't overwritten by empty AI result
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };

          await addOrUpdateJob(enrichedJob);

          // 3. Analyze
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);

      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const locationCounts = allJobs.reduce((acc, job) => {
    const locRaw = job.location.toLowerCase();
    let key = 'Other';
    if (locRaw.includes('edinburgh')) key = 'Edinburgh';
    else if (locRaw.includes('glasgow')) key = 'Glasgow';
    else if (locRaw.includes('remote')) key = 'Remote';
    else if (locRaw.includes('london')) key = 'London';
    else if (locRaw.includes('manchester')) key = 'Manchester';
    if ((job.status || 'new') === 'new') {
        acc[key] = (acc[key] || 0) + 1;
        acc['All'] = (acc['All'] || 0) + 1;
    }
    return acc;
  }, { 'All': 0 } as Record<string, number>);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const filteredJobs = allJobs.filter(j => {
    const status = j.status || 'new';
    if (activeTab === 'new') return status === 'new';
    if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
    if (activeTab === 'archived') return status === 'archived';
    return true;
  }).filter(j => {
    const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
    if (!locMatch) return false;

    // Industry Filter
    if (industryFilter) {
        const ind = j.analysis?.industry || 'Tech';
        if (ind !== industryFilter) {
             const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
             let calculatedIndustry = 'Tech';
             if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
             else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
             else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
             else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

             if (calculatedIndustry !== industryFilter) return false;
        }
    }
    return true;
  }).sort((a, b) => {
      if (sortBy === 'score') {
          return (b.analysis?.score || 0) - (a.analysis?.score || 0);
      }
      return (b.scoutedAt || 0) - (a.scoutedAt || 0);
  });

  return (
    <div className="flex h-screen w-screen p-4 gap-4 overflow-hidden">
        {/* macOS Window Container */}
        <div className="flex w-full h-full rounded-2xl mac-shadow overflow-hidden border border-white/20">

            {/* SIDEBAR (Finder Style) */}
            <div className="w-[260px] flex-none glass-sidebar flex flex-col justify-between">
                <div>
                    {/* Window Controls */}
                    <div className="h-12 flex items-center px-4 gap-2 border-b border-black/5">
                        <div className="w-3 h-3 rounded-full bg-[#FF5F57] shadow-sm"></div>
                        <div className="w-3 h-3 rounded-full bg-[#FEBC2E] shadow-sm"></div>
                        <div className="w-3 h-3 rounded-full bg-[#28C840] shadow-sm"></div>
                    </div>

                    <div className="p-4 space-y-6">
                        {/* Profile Summary */}
                        <div className="flex items-center gap-3 px-2">
                            <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center text-white font-semibold text-xs shadow-md bg-gradient-to-br from-blue-400 to-blue-600">
                                VP
                            </div>
                            <div>
                                <h3 className="text-sm font-semibold text-gray-900 leading-none">Vyom Pathroliya</h3>
                                <p className="text-[10px] text-gray-500 mt-1">Job Agent Active</p>
                            </div>
                        </div>

                        {/* Navigation Group */}
                        <div className="space-y-1">
                            <p className="px-2 text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2">Workspace</p>
                            {[
                                { id: ViewState.DASHBOARD, label: 'Dashboard', icon: Layout },
                                { id: ViewState.KANBAN, label: 'Board', icon: Columns },
                                { id: ViewState.CV_EDITOR, label: 'CV Editor', icon: FileText }
                            ].map(item => (
                                <button 
                                    key={item.id}
                                    onClick={() => setCurrentView(item.id)}
                                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-all ${currentView === item.id ? 'bg-black/10 text-black shadow-inner' : 'text-gray-600 hover:bg-black/5'}`}
                                >
                                    <item.icon size={16} strokeWidth={2} />
                                    {item.label}
                                </button>
                            ))}
                        </div>

                        {/* Smart Filters Group */}
                        {currentView === ViewState.DASHBOARD && (
                            <div className="space-y-1">
                                <p className="px-2 text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2 mt-4">Smart Filters</p>
                                {filterOptions.map(city => {
                                    const count = locationCounts[city] || 0;
                                    if (count === 0 && city !== 'All') return null;
                                    return (
                                        <button 
                                            key={city} 
                                            onClick={() => setCityFilter(city)} 
                                            className={`w-full flex items-center justify-between px-3 py-1.5 rounded-lg text-xs transition-all ${cityFilter === city ? 'bg-[#007AFF] text-white shadow-sm' : 'text-gray-600 hover:bg-black/5'}`}
                                        >
                                            <span className="font-medium">{city}</span>
                                            <span className={`px-1.5 py-0.5 rounded text-[10px] ${cityFilter === city ? 'bg-white/20' : 'bg-black/5'}`}>{count}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        {currentView === ViewState.DASHBOARD && (
                            <div className="mt-4 pt-4 border-t border-black/5">
                                <StatsPanel 
                                    jobs={allJobs} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        )}
                    </div>
                </div>

                <div className="p-4 border-t border-black/5">
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Settings size={12} />
                        <span>v1.2.0 • Online</span>
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 bg-white/80 backdrop-blur-3xl flex flex-col relative">

                {/* Top Toolbar (Mimics Finder Toolbar) */}
                <div className="h-12 border-b border-black/5 flex items-center justify-between px-6 bg-white/50 backdrop-blur-md sticky top-0 z-20">
                    <div className="flex items-center gap-4">
                        <button onClick={() => history.back()} className="text-gray-400 hover:text-gray-600 transition-colors"><Sidebar size={18} /></button>
                        <h1 className="text-sm font-bold text-gray-800">{currentView === ViewState.DASHBOARD ? 'Discover' : currentView === ViewState.KANBAN ? 'Pipeline' : 'CV Editor'}</h1>
                    </div>

                    <div className="flex items-center gap-3">
                        {currentView === ViewState.DASHBOARD && (
                            <div className="flex bg-black/5 rounded-lg p-0.5">
                                {['new', 'saved', 'archived'].map((tab) => {
                                    const count = allJobs.filter(j => {
                                        if (tab === 'new') return (j.status || 'new') === 'new';
                                        if (tab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(j.status || '');
                                        return j.status === 'archived';
                                    }).length;
                                    return (
                                        <button 
                                            key={tab}
                                            onClick={() => setActiveTab(tab as any)}
                                            className={`px-3 py-1 rounded-[6px] text-xs font-medium capitalize transition-all ${activeTab === tab ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-gray-800'}`}
                                        >
                                            {tab} <span className="opacity-50 ml-1">{count}</span>
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        <div className="h-4 w-px bg-black/10 mx-1"></div>

                        {analyzingCount > 0 && (
                            <div className="flex items-center gap-2 px-3 py-1 bg-white/50 border border-black/5 rounded-md shadow-sm">
                                <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                                <span className="text-xs font-medium text-gray-600">Analyzing {analyzingCount}...</span>
                            </div>
                        )}

                        <button 
                            onClick={() => setIsAddLinkOpen(true)}
                            className="p-1.5 rounded-md hover:bg-black/5 text-gray-600 transition-colors"
                            title="Add Job"
                        >
                            <Plus size={18} strokeWidth={2} />
                        </button>

                        <button 
                            onClick={fetchJobs}
                            disabled={isFetching}
                            className={`p-1.5 rounded-md hover:bg-black/5 text-gray-600 transition-colors ${isFetching ? 'animate-spin opacity-50' : ''}`}
                            title="Scout Jobs"
                        >
                            <Search size={18} strokeWidth={2} />
                        </button>
                    </div>
                </div>

                {/* Content Body */}
                <div className="flex-1 overflow-y-auto custom-scrollbar p-6 bg-transparent">
                    {currentView === ViewState.DASHBOARD && (
                        <div className="space-y-4 pb-20">
                            {filteredJobs.length === 0 ? (
                                <div className="flex flex-col items-center justify-center h-[400px] text-gray-400">
                                    <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                                        <CheckCircle2 size={32} className="text-gray-300" />
                                    </div>
                                    <h3 className="text-lg font-semibold text-gray-600">No jobs found</h3>
                                    <p className="text-sm">Try adjusting your filters or scouting for new roles.</p>
                                    {(cityFilter !== 'All' || industryFilter) && (
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="mt-4 text-[#007AFF] text-sm font-medium hover:underline">Clear Filters</button>
                                    )}
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 gap-4">
                                    {filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {currentView === ViewState.KANBAN && (
                        <KanbanBoard 
                            jobs={allJobs} 
                            onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                            onToggleStatus={handleKanbanMove}
                            onDelete={handleDelete}
                            onOpenDetail={handleOpenDetail}
                            onOpenAddModal={() => setIsAddLinkOpen(true)}
                        />
                    )}

                    {currentView === ViewState.CV_EDITOR && (
                        <CVEditor />
                    )}
                </div>
            </div>
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, FileText, TrendingUp, Trash2, Clock, Zap, Bookmark, Archive, MoreHorizontal } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="bg-white/60 backdrop-blur-md p-4 rounded-xl shadow-sm border border-white/40 hover:shadow-md transition-all group flex flex-col gap-3 relative cursor-pointer hover:border-[#007AFF]/50 outline-none"
            tabIndex={0}
            role="button"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-2">
                <h4 className="font-semibold text-[13px] text-[#1d1d1f] leading-snug line-clamp-2">
                    {job.title}
                </h4>
                {analysis && (
                    <div 
                        className={`shrink-0 w-2 h-2 rounded-full ${analysis.isHighValue ? 'bg-[#34C759]' : 'bg-gray-300'}`} 
                        title={analysis.isHighValue ? "High Value" : "Standard"}
                    ></div>
                )}
            </div>

            <p className="text-[11px] font-medium text-gray-500 line-clamp-1">{job.company}</p>

            <div className="flex items-center gap-2 mt-1">
                <button 
                    onClick={(e) => { e.stopPropagation(); onOpenDetail(job); }} 
                    className="w-full py-1.5 text-[11px] font-medium text-gray-600 hover:bg-black/5 rounded-lg transition-colors flex items-center justify-center gap-1.5"
                >
                    Details
                </button>
            </div>
        </div>
      );
  }

  return (
    <div className={`bg-white/70 backdrop-blur-xl rounded-2xl p-6 shadow-sm border border-white/50 hover:shadow-lg transition-all duration-300 relative group overflow-hidden ${status === 'archived' ? 'opacity-50 grayscale' : ''}`}>

