            onClick={() => onDelete(job.id)} 
            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all" 
            title={status === 'archived' ? "Delete Permanently" : "Archive"}
         >
            {status === 'archived' ? <Trash2 size={16} /> : <Archive size={16} />}
         </button>

         {status !== 'archived' && (
             <button 
                onClick={() => onToggleStatus(job.id, status)}
                className={`p-2 rounded-lg transition-all ${isSavedOrBetter 
                    ? 'text-[#007AFF] bg-blue-50' 
                    : 'text-gray-400 hover:bg-black/5'}`}
             >
                 <Bookmark size={16} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}
      </div>

      <div className="flex flex-col md:flex-row gap-6 items-start">
          {/* Score Circle - iOS Health Ring Style */}
          <div className="shrink-0 pt-1" aria-hidden="true">
             {analysis ? (
                 <div className="w-14 h-14 rounded-full bg-white shadow-sm border border-gray-100 flex flex-col items-center justify-center relative overflow-hidden">
                    {/* Ring simulation */}
                    <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 36 36">
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="#E5E5EA" strokeWidth="3" />
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke={analysis.score > 70 ? '#34C759' : '#007AFF'} strokeWidth="3" strokeDasharray={`${analysis.score}, 100`} />
                    </svg>
                    <span className="text-sm font-bold text-gray-900 z-10">{analysis.score}</span>
                 </div>
             ) : (
                 <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center animate-pulse">
                     <span className="text-[9px] font-bold text-gray-400">SCAN</span>
                 </div>
             )}
          </div>

          <div className="flex-1 pr-10">
             <div 
                className="cursor-pointer group/title focus:outline-none" 
                onClick={() => onOpenDetail(job)}
             >
                <div className="flex items-center gap-2 mb-1">
                    <h3 className="text-lg font-semibold text-[#1d1d1f] tracking-tight group-hover/title:text-[#007AFF] transition-colors leading-tight">
                        {job.title}
                    </h3>
                    {job.isRelatedDiscovery && <span className="bg-yellow-100 text-yellow-700 text-[9px] font-bold px-1.5 py-0.5 rounded-full border border-yellow-200">NEW FIND</span>}
                </div>

                <div className="flex flex-wrap items-center gap-4 text-xs font-medium text-gray-500 mb-3">
                    <span className="flex items-center gap-1">{job.company}</span>
                    <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                    <span className="flex items-center gap-1">{job.location}</span>
                    <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                    <span>{job.postedDate}</span>
                </div>
             </div>

             {/* Tags - iOS Style Chips */}
             <div className="flex flex-wrap items-center gap-2 mt-2 mb-4">
                {job.seniorityScore && (
                     <span className="px-2.5 py-1 rounded-md text-[10px] font-semibold bg-gray-100 text-gray-600 border border-gray-200/50">{job.seniorityScore}</span>
                )}
                {analysis && analysis.isHighValue && (
                     <span className="px-2.5 py-1 rounded-md text-[10px] font-semibold bg-green-50 text-green-700 border border-green-100 flex items-center gap-1"><TrendingUp size={10} /> High Value</span>
                )}
                {analysis && analysis.isCommuteRisk && (
                     <span className="px-2.5 py-1 rounded-md text-[10px] font-semibold bg-orange-50 text-orange-700 border border-orange-100 flex items-center gap-1"><AlertTriangle size={10} /> Risk</span>
                )}
                 {analysis?.industry && (
                     <span className="px-2.5 py-1 rounded-md text-[10px] font-semibold bg-blue-50 text-blue-700 border border-blue-100">{analysis.industry}</span>
                )}
             </div>

             {/* Verdict */}
             {analysis && (
                 <div className="mb-4">
                    <p className="text-[13px] text-gray-600 leading-relaxed font-normal">{analysis.verdict}</p>
                 </div>
             )}

             {/* Actions */}
             <div className="flex items-center gap-3 mt-4">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="px-4 py-1.5 rounded-lg text-xs font-medium bg-[#1d1d1f] text-white hover:bg-black hover:shadow-md transition-all flex items-center gap-1.5 shadow-sm"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply' : 'Google Search'} <ExternalLink size={12} />
                 </a>
                 <button 
                    onClick={() => onOpenDetail(job)}
                    className="px-4 py-1.5 rounded-lg text-xs font-medium bg-white text-gray-700 border border-gray-200 hover:bg-gray-50 transition-all shadow-sm"
                 >
                     View Analysis
                 </button>
             </div>
          </div>
      </div>
    </div>
  );
};

