import React from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Job } from '../types';

interface StatsPanelProps {
  jobs: Job[];
  selectedIndustry: string | null;
  onSelectIndustry: (industry: string | null) => void;
}

// macOS Palette
const COLORS = [
  '#007AFF', // Blue
  '#FF2D55', // Pink
  '#FFCC00', // Yellow
  '#34C759', // Green
  '#AF52DE', // Purple
  '#5856D6'  // Indigo
];

const StatsPanel: React.FC<StatsPanelProps> = ({ jobs, selectedIndustry, onSelectIndustry }) => {
  const getIndustry = (job: Job): string => {
    if (job.analysis?.industry && job.analysis.industry !== "Other") {
        return job.analysis.industry;
    }
    const text = (job.company + " " + job.title + " " + (job.summary || "")).toLowerCase();
    if (text.match(/bank|finance|wealth|fintech/)) return 'Fintech';
    if (text.match(/insurance|underwrit/)) return 'Insurance';
    if (text.match(/gov|public|council|nhs/)) return 'Public Sector';
    if (text.match(/agency|studio/)) return 'Agency';
    return 'Tech';
  };

  const industryCounts = jobs.reduce((acc, job) => {
    if ((job.status || 'new') !== 'new') return acc;
    const industry = getIndustry(job);
    acc[industry] = (acc[industry] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const data = Object.entries(industryCounts)
    .map(([name, value]) => ({ name, value: value as number }))
    .filter((item) => item.value > 0)
    .sort((a, b) => b.value - a.value);

  const totalJobs = data.reduce((sum, item) => sum + item.value, 0);

  if (totalJobs === 0) return null;

  return (
    <div className="rounded-xl">
      <div className="flex items-center justify-between mb-4 px-1">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Breakdown</h3>
        {selectedIndustry && (
            <button 
                onClick={() => onSelectIndustry(null)}
                className="text-[9px] font-bold text-[#007AFF] hover:bg-black/5 px-2 py-0.5 rounded transition-colors"
            >
                RESET
            </button>
        )}
      </div>

      <div className="h-[120px] relative mb-4 cursor-pointer">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie 
                data={data} 
                cx="50%" 
                cy="50%" 
                innerRadius={35} 
                outerRadius={50} 
                paddingAngle={2} 
                dataKey="value" 
                stroke="none" 
                cornerRadius={3}
                onClick={(data) => {
                    const newSelection = selectedIndustry === data.name ? null : data.name;
                    onSelectIndustry(newSelection);
                }}
            >
              {data.map((entry, index) => (
                <Cell 
                    key={`cell-${index}`} 
                    fill={COLORS[index % COLORS.length]} 
                    opacity={selectedIndustry && selectedIndustry !== entry.name ? 0.3 : 1}
                    style={{ outline: 'none' }}
                />
              ))}
            </Pie>
            <Tooltip 
              contentStyle={{ borderRadius: '8px', border: 'none', padding: '6px', fontSize: '11px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
              itemStyle={{ color: '#1d1d1f' }}
            />
          </PieChart>
        </ResponsiveContainer>

        {/* Center Text */}
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
             <span className="text-xl font-bold text-[#1d1d1f]">{selectedIndustry ? data.find(d => d.name === selectedIndustry)?.value : totalJobs}</span>
        </div>
      </div>

      <div className="space-y-1">
        {data.slice(0, 4).map((entry, index) => {
          const isSelected = selectedIndustry === entry.name;
          return (
            <button
                key={entry.name} 
                onClick={() => onSelectIndustry(isSelected ? null : entry.name)}
                className={`w-full flex items-center justify-between text-[11px] cursor-pointer px-2 py-1 rounded transition-colors ${isSelected ? 'bg-black/5 font-medium text-black' : 'text-gray-500 hover:bg-black/5'}`}
            >
               <div className="flex items-center gap-2">
                 <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                 <span>{entry.name}</span>
               </div>
               <span>{entry.value}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default StatsPanel;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, Check, ChevronDown, RotateCw, TrendingUp, AlertTriangle } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  // URL Editing
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');

  // Re-Analyze State
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
        setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  // URL Logic
  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleSaveUrl = () => {
      if (onUpdateJob && editedUrl.trim() !== job.url) {
          const finalUrl = editedUrl.trim() || 'Manual Entry';
          onUpdateJob({ ...job, url: finalUrl });
      }
      setIsEditingUrl(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  const handleReAnalyzeClick = async () => {
      if (onReAnalyze) {
          setIsAnalyzing(true);
          await onReAnalyze(job);
          setIsAnalyzing(false);
      }
  };

  const isValidAttribute = (attr?: string) => {
      if (!attr) return false;
      const lower = attr.toLowerCase();
      return lower !== 'unspecified' && lower !== 'unknown' && lower !== 'n/a' && attr.trim() !== '';
  };

  return (
    <div 
        className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-10 transition-all duration-300"
        role="dialog"
        aria-modal="true"
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/20 backdrop-blur-sm" onClick={onClose}></div>

      {/* Surface - macOS Window */}
      <div className="relative bg-white/90 backdrop-blur-2xl w-full max-w-5xl h-[85vh] flex flex-col shadow-2xl rounded-xl border border-white/20 overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Title Bar */}
        <div className="h-12 bg-white/50 border-b border-black/5 flex items-center justify-between px-4 shrink-0 drag-handle">
           <div className="flex gap-2">
                {/* Traffic Lights */}
                <button onClick={onClose} className="w-3 h-3 rounded-full bg-[#FF5F57] hover:bg-[#FF5F57]/80 border border-black/10"></button>
                <div className="w-3 h-3 rounded-full bg-[#FEBC2E] border border-black/10"></div>
                <div className="w-3 h-3 rounded-full bg-[#28C840] border border-black/10"></div>
           </div>

           <div className="text-sm font-semibold text-gray-600 opacity-80 flex gap-2 items-center">
               <Briefcase size={14} /> {job.company}
           </div>

           <div className="w-10"></div> {/* Spacer for balance */}
        </div>

        {/* Unified Scrollable Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-8">
            <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-12">

                {/* Main Content Area (Left) */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Header Info */}
                    <div className="mb-8">
                        {isEditingTitle ? (
                            <input 
                                type="text" 
                                value={editedTitle}
                                onChange={(e) => setEditedTitle(e.target.value)}
                                onBlur={handleSaveTitle}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                                className="text-3xl font-bold text-gray-900 w-full bg-transparent outline-none border-b border-blue-500"
                                autoFocus
                            />
                        ) : (
                            <h2 onClick={() => setIsEditingTitle(true)} className="text-3xl font-bold text-gray-900 leading-tight mb-2 hover:opacity-70 cursor-text">{job.title}</h2>
                        )}

                        <div className="flex gap-4 text-sm text-gray-500 font-medium">
                             {isEditingCompany ? (
                                <input 
                                    type="text" 
                                    value={editedCompany}
                                    onChange={(e) => setEditedCompany(e.target.value)}
                                    onBlur={handleSaveCompany}
                                    className="bg-transparent border-b border-blue-500 outline-none w-32"
                                />
                             ) : (
                                <span onClick={() => setIsEditingCompany(true)} className="hover:text-blue-600 cursor-pointer">{job.company}</span>
                             )}
                             <span>•</span>
                             <span>{job.location}</span>
                        </div>
                    </div>

                    {/* Segmented Control Tabs */}
                    <div className="flex p-1 bg-gray-100/80 rounded-lg w-fit mb-8 shadow-inner">
                        <button 
                            onClick={() => setActiveTab('brief')} 
                            className={`px-6 py-1.5 text-xs font-semibold rounded-md transition-all ${activeTab === 'brief' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-900'}`}
                        >
                            Job Details
                        </button>
                        <button 
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`px-6 py-1.5 text-xs font-semibold rounded-md transition-all ${activeTab === 'strategy' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-900'}`}
                        >
                            Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="text-gray-800" role="tabpanel">
                            {/* Tags */}
                            <div className="mb-8 flex flex-wrap gap-2">
                                {analysis && analysis.isHighValue && (
                                     <span className="px-3 py-1 rounded-full text-xs font-medium bg-green-100 text-green-700">High Value</span>
                                )}
                                {isValidAttribute(analysis?.industry) && (
                                    <span className="px-3 py-1 rounded-full text-xs font-medium bg-blue-50 text-blue-700">{analysis?.industry}</span>
                                )}
                                {isValidAttribute(job.seniorityScore) && (
                                    <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-xs font-medium">{job.seniorityScore}</span>
                                )}
                                {isValidAttribute(analysis?.salary) && (
                                    <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-xs font-medium">{analysis?.salary}</span>
                                )}
                            </div>

                            {/* AI Summary Block */}
                            {analysis && (
                                <div className="mb-8 p-6 bg-blue-50/50 rounded-xl border border-blue-100 backdrop-blur-sm">
                                    <h4 className="text-xs font-bold text-blue-600 mb-2 uppercase tracking-wide flex items-center gap-2">
                                        <Zap size={14} /> AI Verdict
                                    </h4>
                                    <p className="text-gray-900 font-medium leading-relaxed">{analysis.verdict}</p>
                                </div>
                            )}

                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-4 border-b border-gray-200 pb-2">
                                    <h3 className="text-sm font-semibold text-gray-900">Description</h3>
                                    {!isEditingSummary ? (
                                        <button onClick={() => setIsEditingSummary(true)} className="text-xs text-blue-600 font-medium hover:underline">Edit</button>
                                    ) : (
                                        <button onClick={handleSaveDescription} className="text-xs text-blue-600 font-bold hover:underline">Done</button>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <textarea 
                                        value={editedSummary}
                                        onChange={(e) => setEditedSummary(e.target.value)}
                                        className="w-full h-[400px] p-4 border border-blue-500 rounded-lg text-sm leading-relaxed focus:outline-none bg-white font-sans resize-y shadow-inner"
                                    />
                                ) : (
                                    <div className="text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">
                                        {job.summary}
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="animate-in fade-in slide-in-from-bottom-4 duration-300" role="tabpanel">
                            {analysis?.strategy ? (
                                <div className="prose prose-sm max-w-none font-sans text-gray-800">
                                    <div className="whitespace-pre-wrap leading-relaxed">{analysis.strategy}</div>
                                </div>
                            ) : (
                                <div className="py-24 text-center text-gray-400">
                                    <Sparkles size={32} className="mx-auto mb-4 animate-pulse text-yellow-400" />
                                    <p className="font-medium">Generating strategy...</p>
