                    <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                        <label className="text-[10px] font-bold uppercase tracking-wider text-gray-400 mb-2 block">Status</label>
                        <select 
                            value={job.status || 'new'}
                            onChange={handleStatusChange}
                            className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 text-sm font-medium text-gray-700 shadow-sm focus:border-blue-500 outline-none"
                        >
                            <option value="saved">Saved</option>
                            <option value="applied">Applied</option>
                            <option value="interview">Interview</option>
