                            <button onClick={handleReAnalyzeClick} className={`text-blue-500 hover:bg-blue-50 p-1 rounded ${isAnalyzing ? 'animate-spin' : ''}`}><RotateCw size={12} /></button>
                        </div>
                        <div className="text-4xl font-extrabold text-gray-900 tracking-tight flex items-baseline">
                            {analysis?.score || 0}
                            <span className="text-lg text-gray-300 ml-1 font-medium">/100</span>
                        </div>
                        <div className="w-full bg-gray-100 h-1.5 rounded-full mt-2 overflow-hidden">
                            <div className="bg-[#34C759] h-full rounded-full" style={{ width: `${analysis?.score || 0}%` }}></div>
                        </div>
                    </div>

                    <div className="space-y-4 pt-4 border-t border-gray-100">
                        <div className="group">
                            <label className="text-[10px] font-bold uppercase tracking-wider text-gray-400 block mb-1">Location</label>
