                            <label className="text-[10px] font-bold uppercase tracking-wider text-gray-400 block mb-1">Posted</label>
                            {isEditingPostedDate ? (
                                <input value={editedPostedDate} onChange={e => setEditedPostedDate(e.target.value)} onBlur={handleSavePostedDate} className="text-sm border-b border-blue-500 outline-none w-full" autoFocus />
                            ) : (
                                <p onClick={() => setIsEditingPostedDate(true)} className="text-sm font-medium text-gray-700 hover:text-blue-600 cursor-pointer">{job.postedDate}</p>
                            )}
                        </div>
                    </div>

                    <div className="pt-6">
                        <a 
                            href={applyUrl} 
                            target="_blank" 
                            rel="noreferrer" 
                            className="flex items-center justify-center gap-2 w-full py-3 bg-[#1d1d1f] text-white text-sm font-semibold rounded-lg hover:bg-black hover:shadow-lg transition-all"
                        >
                            {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={14} />
                        </a>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

import React, { useState, useEffect } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Columns, FileText, CheckCircle2, Plus, Search, Sidebar, Settings, Bell, ChevronLeft, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        // Auto-archive logic
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // derived state
  const locationCounts = allJobs.reduce((acc, job) => {
    const locRaw = job.location.toLowerCase();
    let key = 'Other';
    if (locRaw.includes('edinburgh')) key = 'Edinburgh';
    else if (locRaw.includes('glasgow')) key = 'Glasgow';
    else if (locRaw.includes('remote')) key = 'Remote';
    else if (locRaw.includes('london')) key = 'London';
    else if (locRaw.includes('manchester')) key = 'Manchester';
    if ((job.status || 'new') === 'new') {
        acc[key] = (acc[key] || 0) + 1;
        acc['All'] = (acc['All'] || 0) + 1;
    }
    return acc;
  }, { 'All': 0 } as Record<string, number>);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const filteredJobs = allJobs.filter(j => {
    const status = j.status || 'new';
    if (activeTab === 'new') return status === 'new';
    if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
    if (activeTab === 'archived') return status === 'archived';
    return true;
  }).filter(j => {
    const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
    if (!locMatch) return false;

    // Industry Filter
    if (industryFilter) {
        const ind = j.analysis?.industry || 'Tech';
        if (ind !== industryFilter) {
             const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
             let calculatedIndustry = 'Tech';
             if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
             else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
             else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
             else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

             if (calculatedIndustry !== industryFilter) return false;
        }
    }
    return true;
  }).sort((a, b) => {
      if (sortBy === 'score') {
          return (b.analysis?.score || 0) - (a.analysis?.score || 0);
      }
      return (b.scoutedAt || 0) - (a.scoutedAt || 0);
  });

  return (
    <div className="flex h-screen w-screen p-4 sm:p-6 overflow-hidden">
        {/* MAIN APP WINDOW FRAME */}
        <div className="flex w-full h-full rounded-[24px] shadow-2xl overflow-hidden border border-white/20 bg-transparent backdrop-blur-3xl relative">

            {/* --- SIDEBAR (Finder Style) --- */}
            <div className="w-[280px] flex-none glass-sidebar flex flex-col justify-between z-10">
                <div>
                    {/* Traffic Lights */}
                    <div className="h-14 flex items-center px-5 gap-2 group">
                        <div className="w-3 h-3 rounded-full bg-[#FF5F57] shadow-sm border border-[#E0443E] group-hover:flex items-center justify-center text-[8px] text-black/50 font-bold opacity-80 transition-all"></div>
                        <div className="w-3 h-3 rounded-full bg-[#FEBC2E] shadow-sm border border-[#D89E24] group-hover:flex items-center justify-center text-[8px] text-black/50 font-bold opacity-80 transition-all"></div>
                        <div className="w-3 h-3 rounded-full bg-[#28C840] shadow-sm border border-[#1AAB29] group-hover:flex items-center justify-center text-[8px] text-black/50 font-bold opacity-80 transition-all"></div>
                    </div>

                    <div className="px-3 py-2 space-y-6">
                        {/* Navigation */}
                        <div className="space-y-1">
                            {[
                                { id: ViewState.DASHBOARD, label: 'Discover', icon: LayoutGrid },
                                { id: ViewState.KANBAN, label: 'Board', icon: Columns },
                                { id: ViewState.CV_EDITOR, label: 'CV Editor', icon: FileText }
                            ].map(item => (
                                <button 
                                    key={item.id}
                                    onClick={() => setCurrentView(item.id)}
                                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-[13px] font-medium transition-all duration-200 ${currentView === item.id ? 'bg-black/10 text-black' : 'text-gray-600 hover:bg-black/5'}`}
                                >
                                    <item.icon size={16} strokeWidth={2} />
                                    {item.label}
                                </button>
                            ))}
                        </div>

                        {/* Smart Filters Group */}
                        {currentView === ViewState.DASHBOARD && (
                            <div className="space-y-1">
                                <p className="px-3 text-[11px] font-semibold text-gray-400 uppercase tracking-wide mb-2 mt-4">Locations</p>
                                {filterOptions.map(city => {
                                    const count = locationCounts[city] || 0;
                                    if (count === 0 && city !== 'All') return null;
                                    return (
                                        <button 
                                            key={city} 
                                            onClick={() => setCityFilter(city)} 
                                            className={`w-full flex items-center justify-between px-3 py-1.5 rounded-lg text-[13px] transition-all ${cityFilter === city ? 'bg-[#007AFF] text-white shadow-sm' : 'text-gray-600 hover:bg-black/5'}`}
                                        >
                                            <span className="font-medium">{city}</span>
                                            {count > 0 && <span className={`px-1.5 py-0.5 rounded text-[10px] ${cityFilter === city ? 'bg-white/20' : 'bg-black/5 text-gray-500'}`}>{count}</span>}
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        {currentView === ViewState.DASHBOARD && (
                            <div className="mt-4 pt-4 border-t border-black/5 px-2">
                                <StatsPanel 
                                    jobs={allJobs} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        )}
                    </div>
                </div>

                {/* User Profile Footer */}
                <div className="p-4 border-t border-black/5 flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-blue-400 to-indigo-500 shadow-inner"></div>
                    <div>
                        <p className="text-xs font-semibold text-gray-800">Vyom Pathroliya</p>
                        <p className="text-[10px] text-gray-500">Pro Plan</p>
                    </div>
                    <Settings size={14} className="ml-auto text-gray-400 hover:text-gray-600 cursor-pointer" />
                </div>
            </div>

            {/* --- MAIN CONTENT CANVAS --- */}
            <div className="flex-1 glass-content flex flex-col relative">

                {/* Top Toolbar */}
                <div className="h-14 border-b border-black/5 flex items-center justify-between px-6 shrink-0">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center text-gray-400">
                             <ChevronLeft size={20} className="hover:text-gray-600 cursor-pointer" />
                             <ChevronRight size={20} className="hover:text-gray-600 cursor-pointer opacity-50" />
                        </div>
                        <h1 className="text-sm font-bold text-gray-800 opacity-90">
                            {currentView === ViewState.DASHBOARD ? 'Market Overview' : currentView === ViewState.KANBAN ? 'Application Pipeline' : 'Resume'}
                        </h1>
                    </div>

                    <div className="flex items-center gap-3">
                         {/* Search Bar */}
                         <div className="relative group">
                             <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-[#007AFF]" />
                             <input 
                                type="text" 
                                placeholder="Search..." 
                                className="pl-9 pr-3 py-1.5 bg-black/5 border border-transparent rounded-md text-xs font-medium focus:bg-white focus:shadow-sm focus:border-black/10 focus:outline-none transition-all w-48 placeholder:text-gray-400"
                             />
                         </div>

                         {currentView === ViewState.DASHBOARD && (
                            <div className="flex bg-black/5 rounded-lg p-0.5">
                                {['new', 'saved', 'archived'].map((tab) => (
                                    <button 
                                        key={tab}
                                        onClick={() => setActiveTab(tab as any)}
                                        className={`px-3 py-1 rounded-[6px] text-[11px] font-medium capitalize transition-all ${activeTab === tab ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-gray-800'}`}
                                    >
                                        {tab}
                                    </button>
                                ))}
                            </div>
                        )}

                        <div className="h-4 w-px bg-black/10 mx-1"></div>

                        {analyzingCount > 0 && (
                            <div className="flex items-center gap-2 px-3 py-1 bg-white/50 border border-black/5 rounded-md shadow-sm">
                                <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                                <span className="text-[10px] font-bold text-gray-600">Analyzing...</span>
                            </div>
                        )}

                        <button onClick={() => setIsAddLinkOpen(true)} className="p-1.5 rounded-md hover:bg-black/5 text-gray-600 transition-colors" title="Add Job">
                            <Plus size={18} strokeWidth={2} />
                        </button>

                        <button onClick={fetchJobs} disabled={isFetching} className={`p-1.5 rounded-md hover:bg-black/5 text-gray-600 transition-colors ${isFetching ? 'animate-spin' : ''}`} title="Scout Jobs">
                            <Sidebar size={18} strokeWidth={2} className="rotate-180" />
                        </button>
                    </div>
                </div>

                {/* Content Body */}
                <div className="flex-1 overflow-y-auto custom-scrollbar p-8">
                    {currentView === ViewState.DASHBOARD && (
                        <div className="space-y-6 pb-20 max-w-5xl mx-auto">
                            {filteredJobs.length === 0 ? (
                                <div className="flex flex-col items-center justify-center h-[400px] text-gray-400">
                                    <div className="w-16 h-16 bg-white/50 rounded-full flex items-center justify-center mb-4 shadow-sm border border-white">
                                        <CheckCircle2 size={32} className="text-gray-300" />
                                    </div>
                                    <h3 className="text-lg font-semibold text-gray-600">All caught up</h3>
                                    <p className="text-sm opacity-70">No jobs match your current filters.</p>
                                    {(cityFilter !== 'All' || industryFilter) && (
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="mt-4 text-[#007AFF] text-sm font-medium hover:underline">Reset Filters</button>
                                    )}
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 gap-4">
                                    {filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {currentView === ViewState.KANBAN && (
                        <KanbanBoard 
                            jobs={allJobs} 
                            onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                            onToggleStatus={handleKanbanMove}
                            onDelete={handleDelete}
                            onOpenDetail={handleOpenDetail}
                            onOpenAddModal={() => setIsAddLinkOpen(true)}
                        />
                    )}

                    {currentView === ViewState.CV_EDITOR && (
                        <div className="h-full max-w-5xl mx-auto">
                            <CVEditor />
                        </div>
                    )}
                </div>
            </div>
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, FileText, TrendingUp, Trash2, Clock, Zap, Bookmark, Archive, MoreHorizontal } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="bg-white/70 backdrop-blur-xl p-4 rounded-2xl shadow-sm border border-white/50 hover:shadow-md transition-all group flex flex-col gap-3 relative cursor-pointer outline-none animate-float"
            tabIndex={0}
            role="button"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-2">
                <h4 className="font-semibold text-[13px] text-[#1d1d1f] leading-snug line-clamp-2">
                    {job.title}
                </h4>
                {analysis && (
                    <div 
                        className={`shrink-0 w-2 h-2 rounded-full shadow-sm ${analysis.isHighValue ? 'bg-[#34C759]' : 'bg-gray-300'}`} 
                        title={analysis.isHighValue ? "High Value" : "Standard"}
                    ></div>
                )}
            </div>

            <p className="text-[11px] font-medium text-gray-500 line-clamp-1">{job.company}</p>

            <div className="flex items-center gap-2 mt-1">
                <button 
                    onClick={(e) => { e.stopPropagation(); onOpenDetail(job); }} 
                    className="w-full py-1.5 text-[10px] font-semibold text-gray-600 hover:bg-black/5 rounded-lg transition-colors flex items-center justify-center gap-1.5"
                >
                    View Details
                </button>
            </div>
        </div>
      );
  }

  return (
    <div className={`glass-card rounded-2xl p-6 hover:bg-white/80 transition-all duration-300 relative group overflow-hidden animate-float ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}>

      {/* Top Right Actions - Hover Only */}
      <div className="absolute top-4 right-4 flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-200">
         <button 
            onClick={() => onDelete(job.id)} 
            className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all" 
            title={status === 'archived' ? "Delete Permanently" : "Archive"}
         >
            {status === 'archived' ? <Trash2 size={16} /> : <Archive size={16} />}
         </button>

         {status !== 'archived' && (
             <button 
                onClick={() => onToggleStatus(job.id, status)}
                className={`p-2 rounded-lg transition-all ${isSavedOrBetter 
                    ? 'text-[#007AFF] bg-blue-50/50' 
                    : 'text-gray-400 hover:bg-black/5'}`}
             >
                 <Bookmark size={16} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}
      </div>

      <div className="flex flex-col md:flex-row gap-6 items-start">
          {/* Score Circle - iOS Health Ring Style */}
          <div className="shrink-0 pt-1" aria-hidden="true">
             {analysis ? (
                 <div className="w-16 h-16 rounded-full bg-white/50 shadow-sm border border-white flex flex-col items-center justify-center relative overflow-hidden backdrop-blur-md">
                    {/* Ring simulation */}
                    <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 36 36">
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="#E5E5EA" strokeWidth="2.5" />
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke={analysis.score > 70 ? '#34C759' : '#007AFF'} strokeWidth="2.5" strokeDasharray={`${analysis.score}, 100`} strokeLinecap="round" />
                    </svg>
                    <span className="text-lg font-bold text-gray-900 z-10">{analysis.score}</span>
                 </div>
             ) : (
                 <div className="w-16 h-16 rounded-full bg-gray-100/50 flex items-center justify-center animate-pulse">
                     <span className="text-[9px] font-bold text-gray-400">SCAN</span>
                 </div>
             )}
          </div>

          <div className="flex-1 pr-10">
             <div 
                className="cursor-pointer group/title focus:outline-none" 
                onClick={() => onOpenDetail(job)}
             >
                <div className="flex items-center gap-2 mb-1">
                    <h3 className="text-xl font-semibold text-[#1d1d1f] tracking-tight group-hover/title:text-[#007AFF] transition-colors leading-tight">
                        {job.title}
                    </h3>
                    {job.isRelatedDiscovery && <span className="bg-yellow-100/80 text-yellow-700 text-[9px] font-bold px-1.5 py-0.5 rounded-md border border-yellow-200">NEW</span>}
                </div>

                <div className="flex flex-wrap items-center gap-3 text-xs font-medium text-gray-500 mb-3 opacity-80">
                    <span className="flex items-center gap-1">{job.company}</span>
                    <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                    <span className="flex items-center gap-1">{job.location}</span>
                    <span className="w-1 h-1 rounded-full bg-gray-300"></span>
                    <span>{job.postedDate}</span>
                </div>
             </div>

             {/* Tags - Pill Chips */}
             <div className="flex flex-wrap items-center gap-2 mt-2 mb-4">
                {job.seniorityScore && (
                     <span className="px-2.5 py-1 rounded-full text-[10px] font-semibold bg-gray-100/80 text-gray-600 border border-white/50 backdrop-blur-sm">{job.seniorityScore}</span>
                )}
                {analysis && analysis.isHighValue && (
                     <span className="px-2.5 py-1 rounded-full text-[10px] font-semibold bg-green-100/60 text-green-700 border border-green-200/50 flex items-center gap-1"><TrendingUp size={10} /> High Value</span>
                )}
                {analysis && analysis.isCommuteRisk && (
                     <span className="px-2.5 py-1 rounded-full text-[10px] font-semibold bg-orange-100/60 text-orange-700 border border-orange-200/50 flex items-center gap-1"><AlertTriangle size={10} /> Risk</span>
                )}
                 {analysis?.industry && (
                     <span className="px-2.5 py-1 rounded-full text-[10px] font-semibold bg-blue-100/60 text-blue-700 border border-blue-200/50">{analysis.industry}</span>
                )}
             </div>

             {/* Verdict */}
             {analysis && (
                 <div className="mb-4">
                    <p className="text-[13px] text-gray-600 leading-relaxed font-normal opacity-90">{analysis.verdict}</p>
                 </div>
             )}

             {/* Actions */}
             <div className="flex items-center gap-3 mt-4">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="px-4 py-1.5 rounded-full text-xs font-semibold bg-[#1d1d1f] text-white hover:bg-black/80 hover:shadow-lg transition-all flex items-center gap-1.5 shadow-sm"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={12} />
                 </a>
                 <button 
                    onClick={() => onOpenDetail(job)}
                    className="px-4 py-1.5 rounded-full text-xs font-semibold bg-white text-gray-700 border border-gray-200 hover:bg-gray-50 transition-all shadow-sm"
                 >
                     View Analysis
                 </button>
             </div>
          </div>
      </div>
    </div>
  );
};

