import React from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Job } from '../types';

interface StatsPanelProps {
  jobs: Job[];
  selectedIndustry: string | null;
  onSelectIndustry: (industry: string | null) => void;
}

// macOS System Colors
const COLORS = [
  '#007AFF', // Blue
  '#FF2D55', // Pink
  '#FFCC00', // Yellow
  '#34C759', // Green
  '#AF52DE', // Purple
  '#5856D6'  // Indigo
];

const StatsPanel: React.FC<StatsPanelProps> = ({ jobs, selectedIndustry, onSelectIndustry }) => {
  const getIndustry = (job: Job): string => {
    if (job.analysis?.industry && job.analysis.industry !== "Other") {
        return job.analysis.industry;
    }
    const text = (job.company + " " + job.title + " " + (job.summary || "")).toLowerCase();
    if (text.match(/bank|finance|wealth|fintech/)) return 'Fintech';
    if (text.match(/insurance|underwrit/)) return 'Insurance';
    if (text.match(/gov|public|council|nhs/)) return 'Public Sector';
    if (text.match(/agency|studio/)) return 'Agency';
    return 'Tech';
  };

  const industryCounts = jobs.reduce((acc, job) => {
    if ((job.status || 'new') !== 'new') return acc;
    const industry = getIndustry(job);
    acc[industry] = (acc[industry] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const data = Object.entries(industryCounts)
    .map(([name, value]) => ({ name, value: value as number }))
    .filter((item) => item.value > 0)
    .sort((a, b) => b.value - a.value);

  const totalJobs = data.reduce((sum, item) => sum + item.value, 0);

  if (totalJobs === 0) return null;

  return (
    <div className="rounded-xl mt-4">
      <div className="flex items-center justify-between mb-4 px-1">
        <h3 className="text-[11px] font-semibold text-gray-400 uppercase tracking-wide">Breakdown</h3>
        {selectedIndustry && (
            <button 
                onClick={() => onSelectIndustry(null)}
                className="text-[10px] font-bold text-[#007AFF] hover:bg-black/5 px-2 py-0.5 rounded transition-colors"
            >
                RESET
            </button>
        )}
      </div>

      <div className="h-[120px] relative mb-4 cursor-pointer group">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie 
                data={data} 
                cx="50%" 
                cy="50%" 
                innerRadius={38} 
                outerRadius={52} 
                paddingAngle={3} 
                dataKey="value" 
                stroke="none" 
                cornerRadius={4}
                onClick={(data) => {
                    const newSelection = selectedIndustry === data.name ? null : data.name;
                    onSelectIndustry(newSelection);
                }}
            >
              {data.map((entry, index) => (
                <Cell 
                    key={`cell-${index}`} 
                    fill={COLORS[index % COLORS.length]} 
                    opacity={selectedIndustry && selectedIndustry !== entry.name ? 0.2 : 1}
                    style={{ outline: 'none' }}
                />
              ))}
            </Pie>
            <Tooltip 
              contentStyle={{ borderRadius: '8px', border: 'none', padding: '6px', fontSize: '11px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
              itemStyle={{ color: '#1d1d1f' }}
            />
          </PieChart>
        </ResponsiveContainer>

        {/* Center Text */}
        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none group-hover:scale-105 transition-transform">
             <span className="text-xl font-bold text-[#1d1d1f]">{selectedIndustry ? data.find(d => d.name === selectedIndustry)?.value : totalJobs}</span>
        </div>
      </div>

      <div className="space-y-1">
        {data.slice(0, 4).map((entry, index) => {
          const isSelected = selectedIndustry === entry.name;
          return (
            <button
                key={entry.name} 
                onClick={() => onSelectIndustry(isSelected ? null : entry.name)}
                className={`w-full flex items-center justify-between text-[12px] cursor-pointer px-2 py-1.5 rounded-lg transition-colors ${isSelected ? 'bg-white shadow-sm font-medium text-black' : 'text-gray-500 hover:bg-black/5'}`}
            >
               <div className="flex items-center gap-2.5">
                 <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                 <span>{entry.name}</span>
               </div>
               <span>{entry.value}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default StatsPanel;

import React, { useState } from 'react';
import { X, Link, FileText, AlignLeft, Building2, Type } from 'lucide-react';

interface AddLinkModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (data: { url?: string; text?: string; title?: string; company?: string }) => void;
}

const AddLinkModal: React.FC<AddLinkModalProps> = ({ isOpen, onClose, onAdd }) => {
  const [mode, setMode] = useState<'link' | 'text'>('link');
  const [url, setUrl] = useState('');
  const [text, setText] = useState('');
  const [manualTitle, setManualTitle] = useState('');
  const [manualCompany, setManualCompany] = useState('');
  const [manualUrl, setManualUrl] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'link' && url.trim()) {
      onAdd({ url });
      setUrl('');
      onClose();
    } else if (mode === 'text' && text.trim()) {
      onAdd({ 
          text, 
          title: manualTitle || 'Manual Job Entry', 
          company: manualCompany || 'Unknown Company',
          url: manualUrl.trim() || 'Manual Entry' 
      });
      setText(''); setManualTitle(''); setManualCompany(''); setManualUrl('');
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm p-4 animate-in fade-in duration-200" role="dialog" aria-modal="true">
      <div className="bg-white/90 backdrop-blur-xl rounded-[20px] shadow-2xl w-full max-w-lg overflow-hidden border border-white/40 animate-float">

        {/* Header */}
        <div className="bg-transparent border-b border-black/5 px-6 py-4 flex items-center justify-between">
            <h2 className="text-sm font-semibold text-gray-800">New Opportunity</h2>
            <div className="flex bg-gray-200/50 rounded-lg p-0.5" role="tablist">
                <button onClick={() => setMode('link')} className={`px-4 py-1 rounded-[6px] text-xs font-semibold transition-all flex items-center gap-2 ${mode === 'link' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
                    <Link size={12} /> Link
                </button>
                <button onClick={() => setMode('text')} className={`px-4 py-1 rounded-[6px] text-xs font-semibold transition-all flex items-center gap-2 ${mode === 'text' ? 'bg-white text-black shadow-sm' : 'text-gray-500 hover:text-gray-800'}`}>
                    <FileText size={12} /> Text
                </button>
            </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6">
          {mode === 'link' ? (
              <div className="mb-6">
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-2">Job URL</label>
                <div className="relative">
                    <Link className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                    <input 
                        type="url" value={url} onChange={(e) => setUrl(e.target.value)}
                        placeholder="https://linkedin.com/jobs/..." 
                        className="w-full pl-10 pr-4 py-3 bg-white/50 border border-gray-200 rounded-xl focus:border-blue-500 focus:ring-2 focus:ring-blue-100 outline-none text-gray-800 transition-all text-sm"
                        autoFocus required
                    />
                </div>
              </div>
          ) : (
              <div className="space-y-4 mb-6">
                  <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-2">Title</label>
                        <input type="text" value={manualTitle} onChange={(e) => setManualTitle(e.target.value)} placeholder="Senior Designer" className="w-full px-3 py-2 bg-white/50 border border-gray-200 rounded-xl focus:border-blue-500 outline-none text-sm" />
                      </div>
                      <div>
                        <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-2">Company</label>
                        <input type="text" value={manualCompany} onChange={(e) => setManualCompany(e.target.value)} placeholder="Acme Inc." className="w-full px-3 py-2 bg-white/50 border border-gray-200 rounded-xl focus:border-blue-500 outline-none text-sm" />
                      </div>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase tracking-wide mb-2">Description</label>
                    <textarea value={text} onChange={(e) => setText(e.target.value)} placeholder="Paste job description..." className="w-full p-4 h-32 bg-white/50 border border-gray-200 rounded-xl focus:border-blue-500 outline-none text-sm resize-none" required />
                  </div>
              </div>
          )}

          <div className="flex justify-end gap-3 pt-4">
            <button type="button" onClick={onClose} className="px-5 py-2 text-xs font-bold text-gray-500 hover:text-gray-800 transition-colors">Cancel</button>
            <button type="submit" className="px-6 py-2 text-xs font-bold text-white bg-black rounded-lg hover:bg-gray-800 transition-colors shadow-lg shadow-black/20 flex items-center gap-2">
                {mode === 'link' ? 'Scout' : 'Add Job'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddLinkModal;

import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy, Plus } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, bgClass: string, accentColor: string }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={16} />, bgClass: 'bg-gray-50/30', accentColor: 'text-blue-600' },
      { id: 'applied', title: 'Applied', icon: <Send size={16} />, bgClass: 'bg-gray-50/30', accentColor: 'text-blue-600' },
      { id: 'interview', title: 'Interview', icon: <Users size={16} />, bgClass: 'bg-yellow-50/30', accentColor: 'text-yellow-600' },
      { id: 'offer', title: 'Offer', icon: <Trophy size={16} />, bgClass: 'bg-green-50/30', accentColor: 'text-green-600' },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 flex gap-6 overflow-x-auto pb-6 items-stretch custom-scrollbar snap-x snap-mandatory">
        {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className={`flex flex-col h-full min-w-[320px] rounded-2xl p-3 transition-colors ${col.bgClass} border border-white/20 backdrop-blur-sm snap-center`}
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className={`flex items-center justify-between mb-4 px-2 pt-2 ${col.accentColor}`}>
                        <h3 className="font-semibold text-sm flex items-center gap-2 opacity-90">
                            {col.icon} {col.title}
                        </h3>
                        <span className="text-[10px] bg-white/50 border border-white/20 px-2 py-0.5 rounded-full font-bold shadow-sm text-gray-500">{colJobs.length}</span>
                    </div>

                    <div className="flex-1 space-y-3 overflow-y-auto pr-1 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="text-center py-12 border-2 border-dashed border-gray-200/50 rounded-xl">
                                <p className="text-xs font-medium text-gray-400">Empty</p>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className="cursor-grab active:cursor-grabbing transform transition-transform hover:scale-[1.02]"
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
        })}
      </div>
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useEffect } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Columns, FileText, CheckCircle2, Plus, Search, Sidebar, Settings, ChevronLeft, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        // Auto-archive logic
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // derived state
  const locationCounts = allJobs.reduce((acc, job) => {
    const locRaw = job.location.toLowerCase();
    let key = 'Other';
    if (locRaw.includes('edinburgh')) key = 'Edinburgh';
    else if (locRaw.includes('glasgow')) key = 'Glasgow';
    else if (locRaw.includes('remote')) key = 'Remote';
    else if (locRaw.includes('london')) key = 'London';
    else if (locRaw.includes('manchester')) key = 'Manchester';
    if ((job.status || 'new') === 'new') {
        acc[key] = (acc[key] || 0) + 1;
        acc['All'] = (acc['All'] || 0) + 1;
    }
    return acc;
  }, { 'All': 0 } as Record<string, number>);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const filteredJobs = allJobs.filter(j => {
    const status = j.status || 'new';
    if (activeTab === 'new') return status === 'new';
    if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
    if (activeTab === 'archived') return status === 'archived';
    return true;
  }).filter(j => {
    const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
    if (!locMatch) return false;

    // Industry Filter
    if (industryFilter) {
        const ind = j.analysis?.industry || 'Tech';
        if (ind !== industryFilter) {
             const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
             let calculatedIndustry = 'Tech';
             if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
             else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
             else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
             else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

             if (calculatedIndustry !== industryFilter) return false;
        }
    }
    return true;
  }).sort((a, b) => {
      if (sortBy === 'score') {
          return (b.analysis?.score || 0) - (a.analysis?.score || 0);
      }
      return (b.scoutedAt || 0) - (a.scoutedAt || 0);
  });

  return (
    <div className="flex h-screen w-screen p-4 sm:p-8 overflow-hidden">
        {/* MAIN WINDOW CONTAINER */}
        <div className="flex w-full h-full rounded-[20px] shadow-2xl overflow-hidden border border-white/20 bg-transparent backdrop-blur-3xl relative">

            {/* --- SIDEBAR (Finder Style) --- */}
            <div className="w-[260px] flex-none glass-sidebar flex flex-col justify-between z-10">
                <div>
                    {/* Traffic Lights */}
                    <div className="h-12 flex items-center px-4 gap-2 group">
                        <div className="w-3 h-3 rounded-full bg-[#FF5F57] shadow-sm border border-[#E0443E]/50"></div>
                        <div className="w-3 h-3 rounded-full bg-[#FEBC2E] shadow-sm border border-[#D89E24]/50"></div>
                        <div className="w-3 h-3 rounded-full bg-[#28C840] shadow-sm border border-[#1AAB29]/50"></div>
                    </div>

                    <div className="px-3 py-2 space-y-6">
                        {/* Navigation */}
                        <div className="space-y-1">
                            {[
                                { id: ViewState.DASHBOARD, label: 'Discover', icon: LayoutGrid },
                                { id: ViewState.KANBAN, label: 'Pipeline', icon: Columns },
                                { id: ViewState.CV_EDITOR, label: 'Resume', icon: FileText }
                            ].map(item => (
                                <button 
                                    key={item.id}
                                    onClick={() => setCurrentView(item.id)}
                                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-[13px] font-medium transition-all duration-200 ${currentView === item.id ? 'bg-black/10 text-black' : 'text-gray-600 hover:bg-black/5'}`}
                                >
                                    <item.icon size={16} strokeWidth={2} />
                                    {item.label}
                                </button>
                            ))}
                        </div>

                        {/* Smart Filters Group */}
                        {currentView === ViewState.DASHBOARD && (
                            <div className="space-y-1">
                                <p className="px-3 text-[11px] font-semibold text-gray-400 uppercase tracking-wide mb-2 mt-4">Locations</p>
                                {filterOptions.map(city => {
                                    const count = locationCounts[city] || 0;
                                    if (count === 0 && city !== 'All') return null;
                                    return (
                                        <button 
                                            key={city} 
                                            onClick={() => setCityFilter(city)} 
                                            className={`w-full flex items-center justify-between px-3 py-1.5 rounded-lg text-[13px] transition-all ${cityFilter === city ? 'bg-[#007AFF] text-white shadow-sm' : 'text-gray-600 hover:bg-black/5'}`}
                                        >
                                            <span className="font-medium">{city}</span>
                                            {count > 0 && <span className={`px-1.5 py-0.5 rounded text-[10px] ${cityFilter === city ? 'bg-white/20' : 'bg-black/5 text-gray-500'}`}>{count}</span>}
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        {currentView === ViewState.DASHBOARD && (
                            <div className="mt-4 pt-4 border-t border-black/5 px-2">
                                <StatsPanel 
                                    jobs={allJobs} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        )}
                    </div>
                </div>

                {/* User Profile Footer */}
                <div className="p-4 border-t border-black/5 flex items-center gap-3">
                    <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-blue-400 to-indigo-500 shadow-inner"></div>
                    <div>
                        <p className="text-xs font-bold text-gray-800">Vyom P.</p>
                        <p className="text-[10px] text-gray-500">Pro Plan</p>
                    </div>
                    <Settings size={14} className="ml-auto text-gray-400 hover:text-gray-600 cursor-pointer" />
                </div>
            </div>

            {/* --- MAIN CONTENT CANVAS --- */}
            <div className="flex-1 glass-content flex flex-col relative">

                {/* Top Toolbar */}
                <div className="h-12 border-b border-black/5 flex items-center justify-between px-6 shrink-0 bg-white/40 backdrop-blur-md">
                    <div className="flex items-center gap-4">
                        <div className="flex items-center text-gray-400">
                             <button className="hover:text-gray-600 transition-colors"><ChevronLeft size={20} /></button>
                             <button className="hover:text-gray-600 transition-colors opacity-50"><ChevronRight size={20} /></button>
                        </div>
                        <h1 className="text-sm font-bold text-gray-700 opacity-90">
                            {currentView === ViewState.DASHBOARD ? 'Market Overview' : currentView === ViewState.KANBAN ? 'Application Pipeline' : 'Resume Editor'}
                        </h1>
                    </div>

                    <div className="flex items-center gap-3">
                         {/* Search Bar */}
                         <div className="relative group">
                             <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 group-focus-within:text-[#007AFF]" />
                             <input 
                                type="text" 
                                placeholder="Search..." 
                                className="pl-9 pr-3 py-1.5 bg-white/50 border border-black/5 rounded-lg text-xs font-medium focus:bg-white focus:shadow-sm focus:border-black/10 focus:outline-none transition-all w-40 focus:w-56 placeholder:text-gray-400"
                             />
                         </div>

                         {currentView === ViewState.DASHBOARD && (
                            <div className="flex bg-black/5 rounded-lg p-0.5">
                                {['new', 'saved', 'archived'].map((tab) => (
                                    <button 
                                        key={tab}
                                        onClick={() => setActiveTab(tab as any)}
                                        className={`px-3 py-1 rounded-[6px] text-[11px] font-medium capitalize transition-all ${activeTab === tab ? 'bg-white shadow-sm text-black' : 'text-gray-500 hover:text-gray-800'}`}
                                    >
                                        {tab}
                                    </button>
                                ))}
                            </div>
                        )}

                        <div className="h-4 w-px bg-black/10 mx-1"></div>

                        {analyzingCount > 0 && (
                            <div className="flex items-center gap-2 px-3 py-1 bg-white/50 border border-black/5 rounded-md shadow-sm">
                                <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                                <span className="text-[10px] font-bold text-gray-600">Analyzing...</span>
                            </div>
                        )}

                        <button onClick={() => setIsAddLinkOpen(true)} className="p-1.5 rounded-md hover:bg-black/5 text-gray-600 transition-colors" title="Add Job">
                            <Plus size={18} strokeWidth={2} />
                        </button>

                        <button onClick={fetchJobs} disabled={isFetching} className={`p-1.5 rounded-md hover:bg-black/5 text-gray-600 transition-colors ${isFetching ? 'animate-spin' : ''}`} title="Scout Jobs">
                            <Sidebar size={18} strokeWidth={2} className="rotate-180" />
                        </button>
                    </div>
                </div>

                {/* Content Body */}
                <div className="flex-1 overflow-y-auto custom-scrollbar p-8">
                    {currentView === ViewState.DASHBOARD && (
                        <div className="space-y-6 pb-20 max-w-5xl mx-auto">
                            {filteredJobs.length === 0 ? (
                                <div className="flex flex-col items-center justify-center h-[400px] text-gray-400">
                                    <div className="w-16 h-16 bg-white/50 rounded-full flex items-center justify-center mb-4 shadow-sm border border-white">
                                        <CheckCircle2 size={32} className="text-gray-300" />
                                    </div>
                                    <h3 className="text-lg font-semibold text-gray-600">All caught up</h3>
                                    <p className="text-sm opacity-70">No jobs match your current filters.</p>
                                    {(cityFilter !== 'All' || industryFilter) && (
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="mt-4 text-[#007AFF] text-sm font-medium hover:underline">Reset Filters</button>
                                    )}
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 gap-4">
                                    {filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {currentView === ViewState.KANBAN && (
                        <KanbanBoard 
                            jobs={allJobs} 
                            onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                            onToggleStatus={handleKanbanMove}
                            onDelete={handleDelete}
                            onOpenDetail={handleOpenDetail}
                            onOpenAddModal={() => setIsAddLinkOpen(true)}
                        />
                    )}

                    {currentView === ViewState.CV_EDITOR && (
                        <div className="h-full max-w-5xl mx-auto">
                            <CVEditor />
                        </div>
                    )}
                </div>
            </div>
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

