        {/* Title Bar */}
        <div className="h-12 bg-white/40 border-b border-black/5 flex items-center justify-between px-4 shrink-0 drag-handle backdrop-blur-md">
           <div className="flex gap-2 group">
                <button onClick={onClose} className="w-3 h-3 rounded-full bg-[#FF5F57] border border-[#E0443E] shadow-sm hover:opacity-80 transition-opacity"></button>
                <div className="w-3 h-3 rounded-full bg-[#FEBC2E] border border-[#D89E24] shadow-sm"></div>
                <div className="w-3 h-3 rounded-full bg-[#28C840] border border-[#1AAB29] shadow-sm"></div>
           </div>
