           </div>
           <div className="w-10"></div> 
        </div>

        {/* Content Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-8">
            <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-10">

                {/* Left Panel: Content */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Header */}
                    <div className="mb-8">
                        {isEditingTitle ? (
                            <input 
                                type="text" 
                                value={editedTitle}
                                onChange={(e) => setEditedTitle(e.target.value)}
                                onBlur={handleSaveTitle}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                                className="text-3xl font-bold text-gray-900 w-full bg-transparent outline-none border-b border-blue-500"
                                autoFocus
                            />
                        ) : (
                            <h2 onClick={() => setIsEditingTitle(true)} className="text-3xl font-bold text-gray-900 leading-tight mb-2 tracking-tight hover:opacity-70 cursor-pointer">{job.title}</h2>
