import React, { useState, useEffect, useMemo } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Columns, FileText, Plus, Search, Sidebar, Settings, ChevronLeft, ChevronRight, SlidersHorizontal, Sparkles } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        // Auto-archive logic
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC (Revised) ---

  // 1. Get jobs for current tab FIRST
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  // 2. Calculate counts based on current tab jobs
  const locationCounts = useMemo(() => {
    return jobsInCurrentTab.reduce((acc, job) => {
        const locRaw = job.location.toLowerCase();
        let key = 'Other';
        if (locRaw.includes('edinburgh')) key = 'Edinburgh';
        else if (locRaw.includes('glasgow')) key = 'Glasgow';
        else if (locRaw.includes('remote')) key = 'Remote';
        else if (locRaw.includes('london')) key = 'London';
        else if (locRaw.includes('manchester')) key = 'Manchester';

        acc[key] = (acc[key] || 0) + 1;
        acc['All'] = (acc['All'] || 0) + 1;
        return acc;
    }, { 'All': 0 } as Record<string, number>);
  }, [jobsInCurrentTab]);

  // 3. Apply Filters to the tab jobs
  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        // Location Filter
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        // Industry Filter
        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="flex h-screen w-screen p-4 sm:p-8 overflow-hidden bg-[url('https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?q=80&w=2574&auto=format&fit=crop')] bg-cover bg-center">
        {/* MAIN WINDOW CONTAINER */}
        <div className="flex w-full h-full rounded-[24px] shadow-2xl overflow-hidden border border-white/40 bg-white/5 backdrop-blur-3xl relative">

            {/* --- SIDEBAR --- */}
            <div className="w-[280px] flex-none glass-sidebar flex flex-col justify-between z-10 pt-5">
                <div>
                    {/* Traffic Lights */}
                    <div className="h-8 flex items-center px-6 gap-2 group mb-6">
                        <div className="w-3 h-3 rounded-full bg-[#FF5F57] shadow-sm border border-[#000000]/10"></div>
                        <div className="w-3 h-3 rounded-full bg-[#FEBC2E] shadow-sm border border-[#000000]/10"></div>
                        <div className="w-3 h-3 rounded-full bg-[#28C840] shadow-sm border border-[#000000]/10"></div>
                    </div>

                    <div className="px-4 space-y-8">
                        {/* Navigation */}
                        <div className="space-y-1.5">
                            {[
                                { id: ViewState.DASHBOARD, label: 'Discover', icon: LayoutGrid },
                                { id: ViewState.KANBAN, label: 'Pipeline', icon: Columns },
                                { id: ViewState.CV_EDITOR, label: 'Resume', icon: FileText }
                            ].map(item => (
                                <button 
                                    key={item.id}
                                    onClick={() => setCurrentView(item.id)}
                                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-[13px] font-medium transition-all duration-200 focus-ring ${currentView === item.id ? 'bg-black/10 text-[#1d1d1f]' : 'text-[#48484a] hover:bg-black/5'}`}
                                >
                                    <item.icon size={18} strokeWidth={2} className={currentView === item.id ? 'text-[#007AFF]' : 'text-gray-500'} />
                                    {item.label}
                                </button>
                            ))}
                        </div>

                        {/* Smart Filters Group */}
                        {currentView === ViewState.DASHBOARD && (
                            <div className="space-y-1">
                                <p className="px-3 text-[11px] font-bold text-[#8e8e93] uppercase tracking-wide mb-3 flex items-center gap-2">
                                    Filters
                                </p>
                                {filterOptions.map(city => {
                                    const count = locationCounts[city] || 0;
                                    if (count === 0 && city !== 'All') return null;
                                    const isSelected = cityFilter === city;
                                    return (
                                        <button 
                                            key={city} 
                                            onClick={() => setCityFilter(city)} 
                                            className={`w-full flex items-center justify-between px-3 py-1.5 rounded-lg text-[13px] transition-all focus-ring ${isSelected ? 'bg-[#007AFF] text-white shadow-sm' : 'text-[#48484a] hover:bg-black/5'}`}
                                        >
                                            <span className="font-medium">{city}</span>
                                            {count > 0 && <span className={`px-1.5 py-0.5 rounded text-[10px] font-semibold ${isSelected ? 'bg-white/25' : 'bg-black/5 text-gray-500'}`}>{count}</span>}
                                        </button>
                                    );
                                })}
                            </div>
                        )}

                        {currentView === ViewState.DASHBOARD && (
                            <div className="mt-4 pt-4 border-t border-black/5">
                                <StatsPanel 
                                    jobs={jobsInCurrentTab} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        )}
                    </div>
                </div>

                {/* User Profile Footer */}
                <div className="p-4 border-t border-black/5 flex items-center gap-3 bg-white/30 backdrop-blur-sm">
                    <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-blue-500 to-indigo-600 shadow-sm border border-white/20"></div>
                    <div>
                        <p className="text-[13px] font-semibold text-[#1d1d1f]">Vyom P.</p>
                        <p className="text-[11px] text-[#6e6e73]">Pro Account</p>
                    </div>
                    <Settings size={16} className="ml-auto text-[#8e8e93] hover:text-[#1d1d1f] cursor-pointer transition-colors" />
                </div>
            </div>

            {/* --- MAIN CONTENT CANVAS --- */}
            <div className="flex-1 glass-content flex flex-col relative z-0">

                {/* Modern Unified Toolbar */}
                <div className="h-16 border-b border-black/5 flex items-center justify-between px-8 shrink-0 bg-white/40 backdrop-blur-md sticky top-0 z-20">
                    <div className="flex items-center gap-6">
                        <div className="flex items-center text-[#6e6e73] bg-black/5 rounded-lg p-0.5 shadow-sm border border-white/20">
                             <button className="p-1.5 hover:bg-white rounded-md transition-all shadow-none hover:shadow-sm"><ChevronLeft size={16} /></button>
                             <button className="p-1.5 hover:bg-white rounded-md transition-all shadow-none hover:shadow-sm opacity-50"><ChevronRight size={16} /></button>
                        </div>
                        <h1 className="text-sm font-bold text-[#1d1d1f]">
                            {currentView === ViewState.DASHBOARD ? 'Market Overview' : currentView === ViewState.KANBAN ? 'Application Pipeline' : 'Resume Editor'}
                        </h1>
                    </div>

                    <div className="flex items-center gap-4">
                         {/* Search Bar */}
                         <div className="relative group">
                             <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#8e8e93] group-focus-within:text-[#007AFF] transition-colors" />
                             <input 
                                type="text" 
                                placeholder="Search" 
                                className="pl-9 pr-3 py-1.5 bg-black/5 border border-transparent rounded-lg text-[13px] font-medium focus:bg-white focus:shadow-sm focus:border-black/10 focus:outline-none transition-all w-48 placeholder:text-[#8e8e93] text-[#1d1d1f]"
                             />
                         </div>

                        <div className="h-5 w-px bg-black/10"></div>

                        {analyzingCount > 0 && (
                            <div className="flex items-center gap-2 px-3 py-1 bg-white/60 border border-black/5 rounded-full shadow-sm">
                                <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                                <span className="text-[11px] font-bold text-[#1d1d1f]">Analyzing...</span>
                            </div>
                        )}

                        <button onClick={() => setIsAddLinkOpen(true)} className="p-2 rounded-lg hover:bg-black/5 text-[#48484a] transition-colors" title="Add Job">
                            <Plus size={20} strokeWidth={1.5} />
                        </button>

                        <button onClick={fetchJobs} disabled={isFetching} className={`p-2 rounded-lg hover:bg-black/5 text-[#48484a] transition-colors ${isFetching ? 'animate-spin' : ''}`} title="Scout Jobs">
                            <Sidebar size={20} strokeWidth={1.5} className="rotate-180" />
                        </button>
                    </div>
                </div>

                {/* Content Body */}
                <div className="flex-1 overflow-y-auto custom-scrollbar">

                    {currentView === ViewState.DASHBOARD && (
                        <div className="pb-24">

                            {/* HERO SECTION */}
                            <div className="px-8 pt-8 pb-8">
                                <div className="glass-panel p-8 rounded-3xl border border-white/50 shadow-sm relative overflow-hidden group">
                                    <div className="absolute top-0 right-0 w-64 h-64 bg-gradient-to-br from-blue-400/20 to-purple-400/20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none"></div>

                                    <div className="relative z-10 flex justify-between items-end">
                                        <div>
                                            <h2 className="text-3xl font-bold text-[#1d1d1f] tracking-tight mb-2">
                                                Welcome back, Vyom.
                                            </h2>
                                            <p className="text-[#48484a] text-lg max-w-xl leading-relaxed">
                                                You have <span className="font-semibold text-[#007AFF]">{allJobs.filter(j => j.status === 'saved').length} saved opportunities</span> waiting for review. The market is active today.
                                            </p>
                                        </div>

                                        <div className="flex gap-3">
                                            {/* Tab Switcher in Hero */}
                                            <div className="flex bg-[#E5E5EA]/80 p-1 rounded-xl backdrop-blur-md">
                                                {['new', 'saved', 'archived'].map((tab) => {
                                                    const isActive = activeTab === tab;
                                                    return (
                                                        <button 
                                                            key={tab}
                                                            onClick={() => setActiveTab(tab as any)} 
                                                            className={`px-6 py-2 rounded-lg text-[13px] font-semibold capitalize transition-all ${isActive ? 'bg-white text-black shadow-sm' : 'text-[#6e6e73] hover:text-[#1d1d1f]'}`}
                                                        >
                                                            {tab}
                                                        </button>
                                                    );
                                                })}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="px-8 max-w-6xl mx-auto">
                                <div className="flex items-center justify-between mb-6">
                                    <h3 className="text-lg font-bold text-[#1d1d1f] flex items-center gap-2">
                                        {activeTab === 'new' ? 'Fresh Discoveries' : activeTab === 'saved' ? 'Shortlist' : 'Archive'}
                                        <span className="text-xs bg-black/5 px-2 py-0.5 rounded-full text-[#6e6e73]">{filteredJobs.length}</span>
                                    </h3>

                                    <button 
                                        onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')}
                                        className="text-xs font-semibold text-[#007AFF] flex items-center gap-1 hover:bg-blue-50 px-3 py-1 rounded-lg transition-colors"
                                    >
                                        Sort by {sortBy === 'date' ? 'Date' : 'Score'} <SlidersHorizontal size={12} />
                                    </button>
                                </div>

                                {filteredJobs.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-[300px] text-[#8e8e93]">
                                        <div className="w-16 h-16 bg-white/50 rounded-full flex items-center justify-center mb-4 shadow-sm border border-white/50">
                                            <Sparkles size={24} className="text-[#8e8e93]" />
                                        </div>
                                        <h3 className="text-base font-semibold text-[#48484a]">All caught up</h3>
                                        <p className="text-sm opacity-80">No jobs match your current filters in this view.</p>
                                        {(cityFilter !== 'All' || industryFilter) && (
                                            <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="mt-4 text-[#007AFF] text-sm font-medium hover:underline">Reset Filters</button>
                                        )}
                                    </div>
                                ) : (
                                    <div className="flex flex-col gap-6">
                                        {filteredJobs.map(job => (
                                            <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    )}

                    {currentView === ViewState.KANBAN && (
                        <div className="px-8 py-8 h-full">
                            <KanbanBoard 
                                jobs={allJobs} 
                                onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                                onToggleStatus={handleKanbanMove}
                                onDelete={handleDelete}
                                onOpenDetail={handleOpenDetail}
                                onOpenAddModal={() => setIsAddLinkOpen(true)}
                            />
                        </div>
                    )}

                    {currentView === ViewState.CV_EDITOR && (
                        <div className="h-full px-8 py-8 max-w-5xl mx-auto">
                            <CVEditor />
                        </div>
                    )}
                </div>
            </div>
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, FileText, TrendingUp, Trash2, Clock, Zap, Bookmark, Archive, MoreHorizontal } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="bg-white/80 backdrop-blur-xl p-5 rounded-[20px] shadow-sm border border-white/60 hover:shadow-md transition-all group flex flex-col gap-3 relative cursor-pointer outline-none animate-float hover:-translate-y-1 duration-300"
            tabIndex={0}
            role="button"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-3">
                <h4 className="font-bold text-[14px] text-[#1d1d1f] leading-snug line-clamp-2">
                    {job.title}
                </h4>
                {analysis && (
                    <div 
                        className={`shrink-0 w-2.5 h-2.5 rounded-full shadow-sm border border-white/50 ${analysis.isHighValue ? 'bg-[#34C759]' : 'bg-gray-300'}`} 
                        title={analysis.isHighValue ? "High Value" : "Standard"}
                    ></div>
                )}
            </div>

            <p className="text-[12px] font-semibold text-[#6e6e73] line-clamp-1">{job.company}</p>

            <div className="flex items-center gap-2 mt-2">
                <button 
                    onClick={(e) => { e.stopPropagation(); onOpenDetail(job); }} 
                    className="w-full py-2 text-[11px] font-bold text-[#48484a] bg-black/5 hover:bg-black/10 rounded-lg transition-colors flex items-center justify-center gap-1.5"
                >
                    Details
                </button>
            </div>
        </div>
      );
  }

  return (
    <div className={`glass-card rounded-[24px] p-7 hover:bg-white/90 transition-all duration-300 relative group overflow-hidden animate-float ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}>

      {/* Top Right Actions - Hover Only */}
      <div className="absolute top-5 right-5 flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-200">
         <button 
            onClick={() => onDelete(job.id)} 
            className="p-2.5 text-[#8e8e93] hover:text-[#FF3B30] hover:bg-red-50 rounded-xl transition-all" 
            title={status === 'archived' ? "Delete Permanently" : "Archive"}
         >
            {status === 'archived' ? <Trash2 size={18} /> : <Archive size={18} />}
         </button>

         {status !== 'archived' && (
             <button 
                onClick={() => onToggleStatus(job.id, status)}
                className={`p-2.5 rounded-xl transition-all ${isSavedOrBetter 
                    ? 'text-[#007AFF] bg-blue-50/50' 
                    : 'text-[#8e8e93] hover:bg-black/5'}`}
             >
                 <Bookmark size={18} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}
      </div>

      <div className="flex flex-col md:flex-row gap-8 items-start">
          {/* Score Circle - iOS Health Ring Style */}
          <div className="shrink-0 pt-1" aria-hidden="true">
             {analysis ? (
                 <div className="w-[72px] h-[72px] rounded-full bg-white/60 shadow-sm border border-white flex flex-col items-center justify-center relative overflow-hidden backdrop-blur-md">
                    {/* Ring simulation */}
                    <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 36 36">
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="#E5E5EA" strokeWidth="2.5" />
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke={analysis.score > 70 ? '#34C759' : '#007AFF'} strokeWidth="2.5" strokeDasharray={`${analysis.score}, 100`} strokeLinecap="round" />
                    </svg>
                    <span className="text-xl font-bold text-[#1d1d1f] z-10">{analysis.score}</span>
                 </div>
             ) : (
                 <div className="w-[72px] h-[72px] rounded-full bg-gray-100/50 flex items-center justify-center animate-pulse border border-black/5">
                     <span className="text-[10px] font-bold text-[#8e8e93]">SCAN</span>
                 </div>
             )}
          </div>

          <div className="flex-1 pr-12">
             <div 
                className="cursor-pointer group/title focus:outline-none" 
                onClick={() => onOpenDetail(job)}
             >
                <div className="flex items-center gap-3 mb-2">
                    <h3 className="text-2xl font-bold text-[#1d1d1f] tracking-tight group-hover/title:text-[#007AFF] transition-colors leading-tight">
                        {job.title}
                    </h3>
                    {job.isRelatedDiscovery && <span className="bg-[#FFD60A]/20 text-[#9A7D0A] text-[10px] font-bold px-2 py-0.5 rounded-md border border-[#FFD60A]/30">NEW</span>}
                </div>

                <div className="flex flex-wrap items-center gap-3 text-[13px] font-medium text-[#6e6e73] mb-4">
                    <span className="flex items-center gap-1 text-[#1d1d1f] font-semibold">{job.company}</span>
                    <span className="w-1 h-1 rounded-full bg-[#aeaeb2]"></span>
                    <span className="flex items-center gap-1">{job.location}</span>
                    <span className="w-1 h-1 rounded-full bg-[#aeaeb2]"></span>
                    <span>{job.postedDate}</span>
                </div>
             </div>

             {/* Tags - Pill Chips */}
             <div className="flex flex-wrap items-center gap-2.5 mt-2 mb-5">
                {job.seniorityScore && (
                     <span className="px-3 py-1.5 rounded-full text-[11px] font-semibold bg-[#F2F2F7] text-[#48484a] border border-black/5">{job.seniorityScore}</span>
                )}
                {analysis && analysis.isHighValue && (
                     <span className="px-3 py-1.5 rounded-full text-[11px] font-semibold bg-[#E6F4EA] text-[#137333] border border-[#34C759]/20 flex items-center gap-1.5"><TrendingUp size={12} /> High Value</span>
                )}
                {analysis && analysis.isCommuteRisk && (
                     <span className="px-3 py-1.5 rounded-full text-[11px] font-semibold bg-[#FFF4F2] text-[#FF3B30] border border-[#FF3B30]/20 flex items-center gap-1.5"><AlertTriangle size={12} /> Commute Risk</span>
                )}
                 {analysis?.industry && (
                     <span className="px-3 py-1.5 rounded-full text-[11px] font-semibold bg-[#E8F0FE] text-[#007AFF] border border-[#007AFF]/20">{analysis.industry}</span>
                )}
