             {/* Verdict */}
             {analysis && (
                 <div className="mb-6">
                    <p className="text-[14px] text-[#3a3a3c] leading-relaxed font-normal">{analysis.verdict}</p>
                 </div>
             )}

             {/* Actions */}
             <div className="flex items-center gap-4 mt-2">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="px-5 py-2 rounded-full text-xs font-bold bg-[#1d1d1f] text-white hover:bg-black hover:shadow-lg transition-all flex items-center gap-2 shadow-md hover:-translate-y-0.5"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={12} />
