import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Settings, Command, Sparkles, SlidersHorizontal, ArrowDownUp } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const locationCounts = useMemo(() => {
    return jobsInCurrentTab.reduce((acc, job) => {
        const locRaw = job.location.toLowerCase();
        let key = 'Other';
        if (locRaw.includes('edinburgh')) key = 'Edinburgh';
        else if (locRaw.includes('glasgow')) key = 'Glasgow';
        else if (locRaw.includes('remote')) key = 'Remote';
        else if (locRaw.includes('london')) key = 'London';
        else if (locRaw.includes('manchester')) key = 'Manchester';

        acc[key] = (acc[key] || 0) + 1;
        acc['All'] = (acc['All'] || 0) + 1;
        return acc;
    }, { 'All': 0 } as Record<string, number>);
  }, [jobsInCurrentTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="flex h-screen w-screen p-3 sm:p-5 overflow-hidden">

        {/* MAIN WINDOW FRAME */}
        <div className="flex w-full h-full rounded-[40px] shadow-2xl overflow-hidden border border-white/50 bg-white/5 backdrop-blur-3xl relative mac-window">

            {/* --- SIDEBAR PANE --- */}
            <div className="w-[260px] flex-none mac-sidebar flex flex-col justify-between z-10 pt-6 pb-6">
                <div>
                    {/* Window Controls */}
                    <div className="h-6 flex items-center px-6 gap-2 mb-8 group">
                        <div className="w-3 h-3 rounded-full bg-[#FF5F57] shadow-sm border border-black/5"></div>
                        <div className="w-3 h-3 rounded-full bg-[#FEBC2E] shadow-sm border border-black/5"></div>
                        <div className="w-3 h-3 rounded-full bg-[#28C840] shadow-sm border border-black/5"></div>
                    </div>

                    {/* Logo Area */}
                    <div className="px-6 mb-8 flex items-center gap-2 opacity-80">
                         <Command size={20} className="text-[#1D1D1F]" strokeWidth={2.5} />
                         <span className="font-bold text-base tracking-tight text-[#1D1D1F]">JobOS</span>
                    </div>

                    {/* Context Filters - Only show on Dashboard */}
                    {currentView === ViewState.DASHBOARD && (
                        <div className="px-4 space-y-6">

                            {/* Location Filter */}
                            <div>
                                <h4 className="px-2 text-[11px] font-bold text-[#86868B] uppercase tracking-wide mb-2">Location</h4>
                                <div className="space-y-0.5">
                                    {filterOptions.map(city => {
                                        const count = locationCounts[city] || 0;
                                        if (count === 0 && city !== 'All') return null;
                                        const isSelected = cityFilter === city;
                                        return (
                                            <button 
                                                key={city} 
                                                onClick={() => setCityFilter(city)} 
                                                className={`w-full flex items-center justify-between px-3 py-1.5 rounded-lg text-[13px] transition-all duration-200 ${isSelected ? 'bg-white shadow-sm font-semibold text-[#007AFF]' : 'text-[#1D1D1F] hover:bg-black/5'}`}
                                            >
                                                <span>{city}</span>
                                                {count > 0 && <span className={`text-[10px] ${isSelected ? 'text-[#007AFF] opacity-100' : 'text-[#86868B] opacity-70'}`}>{count}</span>}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* Chart Widget */}
                            <div className="pt-2">
                                <StatsPanel 
                                    jobs={jobsInCurrentTab} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        </div>
                    )}
                </div>

                {/* Profile */}
                <div className="px-6">
                    <div className="flex items-center gap-3 p-2 rounded-xl hover:bg-black/5 cursor-pointer transition-colors group">
                        <div className="w-8 h-8 rounded-full bg-gradient-to-b from-[#007AFF] to-[#0055B3] shadow-sm flex items-center justify-center text-white text-xs font-bold">VP</div>
                        <div className="flex-1">
                            <p className="text-[12px] font-semibold text-[#1D1D1F]">Vyom P.</p>
                            <p className="text-[10px] text-[#86868B]">Pro Plan</p>
                        </div>
                        <Settings size={14} className="text-[#86868B] group-hover:text-[#1D1D1F] transition-colors" />
                    </div>
                </div>
            </div>

            {/* --- MAIN CONTENT AREA --- */}
            <div className="flex-1 bg-white/50 m-2 rounded-[32px] flex flex-col relative overflow-hidden border-0 shadow-none z-0">

                {/* Top Action Bar (Transparent) */}
                <div className="h-20 flex items-center justify-between px-8 shrink-0">
                    <div className="flex items-center gap-2">
                         {/* Dynamic Title based on View */}
                         <h1 className="text-2xl font-bold text-[#1D1D1F] tracking-tight">
                            {currentView === ViewState.DASHBOARD ? 'Discover' : currentView === ViewState.KANBAN ? 'Pipeline' : 'Resume'}
                         </h1>
                         {analyzingCount > 0 && (
                            <span className="flex items-center gap-1.5 px-2.5 py-1 bg-white rounded-full border border-black/5 shadow-sm text-[10px] font-bold text-[#86868B] ml-2">
                                <Sparkles size={12} className="text-[#007AFF] animate-spin-slow fill-current" /> Analyzing...
                            </span>
                         )}
                    </div>

                    <div className="flex items-center gap-3">
                         <div className="relative group">
                             <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#86868B] group-focus-within:text-[#007AFF] transition-colors" />
                             <input 
                                type="text" 
                                placeholder="Search" 
                                className="pl-9 pr-4 py-2 bg-white/60 border border-transparent rounded-full text-[13px] font-medium focus:bg-white focus:shadow-md focus:outline-none transition-all w-48 text-[#1D1D1F] placeholder:text-[#86868B]"
                             />
                         </div>
                         <button onClick={fetchJobs} disabled={isFetching} className={`p-2.5 rounded-full bg-white/60 hover:bg-white border border-transparent hover:shadow-md text-[#1D1D1F] transition-all hover:scale-105 active:scale-95 ${isFetching ? 'animate-spin' : ''}`} title="Scout">
                             <Sparkles size={18} />
                         </button>
                         <button onClick={() => setIsAddLinkOpen(true)} className="p-2.5 rounded-full bg-[#1D1D1F] text-white border border-transparent shadow-md hover:scale-105 active:scale-95 transition-all" title="Add">
                             <Plus size={18} />
                         </button>
                    </div>
                </div>

                {/* Content Scroller */}
                <div className="flex-1 overflow-y-auto custom-scrollbar px-8 pb-32">

                    {currentView === ViewState.DASHBOARD && (
                        <div className="max-w-6xl mx-auto pt-2">
                            {/* Hero Greeting */}
                            <div className="mb-10 text-center space-y-3 py-6">
                                <h2 className="text-4xl font-semibold text-[#1D1D1F] tracking-tight">
                                    Good afternoon, Vyom.
                                </h2>
                                <p className="text-[#86868B] text-xl font-medium">
                                    You have <span className="text-[#007AFF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} saved opportunities</span> to review.
                                </p>
                            </div>

                            {/* Filters Bar */}
                            <div className="flex items-center justify-between mb-8 sticky top-0 z-20 bg-white/80 backdrop-blur-xl p-2 rounded-2xl border border-white/50 shadow-sm">
                                <div className="flex p-1 bg-[#E5E5EA]/50 rounded-xl">
                                    {['new', 'saved', 'archived'].map((tab) => {
                                        const count = allJobs.filter(j => {
                                                if (tab === 'new') return (j.status || 'new') === 'new';
                                                if (tab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(j.status || '');
                                                return j.status === 'archived';
                                            }).length;
                                        const isActive = activeTab === tab;
                                        return (
                                            <button 
                                                key={tab}
                                                onClick={() => setActiveTab(tab as any)} 
                                                className={`px-5 py-1.5 rounded-lg text-[13px] font-semibold capitalize transition-all ${isActive ? 'bg-white text-black shadow-sm' : 'text-[#86868B] hover:text-[#1D1D1F]'}`}
                                            >
                                                {tab} <span className="opacity-50 ml-1">{count}</span>
                                            </button>
                                        );
                                    })}
                                </div>

                                <button 
                                    onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')}
                                    className="flex items-center gap-2 px-4 py-1.5 bg-white rounded-lg text-xs font-bold text-[#1D1D1F] shadow-sm hover:bg-gray-50 transition-colors mr-1"
                                >
                                    <ArrowDownUp size={12} /> {sortBy === 'date' ? 'Date' : 'Score'}
                                </button>
                            </div>

                            {/* Job List */}
                            <div className="space-y-6">
                                {filteredJobs.length === 0 ? (
                                    <div className="py-24 text-center text-[#86868B]">
                                        <p>No jobs found in this view.</p>
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="text-[#007AFF] text-sm font-medium mt-2 hover:underline">Clear Filters</button>
                                    </div>
                                ) : (
                                    filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))
                                )}
                            </div>
                        </div>
                    )}

                    {currentView === ViewState.KANBAN && (
                        <div className="h-full pt-4">
                            <KanbanBoard 
                                jobs={allJobs} 
                                onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                                onToggleStatus={handleKanbanMove}
                                onDelete={handleDelete}
                                onOpenDetail={handleOpenDetail}
                                onOpenAddModal={() => setIsAddLinkOpen(true)}
                            />
                        </div>
                    )}

                    {currentView === ViewState.CV_EDITOR && (
                        <div className="h-full pt-4 max-w-5xl mx-auto">
                            <CVEditor />
                        </div>
                    )}
                </div>
            </div>

            {/* --- THE FLOATING DOCK --- */}
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-50">
                <div className="mac-dock h-20 px-6 rounded-[32px] flex items-center gap-6 transition-all hover:scale-[1.02]">
                    {[
                        { id: ViewState.DASHBOARD, label: 'Discover', icon: LayoutGrid },
                        { id: ViewState.KANBAN, label: 'Pipeline', icon: Kanban },
                        { id: ViewState.CV_EDITOR, label: 'Resume', icon: FileText }
                    ].map(item => {
                        const isActive = currentView === item.id;
                        return (
                            <button
                                key={item.id}
                                onClick={() => setCurrentView(item.id)}
                                className="group relative flex flex-col items-center justify-center gap-1 w-14 h-14 rounded-2xl hover:bg-white/40 transition-all duration-300"
                            >
                                <div className={`p-3 rounded-2xl transition-all duration-300 ${isActive ? 'bg-[#007AFF] text-white shadow-lg shadow-blue-500/30 -translate-y-4 scale-110' : 'text-[#86868B] group-hover:text-[#1D1D1F] group-hover:-translate-y-2'}`}>
                                    <item.icon size={26} strokeWidth={isActive ? 2.5 : 2} />
                                </div>
                                {isActive && <div className="w-1.5 h-1.5 rounded-full bg-[#007AFF] absolute -bottom-2"></div>}
                            </button>
                        );
                    })}
                </div>
            </div>
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, TrendingUp, Trash2, Bookmark, Archive, Zap, ArrowRight } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="mac-card p-5 rounded-[24px] hover:shadow-lg transition-all group flex flex-col gap-3 relative cursor-pointer outline-none hover:-translate-y-1 duration-300 bg-white"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-3">
                <h4 className="font-bold text-[14px] text-[#1D1D1F] leading-tight line-clamp-2">
                    {job.title}
                </h4>
                {analysis?.isHighValue && (
                    <div className="shrink-0 w-2 h-2 rounded-full bg-[#34C759] shadow-[0_0_8px_rgba(52,199,89,0.5)]"></div>
                )}
            </div>

            <p className="text-[12px] font-medium text-[#86868B] line-clamp-1">{job.company}</p>

            {/* Tiny Tags for Kanban */}
            <div className="flex flex-wrap gap-1.5 mt-1">
                 {job.seniorityScore && (
                     <span className="px-1.5 py-0.5 rounded-md text-[9px] font-bold bg-[#F2F2F7] text-[#8E8E93]">{job.seniorityScore}</span>
                 )}
                 {analysis?.score && analysis.score > 80 && (
                     <span className="px-1.5 py-0.5 rounded-md text-[9px] font-bold bg-[#E6F4EA] text-[#34C759]">{analysis.score}</span>
                 )}
            </div>
        </div>
      );
  }

  return (
    <div 
        onClick={() => onOpenDetail(job)}
        className={`mac-card rounded-[32px] p-8 transition-all duration-300 relative group cursor-pointer hover:bg-white hover:scale-[1.01] ${status === 'archived' ? 'opacity-50 grayscale' : ''}`}
    >

      {/* Hover Actions */}
      <div className="absolute top-8 right-8 flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all duration-200 z-10">
         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
            className="p-2.5 text-[#8E8E93] hover:text-[#FF3B30] hover:bg-[#FF3B30]/10 rounded-full transition-all" 
            title={status === 'archived' ? "Delete Permanently" : "Archive"}
         >
            {status === 'archived' ? <Trash2 size={20} /> : <Archive size={20} />}
         </button>

         {status !== 'archived' && (
             <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                className={`p-2.5 rounded-full transition-all ${isSavedOrBetter 
                    ? 'text-[#007AFF] bg-[#007AFF]/10' 
                    : 'text-[#8E8E93] hover:bg-[#F2F2F7]'}`}
             >
                 <Bookmark size={20} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}
      </div>

      <div className="flex flex-col md:flex-row gap-8 items-start">
          {/* Score Ring */}
          <div className="shrink-0 pt-1">
             {analysis ? (
                 <div className="w-[80px] h-[80px] rounded-full bg-white shadow-sm border border-[#E5E5EA] flex flex-col items-center justify-center relative">
                    <svg className="absolute inset-0 w-full h-full -rotate-90" viewBox="0 0 36 36">
                        <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="#F2F2F7" strokeWidth="2.5" />
                        <path 
                            d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" 
                            fill="none" 
