      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="mac-card p-6 rounded-[28px] hover:shadow-xl transition-all group flex flex-col gap-4 relative cursor-pointer outline-none hover:-translate-y-1 duration-300 bg-white"
