                     <span className="px-2 py-0.5 rounded-md text-[10px] font-bold bg-[#F2F2F7] text-[#8E8E93]">{job.seniorityScore}</span>
                 )}
                 {analysis?.score && analysis.score > 80 && (
                     <span className="px-2 py-0.5 rounded-md text-[10px] font-bold bg-[#E6F4EA] text-[#34C759]">{analysis.score}</span>
