import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, bgClass: string, accentColor: string }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={18} />, bgClass: 'bg-white/40', accentColor: 'text-[#007AFF]' },
      { id: 'applied', title: 'Applied', icon: <Send size={18} />, bgClass: 'bg-white/40', accentColor: 'text-[#007AFF]' },
      { id: 'interview', title: 'Interview', icon: <Users size={18} />, bgClass: 'bg-[#FF9500]/10', accentColor: 'text-[#FF9500]' },
      { id: 'offer', title: 'Offer', icon: <Trophy size={18} />, bgClass: 'bg-[#34C759]/10', accentColor: 'text-[#34C759]' },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 flex gap-6 overflow-x-auto pb-24 items-stretch custom-scrollbar snap-x snap-mandatory px-4">
        {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className={`flex flex-col h-full min-w-[360px] rounded-[32px] p-4 transition-colors ${col.bgClass} border border-white/40 backdrop-blur-xl snap-center`}
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className={`flex items-center justify-between mb-5 px-3 pt-2 ${col.accentColor}`}>
                        <h3 className="font-bold text-[16px] flex items-center gap-2">
                            {col.icon} {col.title}
                        </h3>
                        <span className="text-[11px] bg-white/60 border border-white/20 px-3 py-1 rounded-full font-bold shadow-sm text-[#86868B]">{colJobs.length}</span>
                    </div>

                    <div className="flex-1 space-y-4 overflow-y-auto pr-2 custom-scrollbar pb-8">
                        {colJobs.length === 0 && (
                            <div className="text-center py-20 border-2 border-dashed border-[#d1d1d6]/50 rounded-[24px]">
                                <p className="text-xs font-semibold text-[#8E8E93]">No jobs</p>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className="cursor-grab active:cursor-grabbing transform transition-transform hover:scale-[1.02]"
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
        })}
      </div>
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useEffect, useMemo } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Settings, Command, Sparkles, SlidersHorizontal, ArrowDownUp, ChevronRight } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="min-h-screen bg-[#F5F5F7] pb-20">

        {/* GLOBAL NAVIGATION BAR (Apple Style) */}
        <nav className="fixed top-0 left-0 right-0 h-12 bg-[#1d1d1f]/90 backdrop-blur-md z-50 text-[#f5f5f7] text-[12px]">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-bold text-base tracking-tight"><Command size={18} className="inline mr-1" /> JobOS</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] font-medium">
                            <Sparkles size={12} className="animate-spin" /> Analyzing...
                        </span>
                     )}
                     <div className="w-6 h-6 rounded-full bg-gray-600 flex items-center justify-center text-[10px] font-bold">VP</div>
                 </div>
            </div>
        </nav>

        {/* HERO SECTION */}
        <div className="pt-24 pb-12 px-6 max-w-[1024px] mx-auto">
            {currentView === ViewState.DASHBOARD && (
                <>
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 animate-fade-in-up">
                        <div>
                            <h1 className="text-[48px] md:text-[56px] leading-[1.05] font-semibold text-[#1d1d1f] tracking-tight mb-4">
                                Discover your <br/>
                                <span className="text-[#86868b]">next role.</span>
                            </h1>
                            <p className="text-[#1d1d1f] text-lg font-medium">
                                <span className="text-[#0071e3] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> saved for you.
                            </p>
                        </div>

                        <div className="flex gap-3">
                             <button 
                                onClick={fetchJobs} 
                                disabled={isFetching}
                                className={`h-10 px-5 rounded-full bg-[#0071e3] hover:bg-[#0077ED] text-white text-sm font-medium transition-all flex items-center gap-2 ${isFetching ? 'opacity-70' : ''}`}
                             >
                                <Search size={16} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}
                             </button>
                             <button 
                                onClick={() => setIsAddLinkOpen(true)}
                                className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] text-[#1d1d1f] transition-all"
                             >
                                <Plus size={18} />
                             </button>
                        </div>
                    </div>

                    {/* DASHBOARD GRID LAYOUT */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-fade-in-up" style={{ animationDelay: '0.1s' }}>

                        {/* LEFT COLUMN: FILTERS & WIDGETS */}
                        <div className="lg:col-span-3 space-y-6">
                            {/* Filter Widget */}
                            <div className="apple-card p-6">
                                <h3 className="text-xs font-bold text-[#86868b] uppercase tracking-wider mb-4">Locations</h3>
                                <div className="space-y-1">
                                    {filterOptions.map(city => {
                                        const count = city === 'All' ? jobsInCurrentTab.length : jobsInCurrentTab.filter(j => city === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(city.toLowerCase())).length;
                                        if (count === 0 && city !== 'All') return null;
                                        const isSelected = cityFilter === city;
                                        return (
                                            <button 
                                                key={city} 
                                                onClick={() => setCityFilter(city)} 
                                                className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm transition-all ${isSelected ? 'bg-[#F5F5F7] font-semibold text-[#0071e3]' : 'text-[#1d1d1f] hover:bg-[#F5F5F7]'}`}
                                            >
                                                <span>{city}</span>
                                                <span className="text-[#86868b] text-xs">{count}</span>
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* Chart Widget */}
                            <div className="apple-card p-6">
                                <StatsPanel 
                                    jobs={jobsInCurrentTab} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        </div>

                        {/* RIGHT COLUMN: CONTENT */}
                        <div className="lg:col-span-9">
                            {/* Tabs Pill */}
                            <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-2">
                                {['new', 'saved', 'archived'].map((tab) => {
                                    const isActive = activeTab === tab;
                                    return (
                                        <button 
                                            key={tab}
                                            onClick={() => setActiveTab(tab as any)} 
                                            className={`px-5 py-2 rounded-full text-sm font-medium capitalize whitespace-nowrap transition-all ${isActive ? 'bg-[#1d1d1f] text-white' : 'bg-white text-[#1d1d1f] border border-[#d2d2d7] hover:border-[#86868b]'}`}
                                        >
                                            {tab}
                                        </button>
                                    );
                                })}
                                <div className="ml-auto flex items-center gap-2">
                                    <span className="text-xs text-[#86868b] font-medium mr-1">Sort by:</span>
                                    <button 
                                        onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')}
                                        className="text-xs font-bold text-[#0071e3] hover:underline"
                                    >
                                        {sortBy === 'date' ? 'Date' : 'Match Score'}
                                    </button>
                                </div>
                            </div>

                            {/* Job List */}
                            <div className="space-y-4">
                                {filteredJobs.length === 0 ? (
                                    <div className="py-20 text-center text-[#86868b]">
                                        <p className="text-lg">No opportunities found.</p>
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="text-[#0071e3] font-medium mt-2 hover:underline">Clear Filters</button>
                                    </div>
                                ) : (
                                    filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </>
            )}

            {currentView === ViewState.KANBAN && (
                <div className="h-[calc(100vh-100px)]">
                    <h1 className="text-[40px] font-semibold text-[#1d1d1f] tracking-tight mb-8">Pipeline</h1>
                    <KanbanBoard 
                        jobs={allJobs} 
                        onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                        onToggleStatus={handleKanbanMove}
                        onDelete={handleDelete}
                        onOpenDetail={handleOpenDetail}
                        onOpenAddModal={() => setIsAddLinkOpen(true)}
                    />
                </div>
            )}

            {currentView === ViewState.CV_EDITOR && (
                <div className="h-[calc(100vh-100px)]">
                     <h1 className="text-[40px] font-semibold text-[#1d1d1f] tracking-tight mb-8">Resume</h1>
                    <CVEditor />
                </div>
            )}
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, TrendingUp, Trash2, Bookmark, Archive, Zap, ArrowRight, Star } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  if (isKanban) {
      return (
        <div 
            className="apple-card p-5 cursor-pointer border border-transparent hover:border-[#0071e3]/20 flex flex-col gap-3 h-full justify-between"
            onClick={() => onOpenDetail(job)}
        >
            <div>
                <div className="flex justify-between items-start gap-3 mb-2">
                    <h4 className="font-semibold text-[15px] text-[#1d1d1f] leading-snug line-clamp-2">
                        {job.title}
                    </h4>
                    {analysis?.isHighValue && (
                        <div className="shrink-0 w-2 h-2 rounded-full bg-[#34C759]"></div>
                    )}
                </div>
                <p className="text-[13px] text-[#86868b] font-medium">{job.company}</p>
            </div>

            <div className="flex items-center gap-2 mt-2">
                 {analysis?.score && analysis.score > 80 && (
                     <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-[#E6F4EA] text-[#34C759]">{analysis.score}</span>
                 )}
            </div>
        </div>
      );
  }

  return (
    <div 
        onClick={() => onOpenDetail(job)}
        className={`apple-card p-8 group cursor-pointer border border-transparent hover:border-[#0071e3]/10 relative ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}
    >

      {/* Top Right Actions */}
      <div className="absolute top-8 right-8 flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
            className="w-8 h-8 flex items-center justify-center rounded-full bg-[#F5F5F7] hover:bg-[#FF3B30] hover:text-white text-[#86868b] transition-colors"
         >
            {status === 'archived' ? <Trash2 size={14} /> : <Archive size={14} />}
         </button>

         {status !== 'archived' && (
             <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                className={`w-8 h-8 flex items-center justify-center rounded-full transition-colors ${isSavedOrBetter 
                    ? 'bg-[#0071e3] text-white' 
                    : 'bg-[#F5F5F7] text-[#86868b] hover:bg-[#d2d2d7]'}`}
             >
                 <Bookmark size={14} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}
      </div>

      <div className="flex flex-col sm:flex-row gap-6 items-start">

          {/* Main Info */}
          <div className="flex-1">
             <div className="mb-1 flex items-center gap-2">
                 <h3 className="text-[21px] font-semibold text-[#1d1d1f] tracking-tight group-hover:text-[#0071e3] transition-colors">
                    {job.title}
                 </h3>
                 {job.isRelatedDiscovery && <span className="bg-[#FFCC00] text-white text-[10px] font-bold px-1.5 py-0.5 rounded">NEW</span>}
             </div>

             <div className="flex items-center gap-4 text-[13px] font-medium text-[#86868b] mb-4">
                <span>{job.company}</span>
                <span>•</span>
                <span>{job.location}</span>
                <span>•</span>
                <span>{job.postedDate}</span>
             </div>

             {/* Chips */}
             <div className="flex flex-wrap items-center gap-2 mb-6">
                {analysis?.industry && (
                     <span className="px-3 py-1 rounded-full text-[11px] font-semibold bg-[#E8F2FF] text-[#0071e3]">{analysis.industry}</span>
                )}
                {analysis?.isHighValue && (
                     <span className="px-3 py-1 rounded-full text-[11px] font-semibold bg-[#E6F4EA] text-[#34C759]">High Value</span>
                )}
                 {job.seniorityScore && (
                     <span className="px-3 py-1 rounded-full text-[11px] font-semibold bg-[#F5F5F7] text-[#1d1d1f]">{job.seniorityScore}</span>
                )}
             </div>

             {/* Verdict Text */}
             {analysis && (
                 <p className="text-[15px] text-[#1d1d1f] leading-relaxed max-w-2xl mb-6">
                    {analysis.verdict}
                 </p>
             )}

             {/* Actions */}
             <div className="flex items-center gap-4">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    onClick={(e) => e.stopPropagation()}
                    className="apple-button px-5 py-2 text-[13px] font-medium flex items-center gap-2"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply' : 'Search'} <ExternalLink size={12} />
                 </a>
                 <span className="text-[13px] font-medium text-[#0071e3] flex items-center gap-1 group-hover:translate-x-1 transition-transform">
                     View Strategy <ArrowRight size={12} />
                 </span>
             </div>
          </div>

          {/* Score Circle (Right aligned on desktop) */}
          <div className="shrink-0">
             {analysis ? (
                 <div className="w-[60px] h-[60px] rounded-full border-4 border-[#F5F5F7] flex items-center justify-center" style={{ borderColor: analysis.score > 70 ? '#34C759' : '#F5F5F7' }}>
                    <span className="text-lg font-bold text-[#1d1d1f]">{analysis.score}</span>
                 </div>
             ) : null}
          </div>
      </div>
    </div>
  );
};

