                                className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] text-[#1d1d1f] transition-all hover:scale-105 active:scale-95"
                             >
                                <Plus size={18} />
                             </button>
                        </div>
                    </div>

                    {/* DASHBOARD GRID LAYOUT - Added items-start to fix sticky behavior */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-fade-in-up items-start" style={{ animationDelay: '0.1s' }}>

                        {/* LEFT COLUMN: FILTERS & WIDGETS */}
