import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, count: number }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={16} />, count: jobs.filter(j => j.status === 'saved').length },
      { id: 'applied', title: 'Applied', icon: <Send size={16} />, count: jobs.filter(j => j.status === 'applied').length },
      { id: 'interview', title: 'Interview', icon: <Users size={16} />, count: jobs.filter(j => j.status === 'interview').length },
      { id: 'offer', title: 'Offer', icon: <Trophy size={16} />, count: jobs.filter(j => j.status === 'offer').length },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    <div className="flex flex-1 gap-6 overflow-x-auto px-4 pb-6 -mx-4 items-start">
      {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className="flex flex-col min-w-[320px] max-w-[320px] bg-[#E8E8ED]/30 rounded-[20px] p-2 h-[calc(100vh-220px)]"
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className="flex items-center justify-between p-4 mb-2 shrink-0">
                        <h3 className="font-semibold text-[15px] text-[#1d1d1f] flex items-center gap-2">
                            {col.icon} {col.title}
                        </h3>
                        <span className="text-[11px] font-bold text-[#86868b] bg-white px-2 py-0.5 rounded-full shadow-sm">{col.count}</span>
                    </div>

                    <div className="flex-1 space-y-3 overflow-y-auto px-2 pb-4 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="h-32 border-2 border-dashed border-[#d2d2d7]/50 rounded-xl flex items-center justify-center">
                                <span className="text-xs text-[#86868b] font-medium">No jobs</span>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className="cursor-grab active:cursor-grabbing hover:scale-[1.02] transition-transform"
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
      })}
    </div>
  );
};

export default KanbanBoard;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, RotateCcw, RotateCw, Wand2, Search, Type, List, X, Check, Save, BookOpen } from 'lucide-react';
import { improveCV } from '../services/geminiService';
import { saveCV, getCV } from '../services/firebase';

const CVEditor: React.FC = () => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');

  // AI Panel State
  const [showAiPanel, setShowAiPanel] = useState(false);
  const [showDoc, setShowDoc] = useState(false);
  const [aiMode, setAiMode] = useState<'impact' | 'clarify' | null>(null);
  const [selectedText, setSelectedText] = useState('');
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Initial Load from Firestore
  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded');
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
        }
    };
    loadContent();
  }, []);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }
  }, []);

  // Debounced auto-save
  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };

      const el = editorRef.current;
      const rawInputHandler = () => {
         handleInput();
      };

      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const initAI = (type: 'impact' | 'clarify') => {
    const selection = window.getSelection();
    const text = selection?.toString();

    if (!text || text.trim().length === 0) {
        alert("Please highlight text in your CV first.");
        return;
    }

    setSelectedText(text);
    setAiMode(type);
    setShowAiPanel(true);
    setAiSuggestion('');
    generateSuggestion(text, type);
  };

  const generateSuggestion = async (text: string, type: 'impact' | 'clarify') => {
    setIsAiLoading(true);
    try {
        const promptText = type === 'impact' 
            ? "Identify weak verbs and passive voice. Rewrite this to be action-oriented, using strong power verbs. Return ONLY the rewritten text." 
            : "Clarify this text. Remove fluff, fix grammar, and make it concise and punchy. Return ONLY the rewritten text.";

        const result = await improveCV(text, promptText);
        setAiSuggestion(result);
    } catch (e) {
        setAiSuggestion("Error generating suggestion. Please try again.");
    } finally {
        setIsAiLoading(false);
    }
  };

  const applySuggestion = () => {
      if (editorRef.current && aiSuggestion) {
          editorRef.current.focus();
          document.execCommand('insertText', false, aiSuggestion);
          saveContent();
          closeAiPanel();
      }
  };

  const closeAiPanel = () => {
      setShowAiPanel(false);
      setAiMode(null);
      setSelectedText('');
      setAiSuggestion('');
  };

  return (
    <div className="flex h-full relative overflow-hidden bg-[#F5F5F7]">

        {/* Reference Document Panel */}
        {showDoc && (
             <div className="w-1/2 h-full border-r border-[#d2d2d7] bg-white hidden lg:block animate-in slide-in-from-left-4 duration-300">
                 <iframe 
                    src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" 
                    className="w-full h-full" 
                    title="Reference CV"
                 ></iframe>
             </div>
        )}

        {/* Main Editor Area */}
        <div className={`flex-1 flex flex-col h-full relative transition-all duration-300 ${showAiPanel ? 'mr-[360px]' : ''}`}>

            {/* Scrollable Paper Area */}
            <div className="flex-1 w-full overflow-y-auto custom-scrollbar p-12 flex justify-center pb-32">
                <div 
                    ref={editorRef}
                    contentEditable
                    role="textbox"
                    aria-multiline="true"
                    aria-label="CV Content Editor"
                    className="w-full max-w-[850px] min-h-[1100px] h-max bg-white shadow-xl border border-black/5 p-[72px] outline-none text-[#1d1d1f] font-sans text-lg leading-[1.6] rounded-sm selection:bg-[#B3D7FF]"
                />
            </div>

            {/* Floating Glass Toolbar (Bottom) */}
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-20">
                <div className="flex items-center gap-4 bg-white/80 backdrop-blur-xl px-5 py-3 rounded-full shadow-2xl border border-white/50 animate-in slide-in-from-bottom-10 duration-500">

                    <div className="flex items-center gap-1">
                        <button onClick={() => execCmd('undo')} className="p-2 hover:bg-black/5 rounded-full text-[#1d1d1f] transition-colors"><RotateCcw size={16} /></button>
                        <button onClick={() => execCmd('redo')} className="p-2 hover:bg-black/5 rounded-full text-[#1d1d1f] transition-colors"><RotateCw size={16} /></button>
                    </div>

                    <div className="w-px h-6 bg-black/10"></div>

                    <div className="flex items-center gap-1">
