                        <button onClick={() => execCmd('bold')} className="p-2 hover:bg-black/5 rounded-full text-[#1d1d1f]" title="Bold"><Bold size={16} /></button>
                        <button onClick={() => execCmd('italic')} className="p-2 hover:bg-black/5 rounded-full text-[#1d1d1f]" title="Italic"><Italic size={16} /></button>
                        <button onClick={() => execCmd('insertUnorderedList')} className="p-2 hover:bg-black/5 rounded-full text-[#1d1d1f]" title="List"><List size={16} /></button>
