                        <button 
                            onClick={() => initAI('clarify')} 
                            className="flex items-center gap-2 px-4 py-1.5 bg-[#f5f5f7] text-[#1d1d1f] rounded-full text-xs font-bold hover:bg-[#e8e8ed] transition-all"
                        >
                            <Wand2 size={14} /> Clarify
