        {/* Right Sidebar for AI Results (Fixed) */}
        <div className={`absolute top-0 right-0 h-full w-[360px] bg-white shadow-2xl transform transition-transform duration-300 z-30 flex flex-col ${showAiPanel ? 'translate-x-0' : 'translate-x-full'}`}>
            <div className="p-6 border-b border-[#f5f5f7] flex items-center justify-between">
                <h3 className="text-lg font-bold text-[#1d1d1f] flex items-center gap-2">
                    {aiMode === 'impact' ? <Search size={20} className="text-[#0071e3]" /> : <Wand2 size={20} className="text-[#0071e3]" />}
                    {aiMode === 'impact' ? 'Impact Review' : 'Clarify Text'}
                </h3>
                <button onClick={closeAiPanel} className="p-2 hover:bg-[#f5f5f7] rounded-full text-[#86868b]">
                    <X size={20} />
                </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-[#fbfbfd]">
                <div className="mb-8">
                    <label className="text-[11px] font-bold text-[#86868b] uppercase tracking-wider mb-3 block">Selected Text</label>
                    <div className="p-4 bg-white rounded-2xl text-sm text-[#86868b] border border-[#f5f5f7] italic leading-relaxed">
                        "{selectedText}"
                    </div>
                </div>

                <div>
                    <label className="text-[11px] font-bold text-[#86868b] uppercase tracking-wider mb-3 block">Suggestion</label>
                    {isAiLoading ? (
                        <div className="flex flex-col items-center py-10 gap-4">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#0071e3]"></div>
                            <span className="text-xs text-[#86868b] font-medium">Drafting improvements...</span>
                        </div>
                    ) : (
                        <div className="p-5 bg-white rounded-2xl text-[15px] text-[#1d1d1f] border-2 border-[#0071e3] shadow-lg shadow-blue-500/10 leading-relaxed">
                            {aiSuggestion}
                        </div>
                    )}
                </div>
            </div>

            <div className="p-6 border-t border-[#f5f5f7] bg-white">
                <button 
                    onClick={applySuggestion}
                    disabled={isAiLoading || !aiSuggestion}
                    className="w-full py-3.5 bg-[#0071e3] text-white rounded-full font-bold hover:bg-[#0077ED] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20"
                >
                    <Check size={18} /> Apply Suggestion
                </button>
            </div>
        </div>
    </div>
  );
};

export default CVEditor;

import React, { useState, useEffect, useMemo } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { LayoutGrid, Kanban, FileText, Plus, Search, Command, Sparkles, ArrowDownUp, Layers } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [isFetching, setIsFetching] = useState(false);
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        const ninetyDaysAgo = Date.now() - (90 * 24 * 60 * 60 * 1000);
        jobs.forEach(job => {
            const scoutTime = job.scoutedAt || 0;
            if (scoutTime > 0 && scoutTime < ninetyDaysAgo && job.status !== 'archived') {
                updateJobStatus(job.id, 'archived');
            }
        });
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const fetchJobs = async () => {
    if (!isDbConnected) return;
    setIsFetching(true);
    const query = `("Product Designer" OR "UX Designer" OR "UI Designer") "United Kingdom" -Intern -Trainee -Apprentice`;
    try {
      const foundJobs = await searchAndParseJobs(query);
      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }
      if (jobsToAnalyze.length > 0) analyzeNewJobs(jobsToAnalyze);
    } catch (error) { console.error(error); }
    setIsFetching(false);
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleKanbanMove = (jobId: string, destination: Job['status']) => {
      updateJobStatus(jobId, destination!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;

          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { 
              ...placeholder, 
              ...enrichedDetails,
              summary: enrichedDetails.summary || data.text || placeholder.summary
          };
          await addOrUpdateJob(enrichedJob);
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  // --- FILTER LOGIC ---
  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;

        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) {
                 const text = (j.company + " " + j.title + " " + (j.summary || "")).toLowerCase();
                 let calculatedIndustry = 'Tech';
                 if (text.match(/bank|finance|wealth|fintech/)) calculatedIndustry = 'Fintech';
                 else if (text.match(/insurance|underwrit/)) calculatedIndustry = 'Insurance';
                 else if (text.match(/gov|public|council|nhs/)) calculatedIndustry = 'Public Sector';
                 else if (text.match(/agency|studio/)) calculatedIndustry = 'Agency';

                 if (calculatedIndustry !== industryFilter) return false;
            }
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') {
              return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          }
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  return (
    <div className="min-h-screen bg-[#F5F5F7] pb-20 font-sans">

        {/* GLOBAL NAVIGATION BAR */}
        <nav className="fixed top-0 left-0 right-0 h-12 bg-[#1d1d1f]/80 backdrop-blur-xl z-50 text-[#f5f5f7] text-[12px] border-b border-white/5">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-white flex items-center gap-2"><Layers size={18} /> Career Studio</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] font-medium">
                            <Sparkles size={12} className="animate-spin" /> Analyzing...
                        </span>
                     )}
                     <div className="w-6 h-6 rounded-full bg-gray-600 flex items-center justify-center text-[10px] font-bold ring-2 ring-white/10">VP</div>
                 </div>
            </div>
        </nav>

        {/* HERO SECTION */}
        <div className="pt-24 pb-10 px-6 max-w-[1024px] mx-auto">
            {currentView === ViewState.DASHBOARD && (
                <>
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 animate-fade-in-up">
                        <div>
                            <h1 className="text-[48px] md:text-[64px] leading-[1.05] font-semibold text-[#1d1d1f] tracking-tight mb-4">
                                Masterplan your <br/>
                                <span className="text-[#86868b]">next move.</span>
                            </h1>
                            <p className="text-[#1d1d1f] text-lg font-medium max-w-lg leading-relaxed">
                                <span className="text-[#0071e3] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> tailored to your experience.
                            </p>
                        </div>

                        <div className="flex gap-3 pb-2">
                             <button 
                                onClick={fetchJobs} 
                                disabled={isFetching}
                                className={`h-10 px-6 rounded-full bg-[#0071e3] hover:bg-[#0077ED] text-white text-sm font-medium transition-all flex items-center gap-2 ${isFetching ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/20'}`}
                             >
                                <Search size={16} /> {isFetching ? 'Scouting...' : 'Scout Jobs'}
                             </button>
                             <button 
                                onClick={() => setIsAddLinkOpen(true)}
                                className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] text-[#1d1d1f] transition-all hover:scale-105 active:scale-95"
                             >
                                <Plus size={18} />
                             </button>
                        </div>
                    </div>

                    {/* DASHBOARD GRID LAYOUT - Added items-start to fix sticky behavior */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-fade-in-up items-start" style={{ animationDelay: '0.1s' }}>

                        {/* LEFT COLUMN: FILTERS & WIDGETS */}
                        <div className="lg:col-span-3 space-y-6 sticky top-24">
                            {/* Filter Widget */}
                            <div className="bg-white rounded-[24px] p-5 shadow-sm border border-black/5">
                                <h3 className="text-[11px] font-bold text-[#86868b] uppercase tracking-wider mb-3">Locations</h3>
                                <div className="space-y-1">
                                    {filterOptions.map(city => {
                                        const count = city === 'All' ? jobsInCurrentTab.length : jobsInCurrentTab.filter(j => city === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(city.toLowerCase())).length;
                                        if (count === 0 && city !== 'All') return null;
                                        const isSelected = cityFilter === city;
                                        return (
                                            <button 
                                                key={city} 
                                                onClick={() => setCityFilter(city)} 
                                                className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-[13px] transition-all ${isSelected ? 'bg-[#F5F5F7] font-semibold text-[#0071e3]' : 'text-[#1d1d1f] hover:bg-[#F5F5F7]'}`}
                                            >
                                                <span>{city}</span>
                                                <span className="text-[#86868b] text-[11px]">{count}</span>
                                            </button>
                                        );
                                    })}
                                </div>

                                <div className="w-full h-px bg-[#F5F5F7] my-5"></div>

                                <StatsPanel 
                                    jobs={jobsInCurrentTab} 
                                    selectedIndustry={industryFilter}
                                    onSelectIndustry={setIndustryFilter}
                                />
                            </div>
                        </div>

                        {/* RIGHT COLUMN: CONTENT */}
                        <div className="lg:col-span-9">
                            {/* Tabs Pill */}
                            <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-2 scrollbar-hide">
                                {['new', 'saved', 'archived'].map((tab) => {
                                    const isActive = activeTab === tab;
                                    return (
                                        <button 
                                            key={tab}
                                            onClick={() => setActiveTab(tab as any)} 
                                            className={`px-5 py-2 rounded-full text-[13px] font-medium capitalize whitespace-nowrap transition-all ${isActive ? 'bg-[#1d1d1f] text-white' : 'bg-white text-[#1d1d1f] border border-[#d2d2d7] hover:border-[#86868b]'}`}
                                        >
                                            {tab}
                                        </button>
                                    );
                                })}
                                <div className="ml-auto flex items-center gap-2">
                                    <span className="text-[11px] text-[#86868b] font-medium mr-1">Sort by:</span>
                                    <button 
                                        onClick={() => setSortBy(sortBy === 'date' ? 'score' : 'date')}
                                        className="text-[11px] font-bold text-[#0071e3] hover:underline flex items-center gap-1"
                                    >
                                        {sortBy === 'date' ? 'Date' : 'Match Score'} <ArrowDownUp size={12}/>
                                    </button>
                                </div>
                            </div>

                            {/* Job List */}
                            <div className="space-y-6">
                                {filteredJobs.length === 0 ? (
                                    <div className="py-20 text-center text-[#86868b]">
                                        <p className="text-lg font-medium">No opportunities found.</p>
                                        <button onClick={() => { setCityFilter('All'); setIndustryFilter(null); }} className="text-[#0071e3] font-medium mt-2 hover:underline">Clear Filters</button>
                                    </div>
                                ) : (
                                    filteredJobs.map(job => (
                                        <JobCard key={job.id} job={job} onOpenDetail={handleOpenDetail} onToggleStatus={toggleJobStatus} onDelete={handleDelete} />
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                </>
            )}

            {currentView === ViewState.KANBAN && (
                <div className="h-[calc(100vh-100px)] animate-fade-in-up flex flex-col">
                    <div className="flex items-center justify-between mb-8">
                        <h1 className="text-[40px] font-semibold text-[#1d1d1f] tracking-tight">Pipeline</h1>
                        <button 
                            onClick={() => setIsAddLinkOpen(true)}
                            className="h-10 px-5 rounded-full bg-[#1d1d1f] hover:bg-black text-white text-sm font-medium transition-all flex items-center gap-2 shadow-lg"
                        >
                            <Plus size={16} /> Add Job
                        </button>
                    </div>
                    <div className="flex-1 min-h-0">
                        <KanbanBoard 
                            jobs={allJobs} 
                            onGenerateKit={(job) => handleOpenDetail(job, 'strategy')}
                            onToggleStatus={handleKanbanMove}
                            onDelete={handleDelete}
                            onOpenDetail={handleOpenDetail}
                            onOpenAddModal={() => setIsAddLinkOpen(true)}
                        />
                    </div>
                </div>
            )}

            {currentView === ViewState.CV_EDITOR && (
                <div className="h-[calc(100vh-100px)] animate-fade-in-up">
                     <h1 className="text-[40px] font-semibold text-[#1d1d1f] tracking-tight mb-8">Resume</h1>
                    <CVEditor />
                </div>
            )}
        </div>

      <JobDetailModal 
        isOpen={modalOpen} 
        onClose={() => setModalOpen(false)} 
        job={selectedJob} 
        onGenerateKit={handleGenerateKit}
        initialTab={initialModalTab}
        onUpdateJob={handleUpdateJob}
        onReAnalyze={handleReAnalyzeJob}
      />

      <AddLinkModal 
        isOpen={isAddLinkOpen}
        onClose={() => setIsAddLinkOpen(false)}
        onAdd={handleAddManualJob}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Job } from '../types';
import { AlertTriangle, Briefcase, MapPin, ExternalLink, TrendingUp, Trash2, Bookmark, Archive, Zap, ArrowRight } from 'lucide-react';

interface JobCardProps {
  job: Job;
  onOpenDetail: (job: Job, tab?: 'brief' | 'strategy') => void;
  onToggleStatus: (id: string, currentStatus: Job['status']) => void;
  onDelete: (id: string) => void;
  isKanban?: boolean;
}

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // Tiny Card for Kanban
  if (isKanban) {
      return (
        <div 
            className="bg-white rounded-[20px] p-4 cursor-pointer shadow-sm hover:shadow-md transition-all flex flex-col gap-3 h-full justify-between border border-transparent hover:border-[#0071e3]/10"
            onClick={() => onOpenDetail(job)}
        >
            <div>
                <div className="flex justify-between items-start gap-2 mb-1">
                    <h4 className="font-semibold text-[14px] text-[#1d1d1f] leading-snug line-clamp-2">
                        {job.title}
                    </h4>
                    {analysis?.score && analysis.score > 80 && (
                        <div className="shrink-0 w-2 h-2 rounded-full bg-[#34C759]"></div>
                    )}
                </div>
                <p className="text-[12px] text-[#86868b] font-medium">{job.company}</p>
            </div>

            <div className="flex items-center gap-2 mt-auto">
                 {analysis?.score && (
                     <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${analysis.score > 70 ? 'bg-[#E6F4EA] text-[#137333]' : 'bg-[#F5F5F7] text-[#5F6368]'}`}>
                        {analysis.score}% Match
                     </span>
                 )}
            </div>
        </div>
      );
  }

  // Full "Bento" Card for Dashboard
  return (
    <div 
        onClick={() => onOpenDetail(job)}
        className={`apple-card p-8 group cursor-pointer border border-transparent relative hover:border-[#0071e3]/10 ${status === 'archived' ? 'opacity-60 grayscale' : ''}`}
    >

      {/* Top Right Actions (No Overlap) */}
      <div className="absolute top-6 right-6 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
         {status !== 'archived' && (
             <button 
                onClick={(e) => { e.stopPropagation(); onToggleStatus(job.id, status); }}
                className={`w-9 h-9 flex items-center justify-center rounded-full transition-colors shadow-sm ${isSavedOrBetter 
                    ? 'bg-[#0071e3] text-white hover:bg-[#0077ED]' 
                    : 'bg-white text-[#86868b] border border-[#d2d2d7] hover:border-[#0071e3] hover:text-[#0071e3]'}`}
                title={isSavedOrBetter ? "Saved" : "Save Job"}
             >
                 <Bookmark size={16} fill={isSavedOrBetter ? "currentColor" : "none"} />
             </button>
         )}

         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(job.id); }} 
            className="w-9 h-9 flex items-center justify-center rounded-full bg-white border border-[#d2d2d7] hover:bg-[#FF3B30] hover:text-white hover:border-[#FF3B30] text-[#86868b] transition-colors shadow-sm"
            title="Archive"
         >
            {status === 'archived' ? <Trash2 size={16} /> : <Archive size={16} />}
         </button>
      </div>

      <div className="flex flex-col sm:flex-row gap-6 items-start">

          {/* Main Content */}
          <div className="flex-1 pr-12">
             <div className="mb-2 flex items-center gap-3">
                 <h3 className="text-[22px] font-semibold text-[#1d1d1f] tracking-tight group-hover:text-[#0071e3] transition-colors">
                    {job.title}
                 </h3>
                 {job.isRelatedDiscovery && <span className="bg-[#FFCC00] text-white text-[10px] font-bold px-1.5 py-0.5 rounded">NEW</span>}
             </div>

             <div className="flex items-center gap-4 text-[13px] font-medium text-[#86868b] mb-5">
                <span className="flex items-center gap-1.5"><Briefcase size={14}/> {job.company}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] rounded-full"></span>
                <span className="flex items-center gap-1.5"><MapPin size={14}/> {job.location}</span>
                <span className="w-1 h-1 bg-[#d2d2d7] rounded-full"></span>
                <span>{job.postedDate}</span>
             </div>

             {/* Chip Row */}
             <div className="flex flex-wrap items-center gap-2 mb-6">
                {/* Match Badge Replaces Ring */}
                {analysis?.score && (
                     <span className={`px-3 py-1 rounded-full text-[12px] font-bold flex items-center gap-1 ${analysis.score > 70 ? 'bg-[#1d1d1f] text-white' : 'bg-[#F5F5F7] text-[#1d1d1f]'}`}>
                        <Zap size={12} fill={analysis.score > 70 ? "currentColor" : "none"} /> {analysis.score}% Match
                     </span>
                )}
                {analysis?.industry && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E8F2FF] text-[#0071e3]">{analysis.industry}</span>
                )}
                {analysis?.isHighValue && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E6F4EA] text-[#34C759] flex items-center gap-1"><TrendingUp size={12}/> High Value</span>
                )}
                 {job.seniorityScore && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#F5F5F7] text-[#1d1d1f]">{job.seniorityScore}</span>
                )}
             </div>

             {/* Verdict - Clean text block */}
             {analysis && (
                 <p className="text-[15px] text-[#1d1d1f] leading-relaxed max-w-2xl mb-6 font-normal">
                    {analysis.verdict}
                 </p>
             )}

             {/* Call to Actions - Removed View Strategy Button */}
             <div className="flex items-center gap-4">
                 <a 
                    href={applyUrl} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    onClick={(e) => e.stopPropagation()}
                    className="apple-button px-6 py-2.5 text-[13px] font-medium flex items-center gap-2 shadow-sm hover:shadow-md"
                 >
                     {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={14} />
                 </a>
             </div>
          </div>
      </div>
    </div>
  );
};

export default JobCard;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  // URL Editing
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');

  // Re-Analyze State
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
        setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleSaveUrl = () => {
      if (onUpdateJob && editedUrl.trim() !== job.url) {
          const finalUrl = editedUrl.trim() || 'Manual Entry';
          onUpdateJob({ ...job, url: finalUrl });
      }
      setIsEditingUrl(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  const handleReAnalyzeClick = async () => {
      if (onReAnalyze) {
          setIsAnalyzing(true);
          await onReAnalyze(job);
          setIsAnalyzing(false);
      }
  };

  const isValidAttribute = (attr?: string) => {
      if (!attr) return false;
      const lower = attr.toLowerCase();
      return lower !== 'unspecified' && lower !== 'unknown' && lower !== 'n/a' && attr.trim() !== '';
  };

  return (
    <div 
        className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 transition-all duration-300"
        role="dialog"
        aria-modal="true"
    >
      {/* Darkened Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>

      {/* Surface - Clean Apple Style */}
      <div className="relative bg-white w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[32px] overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header - Minimalist */}
        <div className="flex items-start justify-between px-8 py-8 shrink-0 bg-white z-10">
           <div className="flex-1 mr-8">
                {/* Title Editing */}
                {isEditingTitle ? (
                    <input 
                    type="text" 
                    value={editedTitle}
                    onChange={(e) => setEditedTitle(e.target.value)}
                    onBlur={handleSaveTitle}
                    onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                    className="text-3xl font-semibold text-[#1d1d1f] w-full outline-none bg-transparent p-0 border-b border-[#0071e3]"
                    autoFocus
                    />
                ) : (
                    <h2 
                    onClick={() => setIsEditingTitle(true)}
                    className="text-3xl font-semibold text-[#1d1d1f] leading-tight cursor-pointer hover:text-[#0071e3] transition-colors"
                    >
                    {job.title}
                    </h2>
                )}

                {/* Company & Location Subtitle */}
                <div className="mt-2 flex items-center gap-2 text-lg text-[#86868b] font-medium">
                    {isEditingCompany ? (
                        <input 
                            type="text" 
                            value={editedCompany}
                            onChange={(e) => setEditedCompany(e.target.value)}
                            onBlur={handleSaveCompany}
                            className="border-b border-[#0071e3] outline-none bg-transparent w-40"
                        />
                    ) : (
                        <span onClick={() => setIsEditingCompany(true)} className="hover:text-[#0071e3] cursor-pointer transition-colors">{job.company}</span>
                    )}
                    <span>•</span>
                    <span>{job.location}</span>
                </div>
           </div>

           <button 
                onClick={onClose} 
                className="w-10 h-10 flex items-center justify-center bg-[#f5f5f7] hover:bg-[#e8e8ed] rounded-full text-[#1d1d1f] transition-colors"
           >
             <X size={20} />
           </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto custom-scrollbar px-8 pb-12">
            <div className="flex flex-col md:flex-row gap-12">

                {/* LEFT: Main Information */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs Pill */}
                    <div className="flex items-center gap-1 mb-8 bg-[#f5f5f7] p-1 rounded-full w-fit">
                        <button 
                            onClick={() => setActiveTab('brief')} 
                            className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${activeTab === 'brief' ? 'bg-white text-black shadow-sm' : 'text-[#86868b] hover:text-[#1d1d1f]'}`}
                        >
                            Overview
                        </button>
                        <button 
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${activeTab === 'strategy' ? 'bg-white text-black shadow-sm' : 'text-[#86868b] hover:text-[#1d1d1f]'}`}
                        >
                            Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                            {/* Chips */}
                            <div className="mb-8 flex flex-wrap gap-2">
                                {analysis && analysis.isHighValue && (
                                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E6F4EA] text-[#1e8e3e]">High Value</span>
                                )}
                                {isValidAttribute(analysis?.industry) && (
                                    <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E8F2FF] text-[#0071e3]">{analysis?.industry}</span>
                                )}
                                {isValidAttribute(job.seniorityScore) && (
                                    <span className="px-3 py-1 bg-[#f5f5f7] text-[#1d1d1f] rounded-full text-[12px] font-semibold">{job.seniorityScore}</span>
                                )}
                            </div>

                            {/* Verdict */}
                            {analysis && (
                                <div className="mb-8">
                                    <h4 className="text-[11px] font-bold text-[#86868b] uppercase tracking-wider mb-2">AI Analysis</h4>
                                    <p className="text-[18px] text-[#1d1d1f] font-medium leading-relaxed">{analysis.verdict}</p>
                                </div>
                            )}

                            {/* Description */}
                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="text-[11px] font-bold text-[#86868b] uppercase tracking-wider">Job Description</h4>
                                    {!isEditingSummary ? (
                                        <button onClick={() => setIsEditingSummary(true)} className="text-[11px] font-bold text-[#0071e3] hover:underline">Edit</button>
                                    ) : (
                                        <button onClick={handleSaveDescription} className="text-[11px] font-bold text-[#0071e3] hover:underline">Done</button>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <textarea 
                                        value={editedSummary}
                                        onChange={(e) => setEditedSummary(e.target.value)}
                                        className="w-full h-[400px] p-4 border border-[#0071e3] rounded-xl text-[15px] leading-relaxed focus:outline-none bg-white font-sans resize-y"
                                    />
                                ) : (
                                    <div className="text-[#424245] text-[15px] leading-relaxed whitespace-pre-wrap">
                                        {job.summary}
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="text-[20px] font-bold text-[#1d1d1f]">Strategy Kit</h3>
                                <button onClick={() => onGenerateKit(job)} className="text-[13px] font-medium text-[#0071e3] hover:bg-[#f5f5f7] px-4 py-2 rounded-full transition-colors flex items-center gap-2">
                                    <Sparkles size={16} /> Regenerate
                                </button>
                            </div>

                            {analysis?.strategy ? (
                                <div className="prose prose-p:text-[#424245] prose-headings:text-[#1d1d1f] max-w-none">
                                    <div className="whitespace-pre-wrap leading-relaxed">{analysis.strategy}</div>
                                </div>
                            ) : (
                                <div className="py-20 text-center text-[#86868b]">
                                    <Sparkles size={40} className="mx-auto mb-4 animate-pulse text-[#0071e3]" />
                                    <p className="font-medium">Formulating your custom strategy...</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* RIGHT: Properties Panel */}
                <div className="w-full md:w-72 shrink-0 space-y-8 order-1 md:order-2">
                    {/* Status Dropdown */}
                    <div>
                        <label className="text-[10px] font-bold uppercase tracking-wider text-[#86868b] mb-2 block">Status</label>
                        <div className="relative">
                            <select 
                                value={job.status || 'new'}
                                onChange={handleStatusChange}
                                className="w-full appearance-none pl-4 pr-10 py-3 bg-[#f5f5f7] rounded-xl font-semibold text-[14px] text-[#1d1d1f] focus:outline-none focus:ring-2 focus:ring-[#0071e3] cursor-pointer"
                            >
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-[#86868b]" />
                        </div>
                    </div>

                    {/* Match Score */}
                    {analysis && (
                         <div>
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-[10px] font-bold uppercase tracking-wider text-[#86868b]">Match Score</span>
                                <button onClick={handleReAnalyzeClick} className={`text-[#0071e3] hover:bg-[#f5f5f7] p-1.5 rounded-full transition-all ${isAnalyzing ? 'animate-spin' : ''}`}>
                                    <RotateCw size={14} />
                                </button>
                            </div>
                            <div className="flex items-end gap-2">
                                <span className="text-5xl font-semibold text-[#1d1d1f] tracking-tight">{analysis.score}</span>
                                <span className="text-lg text-[#86868b] font-medium mb-1">/100</span>
                            </div>
                        </div>
                    )}

                    <div className="w-full h-px bg-[#f5f5f7]"></div>

                    {/* Meta Data */}
                    <div className="space-y-4">
                        <div onClick={() => setIsEditingLocation(true)} className="cursor-pointer group">
                            <span className="text-[10px] font-bold uppercase tracking-wider text-[#86868b] mb-1 block">Location</span>
                            {isEditingLocation ? (
                                <input value={editedLocation} onChange={e => setEditedLocation(e.target.value)} onBlur={handleSaveLocation} className="text-[14px] font-medium text-[#1d1d1f] border-b border-[#0071e3] outline-none w-full" autoFocus />
                            ) : (
                                <p className="text-[14px] font-medium text-[#1d1d1f] group-hover:text-[#0071e3] transition-colors flex items-center justify-between">
                                    {job.location} <Edit2 size={12} className="opacity-0 group-hover:opacity-100" />
                                </p>
                            )}
                        </div>

                        <div onClick={() => setIsEditingPostedDate(true)} className="cursor-pointer group">
                            <span className="text-[10px] font-bold uppercase tracking-wider text-[#86868b] mb-1 block">Posted</span>
                            {isEditingPostedDate ? (
                                <input value={editedPostedDate} onChange={e => setEditedPostedDate(e.target.value)} onBlur={handleSavePostedDate} className="text-[14px] font-medium text-[#1d1d1f] border-b border-[#0071e3] outline-none w-full" autoFocus />
                            ) : (
                                <p className="text-[14px] font-medium text-[#1d1d1f] group-hover:text-[#0071e3] transition-colors flex items-center justify-between">
                                    {job.postedDate || 'Unknown'} <Edit2 size={12} className="opacity-0 group-hover:opacity-100" />
                                </p>
                            )}
                        </div>
                    </div>

                    <div className="w-full h-px bg-[#f5f5f7]"></div>

                    {/* URL & Apply */}
                    <div>
                         <div className="flex items-center justify-between mb-3">
                             <span className="text-[10px] font-bold uppercase tracking-wider text-[#86868b]">Link</span>
                             <button onClick={() => setIsEditingUrl(!isEditingUrl)} className="text-[#0071e3] hover:underline text-[10px] font-bold">Edit</button>
                         </div>

                         {isEditingUrl && (
                            <input 
                                type="text"
                                value={editedUrl}
                                onChange={(e) => setEditedUrl(e.target.value)}
                                onBlur={handleSaveUrl}
                                onKeyDown={(e) => e.key === 'Enter' && handleSaveUrl()}
                                className="text-[13px] text-[#1d1d1f] w-full p-2 bg-[#f5f5f7] rounded-lg mb-3 outline-none"
                                autoFocus
                                placeholder="https://..."
                            />
                         )}

                        <a 
                            href={applyUrl} 
                            target="_blank" 
                            rel="noreferrer" 
                            className="flex items-center justify-center gap-2 w-full py-3.5 bg-[#0071e3] text-white text-[14px] font-semibold rounded-full hover:bg-[#0077ED] transition-all shadow-md shadow-blue-500/20"
                        >
                            {getAbsoluteUrl(job.url) ? 'Apply Now' : 'Google Search'} <ExternalLink size={16} />
                        </a>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

import React, { useState } from 'react';
import { X, Link, FileText, Building2, Type } from 'lucide-react';

interface AddLinkModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdd: (data: { url?: string; text?: string; title?: string; company?: string }) => void;
}

const AddLinkModal: React.FC<AddLinkModalProps> = ({ isOpen, onClose, onAdd }) => {
  const [mode, setMode] = useState<'link' | 'text'>('link');
  const [url, setUrl] = useState('');

  // Text Mode State
  const [text, setText] = useState('');
  const [manualTitle, setManualTitle] = useState('');
  const [manualCompany, setManualCompany] = useState('');
  const [manualUrl, setManualUrl] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'link' && url.trim()) {
      onAdd({ url });
      setUrl('');
      onClose();
    } else if (mode === 'text' && text.trim()) {
      onAdd({ 
          text, 
          title: manualTitle || 'Manual Job Entry', 
          company: manualCompany || 'Unknown Company',
          url: manualUrl.trim() || 'Manual Entry' 
      });
      setText('');
      setManualTitle('');
      setManualCompany('');
      setManualUrl('');
      onClose();
    }
  };

  return (
    <div 
        className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4"
        role="dialog"
        aria-modal="true"
    >
      <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-lg p-0 animate-in fade-in zoom-in-95 duration-200 overflow-hidden">

        {/* Header with Tabs */}
        <div className="bg-white px-8 pt-8 pb-4 flex items-center justify-between">
            <h2 className="text-[24px] font-semibold text-[#1d1d1f]">Add Job</h2>
            <button 
                onClick={onClose} 
                className="w-8 h-8 flex items-center justify-center bg-[#f5f5f7] hover:bg-[#e8e8ed] rounded-full text-[#1d1d1f] transition-colors"
            >
                <X size={18} />
            </button>
        </div>

        <div className="px-8 pb-6">
            <div className="flex bg-[#f5f5f7] rounded-full p-1 w-fit" role="tablist">
                <button 
                    onClick={() => setMode('link')}
                    className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${mode === 'link' ? 'bg-white text-black shadow-sm' : 'text-[#86868b] hover:text-[#1d1d1f]'}`}
                >
                    Link
                </button>
                <button 
                    onClick={() => setMode('text')}
                    className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${mode === 'text' ? 'bg-white text-black shadow-sm' : 'text-[#86868b] hover:text-[#1d1d1f]'}`}
                >
                    Text
                </button>
            </div>
        </div>

        <form onSubmit={handleSubmit} className="px-8 pb-8">
          {mode === 'link' ? (
              <div className="mb-8">
                <label htmlFor="job-url" className="block text-[11px] font-bold text-[#86868b] uppercase tracking-wider mb-2">Job URL</label>
                <div className="relative">
                    <Link className="absolute left-4 top-1/2 -translate-y-1/2 text-[#86868b]" size={18} />
                    <input 
