import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, RotateCcw, RotateCw, Wand2, Search, Type, List, X, Check, Save } from 'lucide-react';
import { improveCV } from '../services/geminiService';
import { saveCV, getCV } from '../services/firebase';

const CVEditor: React.FC = () => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');

  // AI Panel State
  const [showAiPanel, setShowAiPanel] = useState(false);
  const [aiMode, setAiMode] = useState<'impact' | 'clarify' | null>(null);
  const [selectedText, setSelectedText] = useState('');
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // Initial Load from Firestore
  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded');
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
        }
    };
    loadContent();
  }, []);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }
  }, []);

  // Debounced auto-save
  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };

      const el = editorRef.current;
      const rawInputHandler = () => {
         handleInput();
      };

      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  const initAI = (type: 'impact' | 'clarify') => {
    const selection = window.getSelection();
    const text = selection?.toString();

    if (!text || text.trim().length === 0) {
        alert("Please highlight text in your CV first.");
        return;
    }

    setSelectedText(text);
    setAiMode(type);
    setShowAiPanel(true);
    setAiSuggestion('');
    generateSuggestion(text, type);
  };

  const generateSuggestion = async (text: string, type: 'impact' | 'clarify') => {
    setIsAiLoading(true);
    try {
        const promptText = type === 'impact' 
            ? "Identify weak verbs and passive voice. Rewrite this to be action-oriented, using strong power verbs. Return ONLY the rewritten text." 
            : "Clarify this text. Remove fluff, fix grammar, and make it concise and punchy. Return ONLY the rewritten text.";

        const result = await improveCV(text, promptText);
        setAiSuggestion(result);
    } catch (e) {
        setAiSuggestion("Error generating suggestion. Please try again.");
    } finally {
        setIsAiLoading(false);
    }
  };

  const applySuggestion = () => {
      if (editorRef.current && aiSuggestion) {
          editorRef.current.focus();
          document.execCommand('insertText', false, aiSuggestion);
          saveContent();
          closeAiPanel();
      }
  };

  const closeAiPanel = () => {
      setShowAiPanel(false);
      setAiMode(null);
      setSelectedText('');
      setAiSuggestion('');
  };

  return (
    <div className="w-full h-full relative bg-[#F5F5F7] flex overflow-hidden">

        {/* Main Editor Area */}
        <div className="flex-1 h-full flex flex-col relative transition-all duration-300">

            {/* Scrollable Paper Container */}
            <div className="flex-1 w-full overflow-y-auto custom-scrollbar p-6 md:p-12 flex justify-center pb-40">
                <div 
                    ref={editorRef}
                    contentEditable
                    role="textbox"
                    aria-multiline="true"
                    aria-label="CV Content Editor"
                    className="w-full max-w-[850px] min-h-[1100px] h-max bg-white shadow-2xl border border-black/5 p-[48px] md:p-[72px] outline-none text-[#1d1d1f] font-sans text-lg leading-[1.6] rounded-sm selection:bg-[#B3D7FF]"
                />
            </div>

            {/* Floating Glass Toolbar - Absolute relative to container to prevent vanish issues */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-40 w-auto">
                <div className="flex items-center gap-3 bg-[#1d1d1f]/90 backdrop-blur-2xl px-5 py-3 rounded-full shadow-2xl border border-white/10 text-white animate-in slide-in-from-bottom-10 duration-500 scale-95 hover:scale-100 transition-transform">

                    <div className="flex items-center gap-1">
                        <button onClick={() => execCmd('undo')} className="p-2 hover:bg-white/10 rounded-full transition-colors"><RotateCcw size={16} /></button>
                        <button onClick={() => execCmd('redo')} className="p-2 hover:bg-white/10 rounded-full transition-colors"><RotateCw size={16} /></button>
                    </div>

                    <div className="w-px h-5 bg-white/20"></div>

                    <div className="flex items-center gap-1">
                        <button onClick={() => execCmd('formatBlock', 'H2')} className="p-2 hover:bg-white/10 rounded-full" title="Heading"><Type size={16} /></button>
                        <button onClick={() => execCmd('bold')} className="p-2 hover:bg-white/10 rounded-full" title="Bold"><Bold size={16} /></button>
                        <button onClick={() => execCmd('italic')} className="p-2 hover:bg-white/10 rounded-full" title="Italic"><Italic size={16} /></button>
                        <button onClick={() => execCmd('insertUnorderedList')} className="p-2 hover:bg-white/10 rounded-full" title="List"><List size={16} /></button>
                    </div>

                    <div className="w-px h-5 bg-white/20"></div>

                    <div className="flex gap-2">
                        <button 
                            onClick={() => initAI('impact')} 
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-[#0071e3] text-white rounded-full text-[11px] font-bold hover:bg-[#0077ED] transition-all"
                        >
                            <Search size={12} /> Impact
                        </button>
                        <button 
                            onClick={() => initAI('clarify')} 
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-white/10 text-white rounded-full text-[11px] font-bold hover:bg-white/20 transition-all"
                        >
                            <Wand2 size={12} /> Clarify
                        </button>
                    </div>

                     <div className="flex items-center gap-2 text-[10px] font-bold text-[#86868b] ml-2 border-l border-white/20 pl-3">
                        <Save size={12} className={lastSaved ? 'text-[#34C759]' : 'text-[#86868b]'} />
                        <span className="hidden sm:inline">{lastSaved ? 'Saved' : ''}</span>
                    </div>
                </div>
            </div>
        </div>

        {/* Right Sidebar for AI Results */}
        <div className={`fixed top-0 right-0 h-full w-[360px] bg-white shadow-2xl border-l border-[#d2d2d7] transform transition-transform duration-300 z-50 flex flex-col ${showAiPanel ? 'translate-x-0' : 'translate-x-full'}`}>
            <div className="p-5 border-b border-[#f5f5f7] flex items-center justify-between bg-white/90 backdrop-blur z-10">
                <h3 className="text-[15px] font-bold text-[#1d1d1f] flex items-center gap-2">
                    {aiMode === 'impact' ? <Search size={16} className="text-[#0071e3]" /> : <Wand2 size={16} className="text-[#0071e3]" />}
                    {aiMode === 'impact' ? 'Impact Review' : 'Clarify Text'}
                </h3>
                <button onClick={closeAiPanel} className="p-2 hover:bg-[#f5f5f7] rounded-full text-[#86868b]">
                    <X size={18} />
                </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-[#fbfbfd]">
                <div className="mb-6">
                    <label className="text-[10px] font-bold text-[#86868b] uppercase tracking-wider mb-2 block">Selected Text</label>
                    <div className="p-3 bg-white rounded-xl text-xs text-[#86868b] border border-[#d2d2d7] italic leading-relaxed">
                        "{selectedText}"
                    </div>
                </div>

                <div>
                    <label className="text-[10px] font-bold text-[#86868b] uppercase tracking-wider mb-2 block">AI Suggestion</label>
                    {isAiLoading ? (
                        <div className="flex flex-col items-center py-8 gap-3">
                            <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-[#0071e3]"></div>
                            <span className="text-[11px] text-[#86868b] font-medium">Drafting improvements...</span>
                        </div>
                    ) : (
                        <div className="p-4 bg-[#F5F9FF] rounded-xl text-[14px] text-[#1d1d1f] border border-[#0071e3]/30 shadow-sm leading-relaxed">
                            {aiSuggestion}
                        </div>
                    )}
                </div>
            </div>

            <div className="p-5 border-t border-[#f5f5f7] bg-white">
                <button 
                    onClick={applySuggestion}
                    disabled={isAiLoading || !aiSuggestion}
                    className="w-full py-3 bg-[#0071e3] text-white rounded-full text-[13px] font-bold hover:bg-[#0077ED] transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-lg shadow-blue-500/20"
                >
                    <Check size={16} /> Apply Suggestion
                </button>
            </div>
        </div>
    </div>
  );
};

